insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21441, 2, 216, 1441, 'hadith', 'عن أبي الدرداء، رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: "ألا أنبئكم بخير أعمالكم، وأزكاها عند مليككم، وأرفعها في درجاتكم، وخير لكم من إنفاق الذهب والفضة وخير لكم من أن تلقوا عدوكم فتضربوا أعناقهم، ويضربوا أعناقكم؟" قالوا: بلى، قال: "ذكر الله تعالى". رواه الترمذي وقال الحاكم أبو عبد الله إسناده صحيح.', 'The Messenger of Allah (ﷺ) said, "Shall I not inform you of the best of your actions which are the purest to your Rubb, which exalt you to the high ranks, which are more efficacious than spending gold and silver (in charity), and better for you than you should encounter your enemies whom you will smite their necks and they will smite your necks?" They said, "Certainly." He (ﷺ) said, "Remembrance of Allah the Exalted.".', 'أبي الدرداء رضي الله عنه', 'Abud-Darda (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1441', 'Riyad as-Salihin 1441', 'ریاض الصالحین 1441', null, 'سَألَ النبيُّ صلى الله عليه وسلم أصحابَه:
 

هل تريدون أن أخبركم وأعلمكم بأفضل أعمالكم وأشرفها وأنماها وأطهرها وأنقاها عند الله المالك عز وجل؟
 

وأرفعها في منازلكم في الجنة؟ 


وخير لكم من التصدُّق بالذهب والفضة؟ 


وخير لكم من أن تَلْقَوا الكفارَ للقتال، فتضربُوا أعناقَهم، ويضربوا أعناقَكم؟ 


قال الصحابة: نعم نريد ذلك. 


قال صلى الله عليه وسلم: ذكر الله تعالى في كل الأوقات وعلى جميع الهيئات والحالات.', 'أن المداومة على ذكر الله تعالى ظاهرًا وباطنًا من أعظم القُرَب، وأنفعها عند الله تعالى.
جميع الأعمال إنما شُرعت لإقامة ذكر الله تعالى، قال الله تعالى: (وَأَقِمِ الصَّلَاةَ لِذِكْرِي). وقال صلى الله عليه وسلم: إنَّما جُعل الطَّوافُ بالبيت وبين الصَّفا والمروة ورمي الجمار لإقامة ذكر الله تعالى. رواه أبو داود والترمذي.
قال العز بن عبدالسلام في قواعده: هذا الحديث مما يدل على أن الثواب لا يترتب على قدر النَّصَب في جميع العبادات بل قد يأجر الله تعالى على قليل الأعمال أكثرَ مما يأجر على كثيرها، فالثواب يترتب على تفاوت الرتب في الشرف.
قال المناوي في فيض القدير: هذا الحديث محمول على أن الذكر كان أفضل للمخاطبين به، ولو خوطب به شُجاع بَاسل حصل به نفع الإسلام في القتال لقيل له الجهاد، أو الغني الذي ينتفع به الفقراء بماله قيل له الصدقة، والقادر على الحج قيل له الحج، أو من له أبوان قيل له برهما، وبه يحصل التوفيق بين الأخبار.
أكمل الذكر ما نطق به اللسانُ مع تدبُّر القلب، ثم ما كان بالقلب وحده كالتفكر، ثم ما كان باللسان وحده، وفي كلٍّ أجرٌ إن شاء الله تعالى.
التزام المسلم بالأذكار المتعلقة بالأحوال كأذكار الصباح والمساء، ودخول المسجد والبيت والخلاء والخروج منها... وغير ذلك يجعله من الذاكرين الله كثيرًا.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3575', false),
(21442, 2, 216, 1442, 'hadith', 'عن سعد بن أبي وقاص رضي الله عنه أنه دخل مع رسول الله صلى الله عليه وسلم على امرأة وبين يديها نوى -أو حصى- تسبح به فقال: "أخبرك بما هو أيسر عليك من هذا - أو أفضل" فقال: "سبحان الله عدد ما خلق في السماء، وسبحان الله عدد ما خلق في الأرض، وسبحان الله عدد ما بين ذلك، وسبحان الله عدد ما هو خالق، والله أكبر مثل ذلك، والحمد لله مثل ذلك، ولا إله إلا الله مثل ذلك، ولا حول ولا قوة إلا بالله مثل ذلك".', 'The Messenger of Allah (ﷺ) and I went to see a woman. She had date- stones or pebbles in front of her, and she was counting and reciting Tasbih. .', 'سعد بن أبي وقاص رضي الله عنه', 'Sa''d bin Abu Waqqas (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1442', 'Riyad as-Salihin 1442', 'ریاض الصالحین 1442', 'رواه الترمذي وقال: حديث حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21443, 2, 216, 1443, 'hadith', 'عن أبي موسى رضي الله عنه قال: قال لي رسول الله صلى الله عليه وسلم: "ألا أدلك على كنز من كنوز الجنة ؟" فقلت: بلى يا رسول الله قال: "لا حول ولا قوة إلا بالله".', 'The Messenger of Allah (ﷺ) said to me, "Shall I not guide you to a treasure from the treasures of Jannah?" I said: "Yes, O Messenger of Allah!" Thereupon he (ﷺ) said, "(Recite) ''La hawla wa la quwwata illa billah'' (There is no change of a condition nor power except by Allah).".', 'أبي موسى رضي الله عنه', 'Abu Musa (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1443', 'Riyad as-Salihin 1443', 'ریاض الصالحین 1443', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21444, 2, 216, 1444, 'hadith', 'عن عائشة رضي الله عنها قالت: كان رسول الله صلى الله عليه وسلم يذكر الله تعالى على كل أحيانه. رواه مسلم.', 'The Messenger of Allah (ﷺ) used to remember Allah at all times..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', null, 'رياض الصالحين 1444', 'Riyad as-Salihin 1444', 'ریاض الصالحین 1444', null, null, null, null, 'sunnah.com', null, false, null, false),
(21445, 2, 216, 1445, 'hadith', 'عن ابن عباس رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «لو أن أحدكم إذا أتى أهله قال: بسم الله، اللهم جنبنا الشيطان وجنب الشيطان ما رزقتنا، فقضى بينهما ولد لم يضره ».', 'The Prophet (ﷺ) said, "If anyone intends to have (sexual intercourse) with his wife, he should say: "Bismillah! Allahumma janibnash-Shaitana, wa jannibish-Shaitana ma razaqtana (In the Name of Allah, O Allah! Keep us away from Satan and keep Satan away from what You have bestowed upon us);'' and if Allah has ordained a child for them, Satan will never harm him.".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1445', 'Riyad as-Salihin 1445', 'ریاض الصالحین 1445', 'متفق عليه', 'قال النبي صلى الله عليه وسلم: لو أن أحدكم إذا أراد جماع زوجته قال: "بسم الله، اللهم ‌جنبنا ‌الشيطان" أي يا الله، أبعد عنا الشيطان، "وجنب الشيطان ما رزقتنا" وباعد الشيطان عن الولد الذي سترزقنا، ذكرًا كان أو أنثى، فإن قُدِّر أن امرأته حملت من ذلك الجماع الذي قال فيه هذا الذكر، ورزقهم الله بولد لم يُسلَط عليه الشيطان بحيث يتمكن من إضراره في دينه أو بدنه، وهذا لا يمنع أن يوسوس له وأن يجاهد معه، لكن لا يضره ذلك بإذن الله..', 'استحباب التسمية والدعاء المذكور، والمحافظة على ذلك قبل الجماع.

الاعتصام بذكر الله تعالى ودعائه من الشيطان، والتبرك باسمه والاستعاذة به من جميع الشرور.

الاستشعار بأنه تعالى هو الميسر لذلك العمل الذي يستعيذ عليه، والمعين عليه.

الحث على المحافظة على تسميته تعالى، ودعائه في كل حال لم ينه الشرع عنه، حتى في حال ملاذ الإنسان.

ملازمة الشيطان لابن آدم من حين خروجه من ظهر أبيه إلى رحم أمه، إلى حين موته، وهو يجري من ابن آدم مجرى الدم.', '-', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65955', false),
(21446, 2, 216, 1446, 'hadith', 'عن حذيفة، وأبي ذر رضي الله عنهما قالا: كان رسول الله صلى الله عليه وسلم إذا أوى إلى فراشه قال: "باسمك اللهم أموت وأحيا" وإذا استيقظ قال: "الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور".', 'Whenever the Messenger of Allah (ﷺ) went to bed, he would supplicate: "Bismika-Allahumma amut wa ahya (With Your Name, O Allah, I die and return to life)"; and when he woke up, he would supplicate thus: "Al-hamdu lillahilladhi ahyana ba''da ma amatana, wa ilaihin-nushur (All praise belongs to Allah Who has restored us back to life after causing us to die; and to Him shall we return)."', 'حذيفة، وأبي ذر رضي الله عنهما', 'Hudhaifah and Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1446', 'Riyad as-Salihin 1446', 'ریاض الصالحین 1446', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21447, 2, 216, 1447, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم "إن لله تعالى ملائكة يطوفون في الطرق يلتمسون أهل الذكر، فإذا وجدوا قومًا يذكرون الله عز وجل، تنادوا: هلموا إلى حاجتكم، فيحفونهم بأجنحتهم إلى السماء الدنيا، فيسألهم ربهم - وهو أعلم: ما يقول عبادي؟ قال: يقولون: يسبحونك، ويكبرونك، ويحمدونك، ويمجدونك، فيقول: هل رأوني؟ فيقولون: لا لا والله ما رأوك، فيقول: كيف لو رأوني؟! قال: يقولون: لو رأوك كانوا أشد لك عبادة، وأشد لك تمجيدًا، وأكثر لك تسبيحًا فيقول: فماذا يسألون؟ قال: يقولون: يسألونك الجنة. قال: يقول: وهل رأوها؟ قال: يقولون: لا والله يا رب ما رأوها. قال: يقول: فكيف لو رأوها؟! قال: يقولون: لو أنهم رأوها كانوا أشد عليها حرصًا، وأشد لها طلبًا، وأعظم فيها رغبة. قال: فمم يتعوذون؟ قال يقولون: يتعوذون من النار، قال: فيقول: وهل رأوها؟ قال: يقولون: ولا والله ما رأوها. فيقول: كيف لو رأوها؟! قال: يقولون: لو رأوها كانوا أشد فرارًا، وأشد لها مخافة. قال: يقول: فأشهدكم أني قد غفرت لهم، قال: يقول ملك من الملائكة: فيهم فلان ليس منهم، إنما جاء لحاجة، قال: هم الجلساء لا يشقى بهم جليسهم" ((متفق عليه)). وفي رواية لمسلم عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: "إن لله ملائكة سيارة فضلا يتتبعون مجالس الذكر، فإذا وجدوا مجلسًا فيه ذكر، قعدوا معهم، وحف بعضهم بعضًا بأجنحتهم حتى يملئوا ما بينهم وما بين السماء الدنيا، فإذا تفرقوا عرجوا وصعدوا إلى السماء، فيسألهم الله عز وجل - وهو أعلم: من أين جئتم؟ فيقولون: جئنا من عند عباد لك في الأرض: يسبحونك، ويكبرونك، ويهللونك، ويحمدونك، ويسألونك. قال: وماذا يسألوني؟ قالوا: يسألونك جنتك. قال: وهل رأوا جنتي؟ قالوا: لا، أي رب. قال: فكيف لو رأوا جنتي؟! قالوا: ويستجيرونك. قال: ومم يستجيروني؟ قالوا: من نارك يا رب. قال: وهل رأوا ناري؟ قالوا: لا، قال: فكيف لو رأوا ناري؟ قالوا: ويستغفرونك، فيقول: قد غفرت لهم، وأعطيتهم ما سألوا، وأجرتهم ما استجاروا. قال: فيقولون: رب فيهم فلان عبد خطاء إنما مر، فجلس معهم، فيقول: وله غفرت، هم القوم لا يشقى بهم جليسهم".', 'The Messenger of Allah (ﷺ) said, "Allah, the Exalted, has teams of angels who go about on the roads seeking those who remember Allah. When they find some people remembering Allah they call to one another and say, ''Come to what you are looking for;'' and they surround them with their wings till the space between them and the lowest sky is fully covered. Allah, the Exalted and Glorious, asks them (although He is best informed about every thing): ''What are my slave saying?'' They say: ''They are glorifying Your Tasbih, Tahmid, Takbir, Tamjid, (i.e., they were declaring Your Perfectness, praising, remembering the Greatness and Majesty of Allah).'' He asks: ''Have they seen Me?'' They reply, ''No, indeed, they have not seen You.'' He asks: ''How would they act if they were to see Me?'' Thereupon they reply: ''If they were to see You, they would engage more earnestly in worshipping and glorifying You and would extol You more.'' He would say: ''What do they beg of Me?'' They say, ''They beg You for Your Jannah.'' Allah says, ''Have they seen My Jannah?'' They say, ''No, our Rubb.'' He says: ''How would they act if they were to see My Jannah?'' They reply, ''Were they to see it, they would more intensely eager for it.'' They (the angels) say, ''They seek Your Protection.'' He asks, ''Against what do they seek My Protection?'' They (the angels) say, ''Our Rubb, from the fire of Hell.'' (He, the Rubb) says, ''Have they seen the fire of Hell?'' They say, ''No. By Your Honour, they have not seen it.'' He says: ''How would they act if they were to see My Fire?'' They say: ''If they were to see it, they would more earnest in being away from it and fearing it. They beg of Your forgiveness.'' He says: ''I call you to witness that I hereby grant pardon to them and confer upon them what they ask for; and grant them protection against what they seek protection from.'' One of the angels says: ''Our Rubb, there is amongst them such and such slave who does not belong to the assembly of those who are participating in Your remembrance. He passed by them and sat down with them.'' He says: ''I also grant him pardon because they are the people by virtue of whom their associates will not be unfortunate''.".(The narration in Muslim is also the same with minor changes in wordings).', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1447', 'Riyad as-Salihin 1447', 'ریاض الصالحین 1447', null, 'يقصُّ هذا الحديث مظهرا من مظاهر تعظيم مجالس الذكر، حيث يقول النبي صلى الله عليه وسلم: 
"إن لله ملائكة يطوفون في الطُرُق يلتمسون أهل الذكر" أي أن الله كلَّف طائفة مخصوصة من الملائكة غير الحفظة للسياحة في الأرض، يدورون في طرق المسلمين ومساجدهم، ودورهم، يطلبون مجالس الذكر، يزورونها ويشهدونها ويستمعون إلى أهلها. قال الحافظ: والأشبه اختصاص ذلك بمجالس التسبيح ونحوها.
فإذا "وجدوا قوماً يذكرون الله عز وجل " وفي رواية مسلم " فإذا وجدوا مجلساً فيه ذكر تنادوا " أي نادى بعضهم بعضاً " أن هلموا إلى حاجتكم " وفي رواية إلى بغيتكم، أي تعالوا إلى ما تبحثون عنه من مجالس الذكر، والوصول إلى أهلها، لتزوروهم، وتستمعوا إلى ذكرهم.
قال عليه الصلاة والسلام في وصف الملائكة، وهم في مجالس الذكر: " فيحفونهم" أي يحيطون بهم إحاطة السوار بالمعصم.
"فيحفونهم بأجنحتهم " أي يطوفون حولهم بأجنحتهم " إلى السماء " أي حتى يصلوا إلى السماء.
ثم يقص عليه الصلاة والسلام المحاورة التي جرت بين رب العزة والجلال، وبين ملائكته الكرام:
فيقول الله جل في علاه: "فيسألهم ربُّهم وهو أعلم بهم" أي وهو أكثر علماً بأحوالهم، تنويهاً بشأنهم في الملأ الأعلى؛ ليباهى بهم الملائكة: "ما يقول عبادي؟ فتجيب الملائكة: يسبحونك، ويكبرونك، ويحمدونك ويمجدونك "، أي فتقول الملائكة: إن هؤلاء الذاكرين يقولون: سبحان الله والحمد لله، ولا إله إلاّ الله، والله أكبر، فالتمجيد هو قول لا إله إلاّ الله؛ لما فيه من تعظيم الله تعالى، بتوحيد الألوهية.
فيقول الله جل في علاه: "هَلْ رَأوْنِي؟ قَالَ: فَيَقُولُون: لا وَاللهِ مَا رَأوْكَ، قَالَ: فَيَقُولُ: فكَيْفَ لَوْ رَأوْنِي؟ "
فتجيب الملائكة الكرام: " لو رأوك كانوا أشد لك عبادة، وأشد تمجيداً وأكثر لك تسبيحاً " لأنّ الاجتهاد في العبادة على قدر المعرفة.
ثم يقول الله تبارك وتعالى: " قال: فما يسألونني؟ " أي فماذا يطلبون مني.
فتقول الملائكة:" قالوا: يسألونك الجنة " أي يذكرونك، ويعبدونك طمعاً في جنتك.
فتجيب الملائكة: "لو رأوها كانوا أشد عليها حرصاً " أي لكانوا أكثر سعياً إليها؛ لأنه ليس الخير كالمعاينة. 
فيقول الله جل جلاله" قال: فمِمَّ يتعوذون " أي فأي شيء يخافون منه، ويسألون ربهم أن يجيرهم منه. 
فتجيب الملائكة: " من النار " أي يذكرون ويعبدون ربهم خوفاً ًمن النار، ويسألونه عز وجل أن يجيرهم منها. 
فيقول الله جل جلاله: " فَكَيْفَ لَوْ رَأوْهَا؟"
فتجيب الملائكة:" لو رأوها كانوا أشد منها فراراً " أي لكانوا أكثر اجتهاداً في الأعمال الصالحة التي هي سبب في النجاة من النار. 
فيقول الله جل جلاله: " قال: فيقول: فأشهدكم أني قد غفرت لهم " أي قد غفرت لهم ذنوبهم. 
فيقول ملك من الملائكة: "فيهم فلان ليس منهم، إنَّما جاء لحاجة " أي إنه يوجد من بين هؤلاء الذاكرين" فلان": وهو ليس منهم، ولكنه جاء لحاجة يقضيها فجلس معهم، فهل يغفر له؟ فيقول الله جل في علاه ما معناه: هم الجلساء لا يشقى جليسهم ولا يخيَّب.', 'فضل مجالس الذكر والذاكرين وفضل الاجتماع على ذلك.
جليس الذاكرين الصالحين يندرج معهم في جميع ما يتفضل الله تعالى به عليهم إكراماً لهم ولو لم يشاركهم في أصل الذكر.
محبة الملائكة بني آدم واعتناؤهم بهم.
السؤال قد يصدر من السائل وهو أعلم بالمسؤول عنه من المسؤول؛ لإظهار العناية بالمسؤول عنه، والتنويه بقدره.
الذكر يتناول الصلاة، وقراءة القرآن، والدعاء، وتلاوة الحديث، ودراسة العلم الشرعي.
بيان كذب من ادعى من الزنادقة أنه يرى الله تعالى جهرة في دار الدنيا.
جواز القسم في الأمر المحقق تأكيداً له وتنويهاً به.
اشتملت الجنة من أنواع الخيرات والنار من أنواع المكروهات ما لا يخطر على قلب بشر.', 'ملائكة سيارة : سياحون في الأرض.
تنادوا : نادى بعضهم بعضاً.
هلموا : تعالوا.
فيحفونهم : يقتربون حول الذاكرين ويطوفون بهم ويدورون حولهم حتى يملؤوا ما بين السماء الدنيا والأرض.
يمجدونك : يعظمونك.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8272', false),
(21448, 2, 216, 1448, 'hadith', 'وعنه وعن أبي سعيد رضي الله عنهما قالا: قال رسول الله صلى الله عليه وسلم: «لا يقعد قوم يذكرون الله عز وجل إلا حفتهم الملائكة، وغشيتهم الرحمة ونزلت عليهم السكينة، وذكرهم الله فيمن عنده».', 'The Messenger of Allah (ﷺ) said, "When a group of people assemble for the remembrance of Allah, the angels surround them (with their wings), (Allah''s) mercy envelops them, Sakinah, or tranquillity descends upon them and Allah makes a mention of them before those who are near Him.".', null, 'Abu Hurairah and Abu Sa''id Al-Khudri (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1448', 'Riyad as-Salihin 1448', 'ریاض الصالحین 1448', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21449, 2, 216, 1449, 'hadith', 'عن أبي واقد الحارث بن عوف رضي الله عنه أن رسول الله صلى الله عليه وسلم، بينما هو جالس في المسجد، والناس معه، إذ أقبل اثنان إلى رسول الله صلى الله عليه وسلم، وذهب واحد، فوقفا على رسول الله صلى الله عليه وسلم، فأما أحدهما فرأى فرجة في الحلقة، فجلس فيها وأما الآخر، فجلس خلفهم، وأما الثالث فأدبر ذاهبًا. فلما فرغ رسول الله صلى الله عليه وسلم، قال: ألا أخبركم عن النفر الثلاثة: أما أحدهم، فأوى إلى الله، فآواه الله ، وأما الآخر فاستحيى فاستحيى الله منه، وأما الآخر، فأعرض، فأعرض الله عنه".', 'The Messenger of Allah (ﷺ) was sitting in the mosque with his Companions when three people came to him. Two of them stepped forward to the Messenger of Allah (ﷺ) and the third went away. Those two men stood by the side of Messenger of Allah (ﷺ). One of them found a space in the circle and he filled it, while the other one sat behind him. When the Messenger of Allah (ﷺ) finished, he said, "Shall I not inform you about these three people? One of them sought refuge with Allah and Allah gave him refuge; the second one felt shy and Allah showed kindness to his shyness (and so he was accommodated in that meeting), and the last one averted, and so Allah turned away His Attention from him.".', 'أبي واقد الحارث بن عوف رضي الله عنه', 'Abu Waqid Al-Harith bin ''Auf (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1449', 'Riyad as-Salihin 1449', 'ریاض الصالحین 1449', 'متفق عليه', 'في الحديث أنَّ رسول الله صلى الله عليه وسلم كان جالسا في المسجد، والناس معه، إذ أقبل ثلاثَةُ رجال، فأقبل اثنان إلى رسول الله صلى الله عليه وسلم وذهب واحد؛ فوقفا عند حلقة رسول الله صلى الله عليه وسلم ، فأما أحدهما فرأى مكاناً فارغاً في الْحَلْقَةِ فجلس فيها، والحلقة رجال جالسون على شكل دائرة أمام النبي صلى الله عليه وسلم وأما الآخر فجلس خلفهم، وأما الثالث فرجع وانصرف، فلما فرغ وانتهى رسول الله صلى الله عليه وسلم من حديثه الذي كان فيه، قال للصحابة ألا أُخْبِرُكُم عن الرجال الثلاثة: أما أحدهم فأَوَى إلى الله فآوَاهُ الله إليه أي جلس في المكان الفارغ يستمع ذكر الله فأكرمه الله بفضيلة ذلك المجلس المبارك، وأما الآخر فاسْتَحْيا فاسْتَحْيَا الله منه أي امتنع من المزاحمة؛ فجلس خلف الحلقة فلم يُمنع من بركة المجلس، وأما الآخر فأعْرَضَ، فأعرضَ اللهُ عنه أي ذهب بلا عذر فمُنع بركة المجلس.', 'استحباب الجلوس في مجالس العلم.
استحباب الجلوس في المكان الفارغ لسد الخلل.
استحباب التحلق في مجالس العلم.
بيان فضيلة الحياء وعدم مضايقة الناس إذا لم يجد مكانًا فارغًا.
إثبات صفة الحياء لله -تعالى- بما يليق به سبحانه وليست كحياء المخلوقين.
الإعراض عن مجالس العلم بغير عذر سبب في إعراض الله عن العبد.
يستحب لطالب العلم أن يجلس حيث ينتهي به المجلس إذا لم يجد فراغاً.
جواز الإخبار عن أهل المعاصي وأحوالهم للزجر عنها، وأن ذلك لا يعد من الغيبة.', 'ثلاثة نَفَر : ثلاثة رجال.
فُرْجَة : مكاناً فارغاً.
الْحَلْقَة : رجال جالسون على شكل دائرة أمام النبي -صلى الله عليه وسلم-، كالحلقة وهي كل مستدير خالي الوسط.
فأدْبر : رجع وانصرف.
أوى : جلس في المكان الفارغ يستمع ذكر الله فأكرمه الله بفضيلة ذلك المجلس المبارك.
فاسْتَحْيَا : امتنع من المزاحمة فجلس خلف الحلقة.
فاستحيا الله منه : صفة الحياء ثابتة لله تليق به -سبحانه- ولكن ليست كحياء المخلوقين، بل معناها هنا هو ترك ما ليس يتناسب مع سعة رحمته وكمال جوده وكرمه وعظيم عفوه وحلمه.
فأعرض : ذهب بلا عذر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3005', false),
(21450, 2, 216, 1450, 'hadith', 'عن أبي سعيد الخدري رضي الله عنه قال: خرج معاوية رضي الله عنه على حلقة في المسجد، فقال: ما أجلسكم؟ قالوا: جلسنا نذكر الله. قال: آلله ما أجلسكم إلا ذاك؟ قالوا: ما أجلسنا إلا ذاك، قال: أما إني لم أستحلفكم تهمة لكم، وما كان أحد بمنزلتي من رسول الله صلى الله عليه وسلم أقل حديثًا مني: إن رسول الله صلى الله عليه وسلم خرج على حلقة من أصحابه فقال: "ما أجلسكم؟" قالوا: جلسنا نذكر الله، ونحمده على ما هدانا للإسلام، ومنَّ به علينا. قال: "آلله ما أجلسكم إلا ذاك؟" قالوا: والله ما أجلسنا إلا ذلك". قال: "أما إني لم أستحلفكم تهمة لكم، ولكنه أتاني جبريل فأخبرني أن الله يباهي بكم الملائكة".', 'Mu''awiyah (May Allah be pleased with him) came to an assembly in the mosque and asked them: "What has made you sit together?" They replied, "We are sitting here to remember Allah." He said, "I adjure you by Allah to tell me whether nothing else has made you to sit together." They replied: "By Allah! We are sitting only to remember Allah." Then he said, "I did not adjure you because I suspected you. No one of my rank in the eyes of the Messenger of Allah (ﷺ) is the narrator of so few traditions as I am. The fact is that the Messenger of Allah (ﷺ) went out to a circle of his Companions and said, ''What has made you sit there?'' When they replied that they are sitting together to remember Allah and to praise Him for guiding them to Islam and bestowing favours on them, he (ﷺ) said, ''I adjure you by Allah to tell me that nothing else has made you sit together.'' On their reply that there was certainly no other purpose, he (ﷺ) said, ''I did not adjure you because I suspected you, but Jibril (Gabriel) came to me and told me that Allah was talking proudly of you to the angels."''.', 'أبي سعيد الخدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1450', 'Riyad as-Salihin 1450', 'ریاض الصالحین 1450', 'رواه مسلم', 'خَرَجَ معاويةُ بن أبي سفيان رضي الله عنهما على حلقة في المسجد، فسألهم على أي شيء اجتمعوا، 
فقالوا: نذكر الله، 
فاستحلفهم رضي الله عنه أنهم ما أرادوا بجلوسهم واجتماعهم إلا الذكر، 
فحلفوا له، 
ثم قال لهم: إني لم أستحلفكم تهمة لكم وشكًّا في صدقكم، ثم أخبر عن منزلته من النبي صلى الله عليه وسلم وأنه ما كان أحد بمنزلة قربه منه؛ لكون أم حبيبة أخته زوجة النبي صلى الله عليه وسلم، ولكونه من كتبة الوحي، ومع ذلك فهو قليل الرواية للأحاديث، 
فحدثهم أن النبي صلى الله عليه وسلم خرج يومًا من بيته، فوجدهم جالسين في المسجد يذكرون الله ويحمدونه على ما هداهم للإسلام، ومنَّ به عليهم، فسألهم صلى الله عليه وسلم واستحلفهم  بمثل ما فعل معاوية رضي الله عنه مع أصحابه، 
ثم قال لهم النبي صلى الله عليه وسلم عن سبب سؤاله لهم واستحلافهم: أنه أتاه المَلك جبريل عليه السلام فأخبره أن الله عز وجل يباهي ويفاخر بكم الملائكة، ويظهر فضلكم لهم ويريهم حسن عملكم، ويثني عليكم عندهم.', 'فضل معاوية رضي الله عنه وحرصه على الاقتداء برسول الله صلى الله عليه وسلم في تبليغ العلم.
جواز الاستحلاف من غير تهمة للتنبيه على أهمية الخبر.
فضل مجالس الذكر والعلم وأن الله يحبها ويباهي بها الملائكة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3007', false),
(21451, 2, 216, 1451, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «من قال حين يصبح وحين يمسي: سبحان الله وبحمده مائة مرة، لم يأتِ أحد يوم القيامة بأفضل مما جاء به، إلا أحد قال مثل ما قال أو زاد».', 'The Messenger of Allah (ﷺ) said, "He who recites in the morning and in the evening the statement: ''Subhan-Allahi wa bihamdihi (Allah is free from imperfection and I begin with praising Him)'' one hundred times, will not be surpassed on the Day of Resurrection by anyone with better deeds than one who utters the same words or utters more of these words.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1451', 'Riyad as-Salihin 1451', 'ریاض الصالحین 1451', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21452, 2, 216, 1452, 'hadith', 'وعنه قال: جاء رجل إلى النبي صلى الله عليه وسلم، فقال: يا رسول الله ما لقيت من عقرب لدغتني البارحة! قال: «أما لو قلت حين أمسيت: أعوذ بكلمات الله التامات من شر ما خلق لم تضرك».', 'A man came to the Prophet (ﷺ) and said, "What a trouble I suffered from a scorpion which stung me last night!" He (ﷺ) said, "Had you said in the evening: ''A''udhu bikalimatillahit-tammati min sharri ma khalaqa (I seek the protection of Allah''s Perfect Words from the evil of whatever He has created),'' it would not have harmed you.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1452', 'Riyad as-Salihin 1452', 'ریاض الصالحین 1452', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21453, 2, 216, 1453, 'hadith', 'وعنه عنه النبي، صلى الله عليه وسلم، أنه كان يقول إذا أصبح: "اللهم بك أصبحنا، وبك أمسينا، وبك نحيا، وبك نموت، وإليك النشور". وإذا أمسى قال: "اللهم بك أمسينا، وبك نحيا، وبك نموت، وإليك المصير". رواه أبو داود والترمذي وقال حديث حسن.', 'The Prophet (ﷺ) used to say in the morning: "Allahumma bika asbahna, wa bika amsaina, wa bika nahya, wa bika namutu, wa ilaikan-nushur (O Allah! With Your Power we have come to the morning, with Your Power we come to the evening, with Your Power we live, and we die, and to You will we return)." In the evening he would say: "Allahumma bika amsaina, wa bika nahya, wa bika namutu, wa ilaikan-nushur (O Allah! With Your Power, we have come to the evening, by You do we live, by You do we die, and to You is the return).".', null, 'Abu Hurairah (May Allah be pleased with him)', null, 'رياض الصالحين 1453', 'Riyad as-Salihin 1453', 'ریاض الصالحین 1453', null, null, null, null, 'sunnah.com', null, false, null, false),
(21454, 2, 216, 1454, 'hadith', 'وعنه أن أبا بكر الصديق رضي الله عنه قال: يا رسول الله مرني بكلمات أقولهن إذا أصبحت وإذا أمسيت، قال: قل: "اللهم فاطر السماوات والأرض عالم الغيب والشهادة، رب كل شيء ومليكه أشهد أن لا إله إلا أنت، أعوذ بك من شر نفسي وشر الشيطان وشركه" قال: "قلها إذا أصبحت، وإذا أمسيت، وإذا أخذت مضجعك". رواه أبو داود والترمذي وقال حديث حسن صحيح.', 'Abu Bakr asked, "O Messenger of Allah! Teach me some words so that I may recite them in the morning and in the evening." The Messenger of Allah (ﷺ) said, "Recite these words: ''Allahumma fatiras-samawati wal-ardi, ''alimal-ghaibi wash-shahadati, Rabba kulli shai''in wa malikahu. Ash- hadu an la ilaha illa Anta, a''udhu bika min sharri nafsi, wa sharrish- Shaitani wa shirkihi (O Allah! Creator of the heavens and the earth! Knower of the hidden and the exposed! Rubb of everything and every one. I bear witness that none has the right to be worshipped but You. I seek Your Protection from the evil of my own self from the evil of Satan and from the evil of Shirk to which he calls)."'' The Messenger of Allah (ﷺ) added: "Recite these words in the morning and the evening and when you go to bed.".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1454', 'Riyad as-Salihin 1454', 'ریاض الصالحین 1454', null, 'هذا الذكر من الأذكار التي تقال في الصباح والمساء، والذي علَّمها النبي صلى الله عليه وسلم أبا بكر رضي الله عنه حيث قال: علمني.
 فعلمه النبي صلى الله عليه وسلم ذكرًا ودعاءً يدعو به كلما أصبح وكلما أمسى، وأمره أن يقول: (اللهم فاطر السماوات والأرض) يعني: يا الله يا فاطر السماوات والأرض وفاطرهما، يعني أنه خلقهما عز وجل على غير مثال سبق، بل أبدعهما وأوجدهما من العدم على غير مثال سبق.
(عالم الغيب والشهادة) أي: عالم ما غاب عن الخلق وما شاهدوه؛ لأن الله تعالى يعلم الحاضر والمستقبل والماضي. 
(رب كل شيء ومليكه)، يعني: يا رب كل شيء ومليكه، والله تعالى هو رب كل شيء وهو مليك كل شيء.
(أشهد أن لا إله إلا أنت): أعترف بلساني وقلبي أنه لا معبود حق إلا أنت، فكل ما عبد من دون الله فإنه باطل لا حق له في العبودية ولا حق في العبودية إلا لله وحده عز وجل .
قوله: أ(عوذ بك من شر نفسي)؛ لأن النفس لها شرور كما قال تعالى : (وما أبرئ نفسي إن النفس لأمارة بالسوء إلا ما رحم ربي)، فإذا لم يعصمك الله من شرور نفسك فإنها تضرك وتأمرك بالسوء، ولكن الله إذا عصمك من شرها وفقك إلى كل خير.
وختم النبي -عليه الصلاة والسلام- بقوله: (ومن شر الشيطان وشِرْكه) وفي لفظ وشَرَكه، يعني: تسأل الله أن يعيذك من شر الشيطان ومن شر شِركه، أي: ما يأمرك به من الشِّرك أو شَرَكه، والشَرَك: ما يصاد به الحوت والطير وما أشبه ذلك؛ لأن الشيطان له شرَك يصطاد به بني آدم إما شهوات أو شبهات أو غير ذلك، (وأن أقترف على نفسي سوءًا)، أي: أجر على نفسي سوءًا (أو أجره إلى مسلم).
فهذا الذكر أمر النبي صلى الله عليه وسلم أبا بكر أن يقوله إذا أصبح وإذا أمسى وإذا أخذ مضجعه.', 'فضل الذكر في الصباح والمساء وهما أشرف الأوقات.
الخلق والأمر بيد الله -سبحانه وتعالى-.
الحذر من شر النفس والشيطان.
ينبغي على العبد الموفق المداومة على مثل هذه الأذكار المتضمنة لمعاني التوحيد والعبودية لله -تعالى- والمحذرة من خطورة الشيطان.', 'فاطِرَ : خالق على غير مثال سبق.
الغيبِ والشهادة : ما غاب وما يشاهد فلا يغيب عنه شيء سبحانه.
مَلِيكَه : مالكه.
شِرْكِهِ : ما يدعو إليه من الإشراك بالله .
مَضْجَعَك : مكان اضطجاعك وهو مكان نومك ورقادك.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3006', false),
(21455, 2, 216, 1455, 'hadith', 'عن ابن مسعود رضي الله عنه قال: كان نبي الله صلى الله عليه وسلم، إذا أمسى قال: أمسينا وأمسى الملك لله، والحمد لله، لا إله إلا الله وحده لا شريك له" قال الراوي: أراه قال فيهن: "له الملك وله الحمد وهو على كل شيء قدير، رب أسألك خير ما في هذه الليلة، وخير ما بعدها، وأعوذ بك من شر ما في هذه الليلة وشر ما بعدها، رب أعوذ بك من الكسل، وسوء الكبر، رب أعوذ بك من شر ما في هذه الليلة، وخير ما بعدها، وأعوذ بك من شر ما في هذه الليلة وشر ما بعدها، رب أعوذ بك من الكسل، وسوء الكبر، رب أعوذ بك من عذاب النار، وعذاب في القبر" وإذا أصبح قال ذلك أيضًا: "أصبحنا وأصبح الملك لله".', 'When it was evening, the Prophet (ﷺ) used to supplicate: "Amsaina wa amsal-mulku lillah, wal-hamdu lillah. La ''ilaha illallahu wahdahu la sharika lahu (We have entered upon evening and the whole kingdom of Allah, too, has entered upon evening. Praise is due to Allah. There is none who has the right to be worshiped but Allah, the One who has no partner with Him)." He (the narrator) said: I think that he (ﷺ) used to follow the recitation with these words: "Lahul-mulku, wa lahul-hamdu, wa Huwa ''ala kulli shi''in Qadir. Rabbi as''aluka khaira ma fi hadhihil-lailati, wa khaira ma ba''daha; wa a''udhu bika min sharri ma fi hadhihil-lailati, wa sharri ma ba''daha; Rabbi a''udhu bika minal- kasali, wa su''il-kibari; Rabbi a''udhu bika min ''adhabin fin-nari, wa ''adhabin fil-qabri (His is the sovereignty and to Him is all praise due, and He is Omnipotent. My Rubb, I beg of you good that lies in this night and good that follows it, and I seek refuge in You from the evil that lies in this night and from the evil of that which follows it. My Rubb! I seek refuge in You from lethargy and the misery of old age. O Allah! I seek Your Protection from the torment of Hell-fire and the punishment of the grave)." When it was morning, he (ﷺ) would recite the same, replacing the words: "We have entered upon evening and the whole kingdom of Allah, too, has entered upon evening" with "We have entered upon morning and the whole kingdom of Allah entered upon morning." (Replace the words "Amsaina, amsa, hadhihil-lailati, ma ba''daha with Asbahna, asbaha, hadhal-yaumi, ma ba''dahu, respectively.).', 'ابن مسعود رضي الله عنه', '''Abdullah bin Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1455', 'Riyad as-Salihin 1455', 'ریاض الصالحین 1455', 'رواه مسلم', 'كان من هديه -عليه الصلاة والسلام- عند دخول الصباح والمساء أن يقول هذه الأدعية المباركة، فقوله: (أمسينا وأمسى الملك لله) أي :دخلنا في المساء ودام الملك فيه لله مختصًا به، (والحمد لله) أي: جميع الحمد لله، أي: أمسينا وعرفنا فيه أن الملك لله وأن الحمد لله لا لغيره، (ولا إله إلا الله) أي: منفردًا بالألوهية.
قوله: (رب أسألك من خير هذه الليلة) أي ذاتها وعينها (وخير ما فيها) أي: من خير ما ينشأ ويقع ويحدث فيها وخير ما يسكن فيها، (وأعوذ بك من شرها وشر ما فيها) أي من الليالي وما فيها من شر يلحق الدين والدنيا.
(اللهم إني أعوذ بك من الكَسَل) أي التثاقل في الطاعة مع الاستطاعة، ويكون ذلك لعدم انبعاث النفس للخير مع ظهور الاستطاعة. 
(وسوء الكِبَر) بمعنى الهرم والخرف وكبر السن المؤدي إلى تساقط بعض القوى وضعفها وهو الرد إلى أرذل العمر؛ لأنه يفوت فيه المقصود بالحياة من العلم والعمل، لما يورثه كبر السن من ذهاب العقل، واختلاط الرأي والتخبط فيه، والقصور عن القيام بالطاعة وغير ذلك مما يسوء الحال، وروي بإسكان الباء بمعنى البطر أي الطغيان عند النعمة والتعاظم على الناس، (وعذاب القبر) أي من نفس عذابه أو مما يوجبه.
(وإذا أصبح) أي دخل صلى الله عليه وسلم في الصباح (قال ذلك) أي: ما يقول في المساء (أيضًا) أي لكن يقول بدل "أمسينا وأمسى الملك لله" (أصبحنا وأصبح الملك لله) ويبدل اليوم بالليلة فيقول: اللهم إني أسالك من خير هذا اليوم، ويذكر الضمائر بعده.', 'حرص النبي -صلى الله عليه وسلم -على هذا الذكر و مواظبته عليه.
استحباب هذا الذكر في الصباح والمساء.
الله -سبحانه- واحد لا شريك له في ذاته ولا صفاته ولا أفعاله ولا في ملك شيء من مخلوقاته.
الكسل وسوء الكبر تمنع العبد من الطاعة والشكر؛ لذلك يستحب أن يستعيذ بالله منهما.
إثبات عذاب القبر نسأل الله العافية.
ينبغي على العبد الاجتهاد في الطاعة وإحسان العبادة لتحصيل النجاة في الدارين.
جواز إضافة الخير والشر إلى الليل.
فيه دليل على وجود النار وعذابها.', 'قال فيهن : قال معهن.
سوء الكِبَرِ : المرض والهرم.
إذا أمسى : دخل في المساء.
أمسى الملك لله : أي استمر دوام الملك لله.
خير ما في هذه الليلة : أي خير الليلة في الدين والدنيا أما الدنيا فحصول الأمن والسلامة، وأما خير الآخرة فمثل التوفيق لقيام الليل وإحيائه بالصلاة والذكر.
الكسل : هو عدم انبعاث النفس للخير مع القدرة عليه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3008', false),
(21456, 2, 216, 1456, 'hadith', 'عن عبد الله بن خُبيب -بضم الخاء المعجمة- رضي الله عنه قال: قال لي رسول الله صلى الله عليه وسلم: «اقرأ: قل هو الله أحد، والمعوذتين حين تمسي وحين تصبح، ثلاث مرات، تكفيك من كل شيء». رواه أبو داود والترمذي وقال حديث حسن صحيح .', 'The Messenger of Allah (ﷺ) said to me, "Recite Surat Al-Ikhlas and Al- Mu''awwidhatain (Surat Al-Falaq and Surat An-Nas) three times at dawn and dusk. It will suffice you in all respects.".', 'عبد الله بن خُبيب -بضم الخاء المعجمة- رضي الله عنه', '''Abdullah bin Khubaib (May Allah be pleased with him)', null, 'رياض الصالحين 1456', 'Riyad as-Salihin 1456', 'ریاض الصالحین 1456', null, null, null, null, 'sunnah.com', null, false, null, false),
(21457, 2, 216, 1457, 'hadith', 'عن عثمان بن عفان رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «ما من عبد يقول في صباح كل يوم ومساء كل ليلة: بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم، ثلاث مرات، إلا لم يضره شيء». رواه أبو داود والترمذي وقال حديث حسن صحيح .', 'The Messenger of Allah (ﷺ) said, "He who recites three times every morning and evening: ''Bismillahil-ladhi la yadurru ma''as-mihi shai''un fil-ardi wa la fis-sama''i, wa Huwas-Sami''ul-''Alim (In the Name of Allah with Whose Name there is protection against every kind of harm in the earth or in the heaven, and He is the All-Hearing and All- Knowing),'' nothing will harm him.".', 'عثمان بن عفان رضي الله عنه', '''Uthman bin ''Affan (May Allah be pleased with him)', null, 'رياض الصالحين 1457', 'Riyad as-Salihin 1457', 'ریاض الصالحین 1457', null, null, null, null, 'sunnah.com', null, false, null, false),
(21458, 2, 216, 1458, 'hadith', 'عن حذيفة وأبي ذر رضي الله عنهما أن رسول الله صلى الله عليه وسلم كان إذا أوى إلى فراشه قال: «باسمك اللهم أحيا وأموت».', 'The Messenger of Allah (ﷺ) used to supplicate when he went to bed at night: "Bismik-Allahumma ahya wa amut (With Your Name, O Allah, I expire and return to life).".', 'حذيفة وأبي ذر رضي الله عنهما', 'Hudhaifah and Abu Dharr (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1458', 'Riyad as-Salihin 1458', 'ریاض الصالحین 1458', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21459, 2, 216, 1459, 'hadith', 'عن علي رضي الله عنه أن رسول الله صلى الله عليه وسلم قال له ولفاطمة، رضي الله عنهما: "إذا أويتما إلى فراشكما، أو: إذا أخذتما مضجعكما - فكبرا ثلاثًا وثلاثين، وسبحا ثلاثًا وثلاثين، واحمدا ثلاثًا وثلاثين" وفي رواية: التسبيح أربعًا وثلاثين" وفي رواية: "التكبير أربعًا وثلاثين".', 'The Messenger of Allah (ﷺ) said to me and to Fatimah (May Allah be pleased with her) (Ali''s wife and the Prophet''s daughter), "When you go to bed, recite: Takbir (Allahu Akbar) thirty-three times and Tasbih (Subhan-Allah) thirty-three times and Tahmid (Al-hamdu lillah) thirty-three times."Another narration is: The Messenger of Allah (ﷺ) said, "Recite Tasbih thirty-four times."Another narration is: The Messenger of Allah(ﷺ) said, "Recite Takbir thirty-four times.".', 'علي رضي الله عنه', '''Ali (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1459', 'Riyad as-Salihin 1459', 'ریاض الصالحین 1459', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21460, 2, 216, 1460, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «إذا أوى أحدكم إلى فراشه، فلينفض فراشه بداخلة إزاره فإنه لا يدري ما خلفه عليه، ثم يقول: باسمك ربي وضعت جنبي، وبك أرفعه؛ إن أمسكت نفسي فارحمها، وإن أرسلتها، فاحفظها بما تحفظ به عبادك الصالحين».', 'The Messenger of Allah (ﷺ) said, "When any of you goes to bed, he should shake off (or dust off) his bedsheet because he does not know what might have fallen on it after he had left it. Then he should recite: ''Bismika Rabbi wada''tu janbi, wa bika arfa''uhu, in amsakta nafsi farhamha, wa in arsaltaha fahfazha bima tahfazu bihi ''ibadakas-salihin .', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1460', 'Riyad as-Salihin 1460', 'ریاض الصالحین 1460', 'متفق عليه', 'يدور معنى هذا الحديث حول بيان أذكار النوم، وهي اللحظة التي يسلم الإنسان فيها روحه لربه في لحظة لا يملك فيها حولا ولا قوة، فيتركها في يد خالقها يحفظها ، ويردها مع تمام التفويض لله تعالى.
قال أهل العلم: وحكمة الذكر والدعاء عند النوم واليقظة أن تكون خاتمة أعماله على الطاعة، وأول أفعاله على الطاعة.
وفي هذا الحديث المبارك يبين لنا النبي صلى الله عليه وسلم ما يسن على العبد فعله وقوله عند النوم، فأرشدنا النبي صلى لله عليه سلم إلى الجانب الفعلي، فقال: «إذا أوى أحدكم إلى فراشه فَليَنْفُضْ" وهذا لأن العرب كانوا يتركون الفراش بحاله، فلربما دخل الفراش بعد مغادرة العبد له بعض الحشرات المؤذية، أو تلوث بالغبار ونحوه، فأمر النبي صلى الله عليه سلم بنفض الفراش قبل النوم، ثم بين النبي صلى الله عليه وسلم آلة النفض والتنظيف فقال: "فلينفض فِرَاشَهُ بِدَاخِلَةِ إزَارِهِ" والإزار: هو ما يلبس على أسفل البدن، والمقصود أي: بطرف الثياب الداخلي، لأنه أسهل للنفض، وحتى لا يصيب ظاهر الإزار شيء من القذر ونحوه، كما انه أستر للعورة، والغالب على العرب أنه لم يكن لهم ثوب غير ما هو عليهم من إزار ورداء، فالمهم هو نفض الفراش سواء كان النفض بملابس متصلة (يرتديها الشخص) أم منفصلة (لا يرتديها)، أو بما ينفض به الفراش غير ذلك.
ثم يبين النبي صلى الله عليه وسلم العلة من هذا النفض والتنظيف: "فإنَّهُ لا يدري ما خلفه عليه" وهذا يدل على حرص الشريعة على سلامة الأبدان، لأن بالأبدان قوام الأديان، وهكذا انتهت هنا السنة الفعلية مع بيان علتها.
ثانيا: السنة القولية.
ثم قال النبي صلى الله عليه وسلم: "ثم يقول: باسمك ربي" أي: باسم الله العلي العظيم أضع هذا الجسد الهامد على الفراش، وهذا يدل على استحباب مداومة الإنسان لذكر ربه في كل وقت، ثم يقول: "وضعت جنبي وبك أرفعه" أي: أني لا أضع هذا الجسد ولا أرفعه إلا مستصحبا فيها ذكرك.
ثم قال صلى الله عليه وسلم : "إن أمسكت نفسي فارحمها" كناية عن الموت.
 قوله صلى الله عليه وسلم: "وإن أرسلتها" كناية عن الحياة.
وقوله صلى الله عليه وسلم: "فاحفظها بما تحفظ به عبادك الصالحين" أي أن تحفظ نفسي وروحي بما تحفظ به عبادك، وهو حفظ عام من سائر الآثام والموبقات والشرور ، كقوله صلى الله عليه وسلم: "احفظ الله يحفظك" فهذا حفظ عام ولذا خصه بالصالحين فإن حفظ الرب تعالى لا ينال إلا بالصلاح، فليس للمفرط والمضيع حظ من حفظ الله الحفظ الخاص الذي يوليه الله تعالى لأوليائه، ولكن قد يناله شيء من الحفظ العام.', 'يستحب نفض الفراش قبل الدخول فيه ، لكيلا يكون دخل فيه شيء من المؤذيات وهو لا يشعر، ولتنظيفه مما وقع عليه من تراب أو أقذار.
حياة العبد ينبغي أن تكون مرتبطة بمنهج الله وأعماله قائمة على اسم الله -تعالى-.
التوفيق ألا يكلك الله طرفة عين، وأن يحفظك بحفظه ويرعاك برحمته، والخذلان أن يكلك الله إلى نفسك.
مَن حفظ الله حفظه الله، فالله يحفظ عباده الصالحين في أنفسهم وأموالهم وأهليهم وأبنائهم ، فاللهم احفظنا بما تحفظ به عبادك الصالحين.
الحث على الدعاء الوارد في هذا الحديث؛ لأن فيه التفويض التام لله والحصول على الهدوء النفسي والطمأنينة الفكرية مما قدر له.
الحديث يحث على نفض الفراش بغض النظر عن آلة النفض وإنما ذكر النبي صلى الله عليه وسلم الإزار؛ لأن الغالب على العرب أنه لم يكن لهم ثوب غير ما هو عليهم من إزار ورداء، فالمهم هو نفض الفراش سواء كان النفض بملابس متصلة (يرتديها الشخص) أم منفصلة (لا يرتديها)، أو بما ينفض به الفراش من آلات حديثه.
الحكمة من الأذكار والدعاء عند النوم واليقظة أن تكون خاتمة أعمال المسلم على الطاعة وأول أفعاله على الطاعة.
هذه من آداب النوم، ومن حكمة الله عز وجل ورحمته أنك لا تكاد تجد فعلا للإنسان إلا وجدته مقرونا بذكر، فاللباس له ذكر، الأكل له ذكر، الشرب له ذكر، وذلك من أجل ألا يغفل الإنسان عن ذكر الله يكون ذكر الله على قلبه دائما وعلى لسانه دائما وهذه من نعمة الله -تعالى-.', 'بداخلة إزاره : أي بالطرف الذي يلي الجسد منه.
الإزار : ثوب يحيط بالنصف الأسفل من الجسد.
خلفه عليه : ما صار بعده خلفا وبدلا بعد غيابه.
إن أمسكت نفسي : كناية عن الموت.
أرسلتها : كناية عن الإبقاء في الدنيا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6034', false),
(21461, 2, 216, 1461, 'hadith', 'عن عائشة، رضي الله عنه، أن رسول الله صلى الله عليه وسلم، كان إذا أخذ مضجعه نفث في يديه، وقرأ بالمعوذات ومسح بهما جسده. ((متفق عليه)). وفي رواية لهما: «أن النبي صلى الله عليه وسلم، كان إذا أوى إلى فراشه كل ليلة جمع كفيه، ثم نفث فيهما فقرأ فيهما: قل هو الله أحد، وقل أعوذ برب الفلق، وقل أعوذ برب الناس، ثم مسح بهما ما استطاع من جسده، يبدأ بهما على رأسه ووجهه، وما أقبل من جسده، يفعل ذلك ثلاث مرات». ((متفق عليه)). قال أهل اللغة : (( النفث )) نفخ لطيف بلا ريق', 'Whenever the Messenger of Allah (ﷺ) went to bed, he would blow upon his hands recite Al-Mu''awwidhat; and pass his hands over his body..', 'عائشة رضي الله عنه', '''A ishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1461', 'Riyad as-Salihin 1461', 'ریاض الصالحین 1461', null, 'تروي لنا أم المؤمنين زوجة نبينا صلى الله عليه وسلم في الدنيا والآخرة: هذه السنةَ النبوية الشريفة، أن رسول الله صلى الله عليه وسلم كل ليلة إذا أخذ مضجعه يضم كفيه معًا ثم ينفخ فيهما نفخًا لطيفًا بلا ريق، ويقرأ فيهما: "قل هو الله احد" و"قل أعوذ برب الفلق" ، و"قل أعوذ برب الناس"، سواء نفح أولًا ثم قرأ، أو قرأ أولا ثم نفخ لا يضر؛ لأن الحديث لا يدل على الترتيب والتعقيب، ثم يمسح بهما ما استطاع من جسده يبدأ بهما على رأسه ووجهه، وما أقبل من جسده، يفعل ذلك ثلاث مرات من القراءة والنفخ والمسح.', 'قول عائشة -رضي الله عنها-: "كان إذا أوى إلى فراشه كل ليلة" يدل على أن النبي -صلى الله عليه وسلم- كان محافظًا على ذلك.
تفاضل بعض آيات وسور القرآن على بعض، فآية الكرسي أعظم آية في كتاب الله -تعالى-، وسورة الفاتحة هي أفضل سور القرآن، والسور التي وردت في الحديث يدل على فضلها وشرفها هذا الحديث.
بيان ما للقرآن من تأثير في حفظ الإنسان بإذن الله -تعالى- من الجن وسائر الأمراض.
المسح باليد عند الرقية أقوى في النفع.
هذا الذكر مع تضمنه للحفظ وتحصين العبد فهو عبادة وقربى لله -تعالى-، وعمل صالح يختم به المسلم ليلته.
يعلمنا النبي -صلى الله عليه وسلم- في هذا الحديث بالقول والعمل ما نقوله ونفعله إذا أردنا النوم، وفي ذلك اللجوء التام لله تعالى والنجاة من كل ضرر.', 'نفث في يديه : النفث: نفخ لطيف بلا ريق.
المعوذات : المراد بها: " قل الله هو الله أحد"، و" قل أعوذ برب الفلق"، و" قل أعوذ برب الناس"، وأطلق على الثلاثة اسم "المعوذات" من باب التغليب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5879', false),
(21462, 2, 216, 1462, 'hadith', 'عن البراء بن عازب رضي الله عنهما، قال: قال لي رسول الله صلى الله عليه وسلم: «إذا أتيت مضجعك فتوضأ وضوءك للصلاة، ثم اضطجع على شقك الأيمن، وقل: اللهم أسلمت نفسي إليك، ووجهت وجهي إليك وفوضت أمري إليك، وألجأت ظهري إليك رغبة ورهبة إليك لا ملجأ ولا منجا منك إلا إليك آمنت بكتابك الذي أنزلت، وبنبيك الذي أرسلت، فإن مت، مت على الفطرة، واجعلهن آخر ما تقول».', 'The Messenger of Allah (ﷺ) said, "Whenever you intend to go to bed, perform Wudu'' as is done for Salat (prayer); and then lie down on the right side and recite: ''Allahumma aslamtu nafsi ilaika, wa fawwadtu amri ilaika, wal-ja''tu zahri ilaika, raghbatan wa rahbatan ilaika, la malja''a wa la manja minka illa ilaika, amantu bikitabik-alladhi anzalta, wa binabiyyik-alladhi arsalta .', 'البراء بن عازب رضي الله عنهما', 'Al-Bara'' bin ''Azib (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1462', 'Riyad as-Salihin 1462', 'ریاض الصالحین 1462', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21463, 2, 216, 1463, 'hadith', 'عن أنس رضي الله عنه، أن النبي صلى الله عليه وسلم، كان إذا أوى فراشه قال: «الحمد لله الذي أطعمنا وسقانا، وكفانا وآوانا، فكم ممن لا كافي له ولا مئوي».', 'Whenever the Prophet (ﷺ) went to his bed, he would say: "Al-hamdu lillah-illadhi at''amana wa saqana, wa kafana wa awana, fakam mimman la kafiya lahu wa la mu''wiya (Praise is due to Allah Who has fed us, provided us drink, satisfied us and gave us protection. Many are those who have no one to provide for them, or give them shelter).".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1463', 'Riyad as-Salihin 1463', 'ریاض الصالحین 1463', 'رواه مسلم', 'النبي صلى الله عليه وسلم كان إذا أوى إلى فراشه قال: الحمد لله الذي أطعمنا وسقانا وكفانا وآوانا فكم ممن لا كافي له ولا مؤوي. يحمد الله عز وجل الذي أطعمه وسقاه بأنه لولا أن الله عز وجل يسر لك هذا الطعام وهذا الشراب ما أكلتَ ولا شربتَ، فتحمد الله الذي أطعمك وسقاك، قوله: أطعمنا وسقانا وكفانا وآوانا كفانا يعني يسر لنا الأمور، وكفانا المؤونة وآوانا أي جعل لنا مأوى نأوي إليه فكم من إنسان لا كافي له ولا مأوى أو ولا مؤوي، فينبغي لك إذا أتيت مضجعك أن تقول هذا الذكر.', 'استحباب قول هذا الدعاء قبل النوم.
وجود مأوى ومسكن يسكن فيه الإنسان نعمة من الله -تعالى- ينبغي شكره عليها.
ذكر النبي صلى الله عليه وسلم الطعام والشراب عند النوم ؛ لأن النوم لا يحصل إلا بعد حصول الكفاية منهما.
الله تعالى هو الذي يكفي العباد شر بعض ويهيئ لهم أرزاقهم وأقواتهم.
ينبغي على العبد أن يشكر الله -تعالى- على كثرة نعمه على عبيده، وينظر إلى من هو دونه في أمور الدنيا ممن لا كافي له ولا مؤوي؛ ليعظم عنده ويعلم نعمة ربه عليه فيزداد شكرا.
ذكر النبي -صلى الله عليه وسلم- لبعض هذه النعم دعوة للعبد للتفكر ومعرفة نعم الله عليه، فإن العبد إذا عرف النعمة شكر الله عليها ، فلن يشكر العبد ربه إلا إذا عرف النعمة ، فعلى العبد التأمل والتفكر في نعم الله تعالى ، فهذا هو الذي يوصله لشكر الله تعالى.يقول ابن القيم: " قال الهروي: الشكر: اسم لمعرفة النعمة؛ لأنها السبيل إلى معرفة المنعم ؛ ولهذا سمى الله تعالى الإسلام والإيمان في القرآن شكرا، فمعرفة النعمة ركن من أركان الشكر، لأنها جملة الشكر والاعتراف بنعمة المنعم.
وضمير الجمع المتصل في قوله -صلى الله عليه وسلم-: "أطعمنا- وسقانا- وكفانا- وآوانا" إشارة إلى عموم الفضل، وعظيم الخير الذي أفاضه الله تعالى على عبيده؛ لأن جميع البشر يرفلون بنعم الله -تعالى- ويتمتعون بها ولكن الشاكر قليل.
فضيلة الحمد والشكر على النعم.', 'كفانا : أغنانا.
آوانا : ردنا إلى سكن ومأوى، ولم يجعلنا منتشرين كالبهائم.
مؤوي : راحم وعاطف، وقيل: لا وطن له ولا سكن يأوي إليه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5882', false),
(21464, 2, 216, 1464, 'hadith', 'عن حذيفة رضي الله عنه أن رسول الله صلى الله عليه وسلم، كان إذا أراد أن يرقد وضع يده اليمنى تحت خده، ثم يقول: «اللهم قني عذابك يوم تبعث عبادك».', 'Whenever the Messenger of Allah (ﷺ) intended to go to sleep, he would place his right hand under his (right) cheek and supplicate: "Allahumma qini ''adhabaka yauma tab''athu ''ibadaka (O Allah! Guard me against Your punishment on the Day when You will resurrect Your slaves).".In a narration in Abu Dawud, Hafsah (May Allah be pleased with her) said: Before going to sleep the Messenger of Allah (ﷺ) would recite this Du''a three times.', 'حذيفة رضي الله عنه', 'Hudhaifah (May Allah be pleased with him)', 'حسن', 'رياض الصالحين 1464', 'Riyad as-Salihin 1464', 'ریاض الصالحین 1464', 'رواه الترمذي وقال حديث حسن ورواه أبو داود من رواية حفصة رضي الله عنه وفيه أنه كان يقوله ثلاث مرات', null, null, null, 'sunnah.com', null, false, null, false),
(21465, 2, 217, 1465, 'hadith', 'عن النعمان بن بشير رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «الدعاء هو العبادة».', 'The Prophet (ﷺ) said, "Du''a (supplication) is worship.".', 'النعمان بن بشير رضي الله عنهما', 'An-Nu''man bin Bashir (May Allah be pleased with them)', null, 'رياض الصالحين 1465', 'Riyad as-Salihin 1465', 'ریاض الصالحین 1465', null, null, null, null, 'sunnah.com', null, false, null, false),
(21466, 2, 217, 1466, 'hadith', 'عن عائشة، رضي الله عنها، قالت: كان رسول الله صلى الله عليه وسلم، يستحب الجوامع من الدعاء، ويدع ما سوى ذلك.', 'The Messenger of Allah (ﷺ) liked comprehensive supplications or (Al-Jawami'' - i.e., supplications with very few words but comprehensive in meanings), and discarded others..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1466', 'Riyad as-Salihin 1466', 'ریاض الصالحین 1466', 'رواه أبو داود بإسناد جيد', 'كَانَ النبيُّ صلى الله عليه وسلم يَستحِبُّ الأدعية الجامعة لخير الدنيا والآخرة مما لفظه قليل ومعناه كثير، ويكون فيه الثناء على الله تعالى، والأغراض الصالحة، ويَدَعُ ما عدا ذلك.', 'استحباب الدعاء بالألفاظ اليسيرة الجامعة لمعاني الخير، وكراهة التكلف والتَّشْقِيْق في المسألة، وهو خلاف هدي النبي صلى الله عليه وسلم.
خُصّ رسول الله صلى الله عليه وسلم بجوامع الكلم.
الحرص على ما ثبت أن النبي صلى الله عليه وسلم دعا به؛ وإن كان طويلًا، وكثرت كلماته، فكلُّه من الأدعية الجامعة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5886', false),
(21467, 2, 217, 1467, 'hadith', 'عن أنس رضي الله عنه، قال: كان أكثر دعاء النبي صلى الله عليه وسلم: «اللهم آتنا في الدنيا حسنة، وفي الآخرة حسنة، وقنا عذاب النار» ((متفق عليه)). زاد مسلم في روايته قال: وكان أنس إذا أراد أن يدعو بدعوة دعا بها، وإذا أراد أن يدعو بدعاء دعا بها فيه.', 'The supplication most often recited by the Prophet (ﷺ) was: "Allahumma atina fid-dunya hasanatan, wa fil-akhirati hasanatan, wa qina ''adhab-annar (O our Rubb! give us in this world that which is good and in the Hereafter that which is good, and save us from the punishment of the Fire)."''.In the narration of Muslim it is added that whenever Anas supplicated, he used to beseech Allah with this Du''a.', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1467', 'Riyad as-Salihin 1467', 'ریاض الصالحین 1467', null, 'كانَ النبيُّ صلى الله عليه وسلم يُكْثِرُ الدعاءَ بِجَوامِعِ الدعاء، ومنها: 
"اللهم ربنا آتنا في الدنيا حسنة، وفي الآخرة حسنة، وقنا عذاب النار"،
فهو يشتمل على حسنة الدنيا من رزق هنيءٍ واسع حلال، وزوجة صالحة، وولدٍ تقَرُّ به العين، وراحة، وعلمٍ نافع، وعمل صالح، ونحو ذلك من المطالب المحبوبة والمباحة، وحسنة الآخرة من السلامة من العقوبات في القبر والموقف والنار، وحصول رضا الله، والفوز بالنعيم المُقيم، والقرب من الرب الرحيم.', 'استحباب الدعاء بالأدعية الجامعة، تأسيًا بالنبي صلى الله عليه وسلم.
الأكمل أنْ يَجمعَ الإنسانُ في دعائه بين خير الدنيا والآخرة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5502', false),
(21468, 2, 217, 1468, 'hadith', 'عن ابن مسعود، رضي الله عنه، أن النبي، صلى الله عليه وسلم، كان يقول: «اللهم إني أسألك الهدى، والتقى، والعفاف، والغنى».', 'The Prophet (ﷺ) used to supplicate: "Allahumma inni as''alukal-huda, wat-tuqa, wal-''afafa, wal-ghina (O Allah! I beseech You for guidance, piety, chastity and contentment).".', 'ابن مسعود رضي الله عنه', '''Abdullah bin Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1468', 'Riyad as-Salihin 1468', 'ریاض الصالحین 1468', 'رواه مسلم', 'سأل النبي صلى الله عليه وسلم ربه العلمَ والتوفيق للحق، وأن يُوفِّقه إلى امتثال ما أمر به وترك ما نهى عنه، وأن يعفه عن كل ما حرَّم عليه فيما يتعلق بجميع المحارم التي حرَّمها عز وجل ، وسأله كذلك الغنى عن الخلق، بحيث لا يفتقر إلى أحد سوى ربَّه عز وجل .', 'الخضوع إلى الله واللجوء إليه في كل الأحوال.
أن النبي -صلى الله عليه وسلم- لا يملك لنفسه نفعًا ولا ضرًّا، وأن الذي يملك ذلك هو الله.
إبطال التعلَّق بالأولياء والصالحين في جلب المنافع ودفع المضار.
حاجة النفس إلى مكارم الأخلاق؛ لتستقيم على أمر الله، ولتخاف عقابه وترجو رحمته.
وجوب التزام التقوى.
الكف عن مباشرة المعصية، وإن كان المكلف قد عزم على فعلها.
شرف هذه الخصال: الهدى والتقى والعفاف والغنى.', 'الهُدَى : الدلالة والرشاد، والعلم.
التُّقَى : التقوى: وهي فعل الأوامر واجتناب النواهي.
العَفَاف : الكف عما لا يحل ولا يجمل من قول أو عمل.
الغِنَى : ضد الفقر، والمراد به: غنى النفس، والاغتناء عن الناس وعما في أيديهم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3057', false),
(21469, 2, 217, 1469, 'hadith', 'عن طارق بن أشيم، رضي الله عنه، قال: كان الرجل إذا أسلم علمه النبي صلى الله عليه وسلم، الصلاة، ثم أمره أن يدعو بهؤلاء الكلمات: "اللهم اغفر لي، وارحمني، واهدني، وعافني، وارزقني" ((رواه مسلم)). وفي رواية له عن طارق أنه سمع النبي صلى الله عليه وسلم، وأتاه رجل، فقال: يا رسول الله، كيف أقول حين أسأل ربي؟ قال: "قل: اللهم اغفر لي، وارحمني، وعافني، وارزقني، فإن هؤلاء تجمع لك دنياك وآخرتك".', 'Whenever a man entered the fold of Islam, the Prophet (ﷺ) would show him how to perform Salat and then direct him to supplicate: "Allahumm-aghfir li, warhamni, wa-hdini, wa ''afini, warzuqni (O Allah! Forgive me, have mercy on me, guide me, guard me against harm and provide me with sustenance and salvation)."''.In another narration Tariq said: A man came to the Prophet (ﷺ) and said to him: "O Messenger of Allah! What shall I say if I want to pray to my Rubb?" He (ﷺ) said, "Say: ''Allahumma-ghfir li, warhamni, wa ''afini, warzuqni (O Allah! Forgive me, have mercy on me, protect me and provide me with sustenance).'' Surely, this supplication is better for you in this life and in the Hereafter."', 'طارق بن أشيم رضي الله عنه', 'Tariq bin Ashyam (May Allah be pleased with him)', null, 'رياض الصالحين 1469', 'Riyad as-Salihin 1469', 'ریاض الصالحین 1469', null, null, null, null, 'sunnah.com', null, false, null, false),
(21470, 2, 217, 1470, 'hadith', 'عن عبد الله بن عمرو بن العاص، رضي الله عنهما، قال: قال رسول الله صلى الله عليه وسلم: «اللهم مصرف القلوب صرف قلوبنا على طاعتك».', 'The Messenger of Allah (ﷺ) supplicated: "Allahumma musarrifal-qulubi, sarrif qulubana ''ala ta''atika (O Allah! Controller of the hearts, direct our hearts to Your obedience).".', 'عبد الله بن عمرو بن العاص رضي الله عنهما', '''Abdullah bin ''Amr bin Al-''As (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1470', 'Riyad as-Salihin 1470', 'ریاض الصالحین 1470', 'رواه مسلم', 'أَخْبَرَ النبيُّ صلى الله عليه وسلم أن قلوب بني آدم كلَّها بين إصبعين من أصابع الرحمن كقلب واحد؛ يُصَرِّفُه حيث يشاء؛ إن شاء أقامه على الحق، وإن شاء أَزَاغَه عن الحق، وتَصَرُّفُه في جميع القلوب كالتصرُّف في واحد لا يشغله سبحانه شَأنٌ عن شأنٍ، ثم دعا صلى الله عليه وسلم فقال: اللهم مُصَرِّفَ القلوبِ تارةً إلى الطاعة وتارةً إلى المعصية، وتارة إلى الذكر وتارة إلى الغفلة، صَرِّفْ قلوبَنا على طاعتك.', 'إثبات القَدَر، وأن الله يوجِّه قلوبَ عبادِه حسب القدر الذي كتبه عليهم.
ينبغي على المسلم إدامة سؤال ربه الثبات على الحق والهدى.
الخوف من الله والتَّعَلُّق به وحده لا شريك له.
قال الآجري: إن أهل الحق يَصِفُوْن الله عز وجل بما وصف به نفسه عز وجل، وبما وصفه به رسوله صلى الله عليه وسلم، وبما وصفه به الصحابة رضي الله عنهم، وهذا مذهب العلماء ممن اتبع ولم يَبتدِع. انتهى. فأهل السنة يُثْبِتُوْن لله ما أثبته لنفسه من الأسماء والصفات من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، ويَنْفُون عن الله ما نفاه عن نفسه، ويَسكتون عما لم يَرِدْ به نفيٌ ولا إثبات، قال الله تعالى: (‌لَيْسَ ‌كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ).', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6331', false),
(21471, 2, 217, 1471, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم، قال: «تعوذوا بالله من جهد البلاء، ودرك الشقاء، وسوء القضاء، وشماته الأعداء» ((متفق عليه)). وفي رواية: قال سفيان: أشك أني زدت واحدة منها.', 'The Prophet (ﷺ) said, "Seek refuge in Allah against the turmoils, attacks of misfortunes, and evil of judgement and joys of the enemies."  .  And in a narration Sufyan said "I suspect I added one."', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1471', 'Riyad as-Salihin 1471', 'ریاض الصالحین 1471', null, 'هذا الحديث من جوامع الكلم؛ لأن النبي صلى الله عليه وسلم استعاذ من أربعة أمور، إذا سلم منها العبد سلمت له دنياه وأخراه، وهذا هو الفوز المبين، والفلاح العظيم؛ وجوامع الكلم اختصار المعاني الكثير في كلمات يسيرة.
فقد استعاذ النبي صلى الله عليه وسلم من أربعة امور، وهي: 
"من جهد البلاء": أي شدة البلاء والجهد فيه- والعياذ بالله- لأن البلاء إذا اشتد فالإنسان لا يأمن نفسه من التبرم والضجر من أقدار الله تعالى، فيخسر بذلك العبد الدنيا والآخرة.
"ودرك الشقاء": أي اللحاق بالشقاء، وهو عام ويدخل فيه شقاء الآخرة دخولا أوليا ، لأنه الشقاء الذي لا يعقبه هناء، بخلاف شقاء الدنيا فالأيام دول، يوم لك تسر به، ويوم عليك تشقي به.
"وسوء القضاء": أي يقدر ويقع على العبد فيما لا يسره، وهو عام في كل شؤون الدنيا من: مال وولد وصحة وزوجة وغيرها، وشؤون الآخرة والمعاد.
والمراد بالقضاء هنا: المقضي، لأن قضاء الله وحكمه كله خير .
"وشماتة الأعداء": فهذا مما يتأثر به الإنسان أن يجد عدوه فرحا بمصابه، فدخول عدو الدين هو دخولا أصليا، وعدو الدنيا دخولاً ثانوياً.', 'تعليق الاستعاذة بالله تعالى يشعر بالطمأنية والأمن لقدرته سبحانه وتعالى على تحقيق العوذ، وصرف المستعاذ منه ، لأنه لا يصح التعوذ إلا بمن قدر على إزالة ما استعيذ به منه.
شفقة النبي صلى الله عليه وسلم ورحمته بأمته حيث أرشدهم إلى هذا الدعاء، فقال: " تعوذوا .." حرصًا على أمته.
استحباب الاستعاذة من الأشياء المذكورة، لأن الاستعاذة منها تدفع وقوع المكروه في الحياة الدنيا والآخرة.
الكلام المسجوع لا يكره إذا صدر عن غير قصد ولا تكلف.
فائدة الاستعاذة والدعاء: إظهار العبد حاجته وفاقته لربه العلي العظيم، وتضرعه إليه.
تعميم الخطاب في الأمر بقوله صلى الله عليه وسلم: "تعوذوا" يشير إلى أهميته، بحيث لا يختص بأحد دون أحد.', 'جهد البلاء : الحالة الشاقة.
الدرك : الإدراك واللحاق.
الشقاء : الهلاك ، ويطلق على السبب المؤدي إلى الهلاك.
سوء القضاء : يكون في أمور الدنيا، وفي أمور الآخرة، فهو عام في النفس والمال والأهل والولد والخاتمة والمعاد، والمراد بالقضاء هنا المقضي، لأن حكم الله تعالى كله حسن لا سوء فيه.
شماتة الأعداء : الشماتة: فرح العدو ببلية تنزل بمن يعاديه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6040', false),
(21472, 2, 217, 1472, 'hadith', 'وعنه قال: كان رسول الله صلى الله عليه وسلم، يقول: «اللهم أصلح لي ديني الذي هو عصمة أمري، وأصلح لي دنياي التي فيها معاشي، وأصلح لي آخرتي التي فيها معادي، واجعل الحياة زيادة لي في كل خير، واجعل الموت راحة لي من كل شر».', 'The Messenger of Allah (ﷺ) used to say: "Allahumm-aslih li diniyalladhi huwa ''ismatu amri, wa aslih li dunyaya-llati fiha ma''ashi, wa aslih li akhirati-llati fiha ma''adi, waj''alil-hayata ziyadatan li fi kulli khair, waj''alil-mauta rahatan li min kulli sharrin (O Allah, make my religion easy for me by virtue of which my affairs are protected, set right for me my world where my life exists, make good for me my Hereafter which is my resort to which I have to return, and make my life prone to perform all types of good, and make death a comfort for me from every evil).".', null, 'Abu Hurairah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1472', 'Riyad as-Salihin 1472', 'ریاض الصالحین 1472', 'رواه مسلم', 'دَعَا النبيُّ صلى الله عليه وسلم بِدُعاء جَمَعَ فيه أصولَ مَكارِمِ الأخلاقِ التي بُعِثَ لإتمامها؛ وهي صلاح الدين، والدنيا، والآخرة، فاستقى في هذا اللفظ الوجيز صلاح هذه الجوامع الثلاث، وبدأ بصلاح الدين وبه صلاحُ حالِ الدَّارَين فقال: 

(اللهم أصلح لي ديني) بأنْ توفقَني للقيام بآدابه على الوجه الأكمل الأتمّ. 

(الذي هو عصمة أمري) وحافظٌ لجميع أموري، فإنْ فَسَدَ ديني فَسَدت أموري، وخِبْتُ وخَسِرتُ، ولأنه لا يتم صلاح الدين المطلوب إلا بصلاح الدنيا فقال:

(وأصلح لي دنياي) بإعطائي صحةَ البدن والأمن، والرزق، والزوجة الصالحة، والذرية الطيبة وما أحتاج إليه، ويكون حلالًا، ومُعِيْنًا على طاعتك، ثم ذَكَرَ العُذْرَ في سؤاله إصلاحها؛ بأن قال: 

(التي فيها معاشي) ومكان عيشي وزَمَنُ حياتي.

(وأصلح لي آخرتي التي فيها معادي) وعَوْدِيْ إلى لقائك وذلك بصلاح الأعمال، وتوفيق الله للعبد على العبادة والإخلاص، وحسن الخاتمة. 

ورَتَّبَ صلى الله عليه وسلم الآخرة بعد الدنيا؛ إذ الأُولى هي وسيلة إصلاح الثانية، فمَن استقام في دنياه وِفْقَ مُرَاد الله، استقامت له آخرته وسعد فيها.

(واجعل الحياة) وطول العمر (زيادة لي في كل خير) أتكثَّر فيها من الأعمال الصالحة، (واجعل الموت) وتعجيلَه (راحة لي من كل شرٍّ) وفتنةٍ ومِحْنَةٍ وابتلاء بمعصية وغفلة، وخلاصًا من مَشَقّة الدنيا وغمومها، وحصول الراحة.', 'الدين أهمُّ شيء؛ لهذا بدأ به النبي صلى الله عليه وسلم بالدعاء.
الدين عِصْمَةٌ للإنسان يَمْنَعُه من كلّ شرٍّ.
الدعاء بالأمور الدنيوية من أجل صلاح الدين والآخرة.
لا يُكرَه تَمَنِّي الموت خوفًا من الفتنة في الدين، أو سؤال الله الموت على الشهادة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5482', false),
(21473, 2, 217, 1473, 'hadith', 'عن علي رضي الله عنه قال: قال لي رسول الله صلى الله عليه وسلم: "قل: اللهم اهدني، وسددني". وفي رواية: "اللهم إني أسألك الهدى، والسداد".', 'The Messenger of Allah (ﷺ) said to me, "Recite: ''Allahumma-hdini wa saddidni (O Allah! Direct me to the Right Path and make me adhere to the Straight Path)." Another narration is: ''Allahumma inni as''aluk-alhuda was-sadad (I beg You for guidance and uprightness).".', 'علي رضي الله عنه', '''Ali (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1473', 'Riyad as-Salihin 1473', 'ریاض الصالحین 1473', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21474, 2, 217, 1474, 'hadith', 'عن أنس رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم: يقول: "اللهم إني أعوذ بك من العجز والكسل والجبن والهرم، والبخل، وأعوذ بك من عذاب القبر، وأعوذ بك من فتنة المحيا والممات". وفي رواية: "وضلع الدين وغلبة الرجال".', 'The Messenger of Allah (ﷺ) used to supplicate: "Allahumma inni a''udhu bika minal-ajzi wal- kasali, wal-jubni wal-harami, wal-bukhli, wa a''udhu bika min ''adhabil- qabri, wa a''udhu bika min fitnatil-mahya wal-mamat .', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1474', 'Riyad as-Salihin 1474', 'ریاض الصالحین 1474', 'رواه مسلم', 'هذا الحديث يعد من جوامع الكلم، وهي أن النبي صلى الله عليه وسلم يأتي بالمعاني الجامعة في كلمات يسيرة؛ لأن النبي صلى الله عليه وسلم استعاذ فيه من جملة آفات وشرور تعوق حركة سير العبد إلى الله، فتعوذ النبي -صلى الله صلى الله عليه وسلم- من:
"العجز والكسل": وهما قرينان من معوقات الحركة؛ وعدم الفعل إما ان يكون بسبب ضعف الهمة وقلة الإراده فهو: الكسل، فالكسلان من أضعف الناس همة، وأقلهم رغبة، وقد يكون عدم الفعل لعدم قدرة العبد فهو: العجز.
و"الجبن والبخل": وهما من موانع الواجب والإحسان، فالجبن يضعف قلب الإنسان فلا يأمر بالمعروف ولا ينهى عن المنكر لضعف قلبه وتعلقه بالناس دون رب الناس.
والبخل يدعو صاحبه للإمساك في موضع الإنفاق، فلا يعطى حق الخالق من زكوات، ولا حق المخلوق من النفقات، فهو مبغوض عند الناس وعند الله.
"والهرم": هو بلوغ الشخص أرذل العمر، فالإنسان إذا بلغ أرذل العمر فقد كثيرا من حواسه، وخارت قواه، فلا يستطيع عبادة الله تعالى ، ولا يجلب لأهله نفعا.
ثم استعاذ النبي صلى الله عليه وسلم من عذاب القبر، وعذاب القبر حق، ولذا شرع لنا النبي صلى الله عليه وسلم أن نستعيذ بالله من عذابه في كل صلاة.
ثم التعوذ من فتنة المحيا والممات ليشمل الدارين، ففتنة المحيا مصائبها وابتلاءاتها، "وفتنة الممات" بأن يخشى على نفسه سوء الخاتمة وشؤم العاقبة، وفتنة الملكين في القبر وغيرهما. 
وفي رواية :" وضلع الدين وغلبة الرجال" فكلاهما من القهر، فضلع الدين شدته وثقله ولا معين له فيه، فهو قهر للرجل ولكن بحق، و"غلبة الرجال" أي: تسلطهم، وهو القهر بالباطل.', 'هذا الحديث من جوامع الكلم، لأن أنواع الرذائل ثلاثة: نفسية، وبدنية، وخارجية، والحديث مشتمل على الاستعاذة منها جميعا.
العجز والكسل قرينان: فإن تخلف مصلحة العبد وكماله ولذته وسروره إما أن يكون مصدره: أ‌-عدم القدرة، فهو عجز.ب‌-أو يكون قادرا عليه لكن تخلف لعدم إرادته، فهو الكسل، وصاحبه يلام عليه ما لا يلام على العجز.
الإحسان المتوقع من العبد: إما بماله، وإما ببدنه، فمانع الأول: بخيل، ومانع الثاني: جبان، ولذلك استعاذ النبي -صلى الله عليه وسلم- من الجبن والبخل.
إثبات عذاب القبر، ومشروعية التعوذ من فتنته.
القهر الذي ينال العبد نوعان: أ‌-قهر بحق: وهو ضلع الدين .ب‌-قهر بباطل: وهو غلبة الرجال.
اللجوء إلى الله -تعالى- طلبا للنجاة من هذه الشرور، والتحذير من الوقوع فيها.
في هذا الحديث يُعلِّم النبي -صلى الله عليه وسلم- أمته كيفية الاستعاذة بالله -تعالى- القادر القدير المقتدر، والاستعاذة بالله -تعالى- تحقق عدة فوائد من أهمها: أ-أنها عبادة محبوبة لله -تعالى-. ب-يستشعر العبد في الاستعاذة الافتقار إلى الله -تعالى- القادر في كل أمر وإن دق.ج-أنها تحقق للعبد الأمن من كل ما يخشاه.د-أنها تحقق له الأمن النفسي من خلال الشعور بالطمأنينة، وهذا الحديث يؤكد هذا المعنى.', 'الكسل : هو عدم انبعاث النفس بخير، وقلة الرغبة فيه مع إمكانه.
الجبن : الخوف وضعف القلب؛ ضد الشجاعة.
الهرم : الكِبَر والضعف، والمقصود به أن يطول عمر الإنسان وتضعف قواه حتى يصاب بالخرف بحيث لا يميز بين الأمور.
البخل : منع أداء ما يطلب أداؤه.
الفتنة : الامتحان والاختبار.
ضلع الدين : أصل الضلع: الاعوجاج، والمراد هنا: ثقل الدين وشدته بحيث لا يجد من عليه الدين وفاء ولاسيما مع المطالبة.
غلبة الرجال : شدة تسلطهم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5914', false),
(21475, 2, 217, 1475, 'hadith', 'عن أبي بكر الصديق رضي الله عنه أنه قال لرسول الله صلى الله عليه وسلم: علمني دعاء أدعو به في صلاتي، قال: "قل: اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني، إنك أنت الغفور الرحيم" ((متفق عليه)). وفي رواية: "وفي بيتي" وروي: "ظلمًا كثيرًا" وروي "كبيرًا" بالثاء المثلثة وبالباء الموحدة، فينبغي أن يجمع بينهما، فقال: كثيرًا كبيرًا.', 'I requested the Messenger of Allah (ﷺ) to teach me a supplication which I could recite in my Salat (prayer). Thereupon he said, "Recite: ''Allahumma inni zalamtu nafsi zulman kathiran, wa la yaghfirudh- dhunuba illa Anta, faghfir li maghfiratan min ''indika, warhamni, innaka Antal-Ghafur-ur-Rahim (O Allah! I have considerably wronged myself. There is none to forgive the sins but You. So grant me pardon and have mercy on me. You are the Most Forgiving, the Most Compassionate)."''.', 'أبي بكر الصديق رضي الله عنه', 'Abu Bakr As-Siddiq (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1475', 'Riyad as-Salihin 1475', 'ریاض الصالحین 1475', null, 'قال أبو بكر الصديق رضي الله عنه لرسول الله صلى الله عليه وسلم: علمني دعاء أدعو به في صلاتي، والمراد به في حالة القعود بعد التشهد قبل السلام، قال صلى الله عليه وسلم: قل: اللهم إني ظلمت نفسي ظلمًا كثيرًا، يعني بإتيان ما يوجب العقوبة، ولا يغفر الذنوب إلا أنت فيها الإشارة إلى الإقرار بأن الله هو الذي يغفر الذنوب، وليس ذلك لغيره، فاغفر لي مغفرةً من عندك، وقوله من عندك إشارة إلى التعظيم، لأن ما يكون من عنده لا يحيط به وصف الواصفين، وهو طلب مغفرة متفضل بها لا يقتضيها سبب من جهة العبد من عمل صالح وغيره، وحاصله: هب لي المغفرة، وإن لم أكن أهلًا لها بعملي، وارحمني إنك أنت الغفور الرحيم، وفي هاتين الصفتين مقابلة حسنة لأن قوله: الغفور مقابل لقوله: اغفر لي وقوله: الرحيم مقابل لقوله: ارحمني. 
وهذا الدعاء من الجوامع إذ فيه اعتراف بغاية التقصير، وهو كونه ظالما ظلما كثيرا، وطلب غاية الإنعام التي هي المغفرة والرحمة، إذ المغفرة ستر الذنوب ومحوها، والرحمة إيصال الخيرات، فالأول ينتج عنه الزحزحة عن النار، والثاني يشمل إدخال الجنة، وهذا هو الفوز العظيم.', 'طلب التعليم من العالم، ومن ذلك تعلم الدعوات المباركة.

الاعتراف بالتقصير ونسبة الظلم إلى النفس.

الاعتراف بأن الله سبحانه هو المتفضل المعطي من عنده رحمة على عباده من غير مقابلة عمل حسن.

استحباب قراءة الأدعية في آخر الصلاة.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/65461', false),
(21476, 2, 217, 1476, 'hadith', 'عن أبي موسى، رضي الله عنه، عن النبي صلى الله عليه وسلم، أنه كان يدعو بهذا الدعاء: «اللهم اغفر لي خطيئتي وجهلي، وإسرافي في أمري، وما أنت أعلم به مني، اللهم اغفر لي جدي وهزلي، وخطئي وعمدي، وكل ذلك عندي، اللهم اغفر لي ما قدمت وما أخرت، وما أسررت وما أعلنت، وما أنت أعلم به مني، أنت المقدم، وأنت المؤخر، وأنت على كل شيء قدير».', 'The Prophet (ﷺ) used to supplicate: "Allahumm-aghfir li khati''ati, wajahli, wa israfi fi amri, wa ma Anta a''lamu bihi minni. Allahumm-aghfir li jiddi wa hazli, wa khata''i wa ''amdi, wa kullu dhalika ''indi. Allahumm-aghfir li ma qaddamtu wa ma akhkhartu, wa ma asrartu, wa ma a''lantu, wa ma Anta a''lamu bihi minni. Antal-Muqaddimu, wa Antal-Mu''akhkhiru; wa Anta ''ala kulli shai''in Qadir (O Allah! Forgive my errors, ignorance and immoderation in my affairs. You are better aware of my faults than myself. O Allah! Forgive my faults which I committed in seriousness or in fun deliberately or inadvertently. O Allah! Grant me pardon for those sins which I committed in the past and I may commit in future, which I committed in privacy or in public and all those sins of which You are better aware than me. You Alone can send whomever You will to Jannah, and You Alone can send whomever You will to Hell-fire and You are Omnipotent).".', 'أبي موسى رضي الله عنه', 'Abu Musa (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1476', 'Riyad as-Salihin 1476', 'ریاض الصالحین 1476', 'متفق عليه', 'كانَ مِن أَدعية النبيِّ صلى الله عليه وسلم الجَامِعة قوله: 

"رب اغفر لي خطيئتي" وذنبي، "وجهلي" وما وَقَع مِنِّي بدون علم. 

"وإسرافي في أمري كله" وتقصيري وتَجَاوُزِيْ للحد. 

"وما أنت أعلم به مني" عَلِمْتَه أنت يا الله ونَسِيْتُه أنا. 

"اللهم اغفر لي خطاياي وعمدي" وما صَدَر عَن عَمْدٍ مني وعِلْمٍ مني بالذنوب. 

"وجدي وهزلي" وما صدر عن مُزَاح، وما وَقَع مني في الحالين. 

"وكل ذلك عندي" حيث جَمَعتْ ما ذُكِرَ من الذنوب والعيوب. 

"اللهم اغفر لي ما قدمت" فيما مضى، "وما أخرت" فيما سيأتي. 

"وما أسررت" وأخفيت، "وما أعلنت" وأظهرت. 

"أنت المقدم وأنت المؤخر" تُقدِّم من تشاء من خلقك إلى رحمتك بتوفيقك لما ترضاه، وأنت تؤخر من تشاء عن ذلك بخذلانك إياه، فلا مُقَدِّمَ لما أخرت، ولا مؤخِّرَ لما قدمت من الأمور. 

"وأنت على كل شيء قدير" كامل القدرة تام الإرادة، الفعال لكل ما تشاء.', 'فضيلة هذا الدعاء، والحرص عليه اقتداء بالنبي صلى الله عليه وسلم.
النهي عن الإسراف وأنَّ المسرف مُعَرَّض للعقوبة.
الله تعالى أعلم بالإنسان من نفسه، فعليه أنْ يُفَوِّض أمرَه إلى الله؛ لأنه قد يخطئ وهو لا يدري.
الإنسان قد يُؤاخَذ على هَزْلِهِ كما يُؤاخذ على جِدِّه، فيجب على الإنسان أنْ يَحْتَرِس في مُزاحِه.
قال ابن حجر العسقلاني: لم أَرَ في شيءٍ من طُرُقه محل الدعاء بذلك، وقد وقع معظم آخره… كان يقوله في صلاة الليل، ووقع أيضًا أنه كان يقوله في آخر الصلاة، واختلفت الرواية هل كان يقوله قبل السلام أو بعده؟ بكلامها وَرَدَ.
هل النبيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يخطئ ليستغفر؟ قيل بأنه قاله متواضعًا وهَضْمًا لنفسه، أو عَدَّ فَواتَ الكمال وترك الأولى ذنوبًا، أو أراد ما كان عن سهو، أو ما كان قبل النبوة، وقيل: الاستغفار تَعَبُّدٌ يجب أتيانه، لا للمغفرة، بل تعبدًا، وقيل: ذلك تنبيه وتعليمٌ لأمته؛ كي لا يأمنوا ويتركوا الاستغفار.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5483', false),
(21477, 2, 217, 1477, 'hadith', 'عن عائشة، رضي الله عنها، أن النبي صلى الله عليه وسلم، كان يقول في دعائه: «اللهم إني أعوذ بك من شر ما عملت ومن شر ما لم أعمل».', 'The Prophet (ﷺ) used to supplicate (in these words): "Allahumma inni audhu bika min sharri ma ''amiltu, wa min sharri ma lam a''mal (O Allah! I seek refuge in You from the evil of that which I have done and the evil of that which I have not done).".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her)', 'صحيح', 'رياض الصالحين 1477', 'Riyad as-Salihin 1477', 'ریاض الصالحین 1477', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21478, 2, 217, 1478, 'hadith', 'عن ابن عمر رضي الله عنه الله عنهما قال: كان من دعاء رسول الله صلى الله عليه وسلم: «اللهم إني أعوذ بك من زوال نعمتك، وتحول عافيتك، وفجاءة نقمتك، وجميع سخطك».', 'The Messenger of Allah (ﷺ) used to supplicate thus: "Allahumma inni a''udhu bika min zawali ni''matika, wa tahawwuli ''afiyatika, wa fuja''ati niqmatika, wa jami''i sakhatika (O Allah! I seek refuge in You against the declining of Your Favours, passing of safety, the suddenness of Your punishment and all that which displeases You).".', 'ابن عمر رضي الله عنه', '''Abdullah bin ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1478', 'Riyad as-Salihin 1478', 'ریاض الصالحین 1478', 'رواه مسلم', 'اسْتَعاذَ النبيُّ صلى الله عليه وسلم مِن أربعةِ أمور: 

الأول: (اللهم إني أعوذ بك من زوال نعمتك) الدينيّة والدنيويّة وأنْ أَثْبُتَ على الإسلام، وأبْتَعِدَ عن الوقوع في المعاصي التي تُزيل النِّعَم. 

الثاني: (وتَحَوُّل عافيتك) بتبديلِها إلى البلاء؛ فأسألك دوام العافية، والسلامة من الآلام والأسقام. 

الثالث: (وفجأة نقمتك) من بلاء أو مصيبة، فالنقمة والعقوبة إذا جاءت فجأة وبَغْتَة، لم يكن هناك زمانٌ للتوبة والاستدراك، وكان المُصاب بها أعظمَ وأشدَّ. 

الرابع: (وجميع سخطك) والأسباب المُوجِبَة لغضبك؛ فإنَّ مَن سَخِطْتَ عليه فَقَد خاب وخَسِر. 

وقد أتى صلى الله عليه وسلم بلفظ الجَمْع؛ لِتشمَلَ جميعَ أسبابِ سَخَطِهِ سبحانه وتعالى من الأقوال والأعمال والاعتقادات.', 'افتقار النبيِّ صلى الله عليه وسلم إلى الله تعالى.
تضمّنت هذه الاستعاذة المباركة: التوفيق لشكر النِّعم، والحفظ من الوقوع في المعاصي؛ لأنها تزيل النعم.
الحرص عن الابتعاد عن مواضع سَخَطِ الله تعالى.
استعاذ صلى الله عليه وسلم من فجأة نقمة الله تعالى؛ لأنه إذا انتقم من العبد فقد أَحَلَّ به من البلاء ما لا يَقدِر على دفعه، ولا يُستدفع بسائر المخلوقين، وإن اجتمعوا جميعًا.
استعاذ صلى الله عليه وسلم من تحول عافيته سبحانه؛ لأنه إذا كان قد اختصَّه الله بعافيته، فقد ظفر بخير الدارين، فإن تحولت عنه فقد أصيب بشر الدارين، فإن العافية بها صلاح الدِّين والدنيا.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5488', false),
(21479, 2, 217, 1479, 'hadith', 'عن زيد بن أرقم رضي الله عنه قال: كان رسول الله صلى الله عليه وسلم، يقول: «اللهم إني أعوذ بك من العجز والكسل، والبخل والهرم، وعذاب القبر، اللهم آت نفسي تقواها، وزكها أنت خير من زكاها، أنت وليها ومولاها، اللهم إني أعوذ بك من علم لا ينفع ومن قلب لا يخشع، ومن نفس لا تشبع، ومن دعوة لا يستجاب لها».', 'The Messenger of Allah (ﷺ) would supplicate: "Allahumma inni a''udhu bika minal-''ajzi wal-kasali, wal-bukhli wal-harami, wa ''adhabil-qabri. Allahumma ati nafsi taqwaha, wa zakkiha Anta khairu man zakkaha, Anta waliyyuha wa maulaha. Allahumma inni a''udhu bika min ''ilmin la yanfau'', wa min qalbin la yakhsha''u, wa min nafsin la tashba''u, wa min da''watin la yustajabu laha'' .', 'زيد بن أرقم رضي الله عنه', 'Zaid bin Arqam (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1479', 'Riyad as-Salihin 1479', 'ریاض الصالحین 1479', 'رواه مسلم', 'كان من دعاء النبي صلى الله عليه وسلم «اللهم إني أعوذ بك» والتجاء إليك، «من العجز» بعدم القدرة على الحيلة النافعة، «والكسل» بعدم وجود إرادة الفعل، فالعاجز لا يستطيع الحيلة، والكسلان لا يريدها، «والجبن» بالامتناع عن الإقدام على ما ينبغي فعله، «والبخل» بمنع ما يجب بذله، «والهرم» وكبر السن الذي يؤدي إلى ضعف البدن، «وعذاب القبر» والأسباب التي تؤدي إلى ذلك. 

«اللهم آت نفسي» وأعطها ووفقها لـ «تقواها» بفعل الطاعة وترك المعصية، «وزكها» وطهرها من الرذائل والأخلاق الدنيئة، «أنت خير من زكاها» ولا مزكي لها أحد سواك، «أنت وليها» وناصرها والقائم بها، «ومولاها» متولي أمورها، وربها ومالكها والمنعم عليها. 

«اللهم إني أعوذ بك من علم لا ينفع»، كعلم النجوم والكهانة والسحر، أو ما لا ينفع في الآخرة، أو علم لا يعمل به، «ومن قلب لا يخشع» لك، ولا يخضع، ولا يسكن، ولا يطمئن بذكرك، «ومن نفس لا تشبع» ولا تقنع بما أعطاها الله ورزقها من الحلال الطيب، «ومن دعوة» مردودة «لا يستجاب لها».', 'استحباب الاستعاذة من هذه الأمور المذكورة في الحديث.
الحث على التقوى ونشر العلم والعمل به.
العلم النافع هو الذي يزكي النفس ويولد فيها خشية الرب تبارك وتعالى، فتسري منها إلى سائر الجوارح.
القلب الخاشع هو الذي يخاف ويضطرب عند ذكر الله ثم يلين ويطمئن.
ذم الحرص على الدنيا وعدم الشبع من شهواتها وملاذها، ولذلك فالنفس المنهومة الحريصة على متاع الدنيا أعدى أعداء المرء، ولذلك استعاذ منها رسول الله صلى الله عليه وسلم.
ينبغي على العبد أن يفارق أسباب رد الدعاء وعدم إجابته.
قال النووي: هذا الحديث وغيره من الأدعية المسجوعة دليل لما قاله العلماء؛ أن السجع المذموم في الدعاء هو المتكلف، فإنه يذهب الخشوع والخضوع والإخلاص، ويلهي عن الضراعة والافتقار وفراغ القلب، فأما ما حصل بلا تكلف ولا إعمال فكر لكمال الفصاحة ونحو ذلك، أو كان محفوظًا فلا بأس به، بل هو حسن.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5878', false),
(21480, 2, 217, 1480, 'hadith', 'عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم، كان يقول: "اللهم لك أسلمت، وبك آمنت، وعليك توكلت، وإليك أنبت وبك خاصمت، وإليك حاكمت، فاغفر لي ما قدمت، وما أخرت وما أسررت وما أعلنت، أنت المقدم، وأنت المؤخر، لا إله إلا أنت" زاد بعض الرواة: "ولا حول ولا قوة إلا بالله".', 'The Messenger of Allah (ﷺ) used to supplicate: "Allahumma laka aslamtu, wa bika amantu, wa ''alaika tawakkaltu, wa ilaika anabtu, wa bika khasamtu, wa ilaika hakamtu. Faghfir li ma qaddamtu, wa ma akh-khartu, wa ma asrartu wa ma a''lantu, Antal-Muqaddimu, wa Antal-Mu''akhkhiru, la ilaha illa Anta (O Allah! to You I submit, in You I affirm my faith, in You I repose my trust, to You I turn in repentance and with Your Help I contend my adversaries and from You I seek judgement. O Allah! Grant me forgiveness for the faults which I made in past and those ones I may commit in the future, those which I committed secretly or openly. You Alone send whomever You will to Jannah, and You Alone send whomever You will to Hell-fire. There is none worthy of worship except You)." Another narration adds: "La hawla wa la quwwata illa billah (There is no strength to resist evil and no power to do good except through Allah).".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1480', 'Riyad as-Salihin 1480', 'ریاض الصالحین 1480', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false)
