insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21601, 2, 218, 1601, 'hadith', 'وعنه أنه مر بفتيان من قريش قد نصبوا طيرًا وهم يرمونه، وقد جعلوا لصاحب الطير كل خاطئة من نبلهم، فلما رأوا ابن عمر تفرقوا، فقال ابن عمر: من فعل هذا؟ لعن الله من فعل هذا، إن رسول الله صلى الله عليه وسلم لعن من اتخذ شيئًا فيه روح غرضًا. ((متفق عليه)). «الغَرَض» : بفتح الغين المعجمة والراء، وهو الهدف، والشيء الذي يرمى إليه.', 'I happened to pass by some lads of the Quraish who had tied a bird at which they have been shooting arrows. Every arrow that they missed came into the possession of the owner of the bird. No sooner had they seen Ibn ''Umar, they dispersed. Thereupon, Ibn ''Umar said: "Who has done this? May Allah curse him who has done so. Verily, the Messenger of Allah (ﷺ) has cursed anyone who makes a live thing the target (of one''s marksmanship).".', null, 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1601', 'Riyad as-Salihin 1601', 'ریاض الصالحین 1601', null, 'يخبر سعيد بن جُبير أن ابن عمر رضي الله عنهما مر بفتيان بقريش وقد وضعوا طائرًا يرمون عليه سهامهم، أيهم أشد إصابة، فلما رأوا عبد الله بن عمر رضي الله عنه تفرقوا هربًا منه، ثم قال: ما هذا؟ فأخبروه، فقال: لعن الله من فعل هذا، وذكر أن النبي صلى الله عليه وسلم لعن من اتخذ شيئا فيه الروح غرضا.
وهذا لأنه يتألم إذ أن هذا يضربه على جناحه، وهذا يضربه على صدره، وهذا يضربه على ظهره، وهذا على رأسه فيتأذى إذا لم يمت، وهو مقدور على تذكيته، فلهذا لعن النبي صلى الله عليه وسلم من اتخذ شيئًا فيه الروح غرضًا.', 'أن تعذيب الحيوان من غير سبب شرعي من الكبائر.
جواز لعن من اتخذ شيئًا فيه الروح غرضًا.
وجوب الأمر بالمعروف والنهي عن المنكر في وقته, وعدم تأخير البيان عن وقت الحاجة.
حرمة تضييع المال, لأن الطير إذا مات حرم أكل لحمه.
تحريم اللهو الباطل الذي لا يعود على الأمة بفائدة.
أن الدين الإسلامي كما يرحم الإنسان يرحم الحيوان.
سمو هذه الشريعة وشمولها حيث أوجبت الشفقة على الناس وعلى البهائم, وحرمت كل ما فيه إيذاء أو تعذيب.
وجوب الرفق بالحيوان.', 'نَصَبُوا طَيْرًا : جعلوه هدفًا لنبلهم.
كل خاطئة من نبلهم : كل نبلة لم تصب الهدف.
لعن : اللعن: هو الطرد والإبعاد عن الخير، وعن رحمة الله -تعالى-.
غرضا : الغرض: بفتح الغين المعجمة، والراء وهو الهدف، والشيء الذي يرمى إليه.والمراد: لا تتخذوا الحيوان الحي غرضًا ترمون إليه، والنهي يقتضي التحريم؛ فإنه تعذيبٌ للحيوان.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/64654', false),
(21602, 2, 218, 1602, 'hadith', 'عن أنس رضي الله عنه قال: نهى رسول الله صلى الله عليه وسلم أن تُصبر البهائم. ((متفق عليه)). ومعناه: تحبس للقتل.', 'The Messenger of Allah (ﷺ) forbade animals being tied (as targets)..', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', null, 'رياض الصالحين 1602', 'Riyad as-Salihin 1602', 'ریاض الصالحین 1602', null, null, null, null, 'sunnah.com', null, false, null, false),
(21603, 2, 218, 1603, 'hadith', 'عن أبي علي سويد بن مقرن رضي الله عنه قال: لقد رأيتني سابع سبعة من بني مقرن ما لنا خادم إلا واحدة لطمها أصغرنا فأمرنا رسول الله صلى الله عليه وسلم أن نعتقها. ((رواه مسلم)). ورواية: «سابع إخوة لي».', 'I was the seventh child of Banu Muqarrin and we had only one slave-girl. When the youngest of us once happened to slap her (on the face) the Messenger of Allah (ﷺ) ordered us to set her free..', 'أبي علي سويد بن مقرن رضي الله عنه', 'Abu Ali Suwaid bin Muqarrin (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1603', 'Riyad as-Salihin 1603', 'ریاض الصالحین 1603', null, 'يخبر سويد بن مقرن فيقول كنت واحدًا من سَبْعة إخوة من بَني مُقَرِّنٍ كلهم صحابة مهاجرون، لم يشاركهم أحدٌ في ذلك: وهو اجتماع سبعة من الإخوة في الهجرة، وليس لنَا من يقوم على خِدمتنا نحن السَبْعة إلا مملوكة واحدة.، فضَربها أصغرنا على خَدِّها.
فأمرنا صلى الله عليه وسلم أن نحررها من العبودية؛ ليكون اعتاقها كفَّارة عن ضَرِبها.', 'غلظ تعذيب المملوك والاعتداء عليه.
وجوب الرفق بالمملوك والإحسان إليه.
يُندب إعتاق المملوك كَفَّارة عن ضَربه أو تعذيبه.
مشروعية المبادرة بالحَسنة بعد السيئة، وفي الحديث: "وأَتْبِعِ السَيئة الحسنة تَمْحُها".
جواز الاشتراك في المملوك للخدمة، ولو كثر عدد المشتركين لكن لا يكلف فوق ما يطيق.
حرص الإسلام على حقوق العامل وحقوق الإنسان عمومًا.', 'لَطَمَهَا : ضرب خدَّها.
رأيتني : علمتني.
فيعتقها : العتق تحرير الرقاب يعني أن يكون هناك إنسان مملوك فيخلصه سيده ويجعله حرًّا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8894', false),
(21604, 2, 218, 1604, 'hadith', 'عن أبي مسعود البدري رضي الله عنه قال: "كنتُ أضرب غلامًا لي بالوسط، فسمعت صوتًا من خلفي: "اعلم أبا مسعود" فلم أفهم الصوت من الغضب، فلما دنا مني إذا هو رسول الله صلى الله عليه وسلم فإذا هو يقول: "اعلم أبا مسعود أن الله أقدرُ عليك منك على هذا الغلام" فقلت: لا أضرب مملوكًا بعده أبدًا.', 'I was beating my slave with a whip when I heard a voice behind me which said: "Abu Mas''ud! Bear in mind..." I did not recognize the voice for the intense anger I was in. Abu Mas''ud added: As he came near me, I found that he was the Messenger of Allah (ﷺ) who was saying, "Abu Mas''ud! Bear in mind that Allah has more dominance upon you than you have upon your slave." Then I said: "I will never beat any slave in future."Another narration is: The whip dropped from my hand in awe of the Prophet (ﷺ).Still another narration is: I said: "He is free for the sake of Allah." He (ﷺ) said, "If you had not done this, you would have been scorched by the Fire.".', 'أبي مسعود البدري رضي الله عنه', 'Abu Mas''ud Al-Badri (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1604', 'Riyad as-Salihin 1604', 'ریاض الصالحین 1604', 'وفي رواية: فسقط السوط من يدي من هيبته)) ((وفي رواية: فقلت: يارسول الله هو حر لوجه الله تعالى، فقال: "أما لو لم تفعل، للفحتك النار، أو لمستك النار" ((رواه مسلم بهذه الروايات', 'كان أبو مسعود رضي الله عنه يَضرب غلامه بالسَّوط، فسمع صوتا يَزجره عن خلفه، فلم يُمَيِّز صوت القائل، فلما اقترب منه علم أنه صوت رسول الله صلى الله عليه وسلم ، فإذا هو يذكره بقدرة الله عز وجل بقوله: «اعلم أبَا مسعود أن الله أقْدَرُ عليك مِنْك على هذا الغُلام».
فلما سمع كلام النبي صلى الله عليه وسلم وتحذيره من التعدي على الضعيف، سقط السَّوط من يده هيبة لرسول الله صلى الله عليه وسلم ، والتزم للنبي صلى الله عليه وسلم أن لا يَتعدى على مملوك بعد هذا أبدا.
وبعد أن سمع ما سمعه من النبي -صلى الله عليه و سلم- من زجر وتحذير، ما كان منه رضي الله عنه إلا أن أعتقه كفارة عن ضرب، فقال صلى الله عليه وسلم : لو لم تعتقه لأصابتك النار يوم القيامة لسوء فعلتك.', 'الرفق بالخدم والمماليك إذا لم يذنبوا، أما إذا أذنبوا فقد رخَص الشرع بتأديبهم بِقَدِر إثمهم.
هيبة النبي -صلى الله عليه وسلم- في نفوس أصحابه.
انقياد الصحابة والتزامهم بإرشاداته وتوجيهاته -صلى الله عليه وسلم-.
عِتق المملوك كفارة لضربه.
أن الصحابة غير معصومين من الأخطاء.
بيان رحمة النبي -صلى الله عليه وسلم-.
أن تعذيب المملوك مُستوجب للنار.', 'فلمَّا دَنَا : أي اقترب.
السَّوط : ما يُضرب به من جلد.
هَيْبَتِه : مخَافته.
للَفَحَتْكَ النَّار : أصابتك بِحَرِّها ووهَجِها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8887', false),
(21605, 2, 218, 1605, 'hadith', 'عن ابن عمر رضي الله عنهما أن النبي صلى الله عليه وسلم قال: «من ضرب غلامًا له حدًا لم يأتهِ، أو لطمه، فإن كفارته أن يعتقه».', 'The Prophet (ﷺ) said, "The expiation for beating or slapping a slave on the face for something he has not done is to set him free.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them)', 'صحيح', 'رياض الصالحين 1605', 'Riyad as-Salihin 1605', 'ریاض الصالحین 1605', 'رواه مسلم', 'من ضرب غلامًا مملوكًا له بلا ذنب يستحق معه العقوبة و لم يفعل الغلام ما يُوجب حَدَّه فإن كفَّارة تلك المعصية أن يُعْتِقَه.', 'الحثُّ على الرفق بالمماليك، وحسن صحبتهم.
جواز إقامة الحدِّ على المملوك من قبل سيده إذا كان الحد جلدًا.
عِتق المملوك كفَّارة على ضَربه.
اهتمام الإسلام بحقوق الإنسان قبل التشريعات الغربية.', 'حَدًّا : الحدُّ: الذَّنْب المقتضي للعقوبة.
لَطَمَه : ضربه بيده على وجهه.
كَفارَتَه : الكَفَّارة: العمل الذي يَسْتُر الذَّنْب ويَمْحُوه.
يعتقه : العتق هو تحرير الرقاب يعني أن يكون هناك إنسان مملوك فيخلصه سيده ويجعله حرًّا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8895', false),
(21606, 2, 218, 1606, 'hadith', 'عن هشام بن حكيم بن حزام رضي الله عنه أنه مر بالشام على أناس من الأنباط، وقد أقيموا في الشمس، وصُب على رءوسهم الزيت فقال: ما هذا؟ يُعذبون في الخراج وفي رواية: حُبسوا في الجزية. فقال هشام: أشهد لسمعت رسول الله صلى الله عليه وسلم يقول: "إن الله يعذب الذين يعذبون الناس في الدنيا" فدخل على الأمير، فحدثه، فأمر بهم فخلوا".', '"What is the matter?" He was told that they had been detained for the non-payment of Jizyah. (Another narration says that they were being tortured for not having paid Al-Kharaj). Thereupon Hisham said: "I bear testimony to the fact that I heard the Messenger of Allah (ﷺ) saying, ''Allah will torment those who torment people in the world."'' Then he proceeded towards their Amir and reported this Hadith to him. The Amir then issued orders for their release..', 'هشام بن حكيم بن حزام رضي الله عنه', 'It has been narrated that Hisham bin Hakim bin Hizam (May Allah be pleased with them) happened to pass by some (non-Arab) farmers of Syria who had been made to stand in the sun, and olive oil was poured on their heads. He said:', 'صحيح', 'رياض الصالحين 1606', 'Riyad as-Salihin 1606', 'ریاض الصالحین 1606', 'رواه مسلم. "الأنباط" الفلاحون من العجم', null, null, null, 'sunnah.com', null, false, null, false),
(21607, 2, 218, 1607, 'hadith', 'عن ابن عباس رضي الله عنهما قال: رأى رسول الله صلى الله عليه وسلم حمارًا موسوم الوجه، فأنكر ذلك؟ فقال: والله لا أسمه إلا أقصى شيء من الوجه، وأمر بحماره، فكوي في جاعرتيه، فهو أول من كوى الجاعرتين. ((رواه مسلم)).((الجاعرتان)): ناحية الوركين حول الدبر.', 'The Messenger of Allah (ﷺ) saw an ass which had been branded on the face. He disapproved of it. Upon this Ibn ''Abbas (May Allah be pleased with them) said, "By Allah, I shall not brand (the animal) but on a part at a distance from the face." Ibn ''Abbas (May Allah be pleased with them) then commanded branding on the hips; he was the first person to brand the animals on hips..', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1607', 'Riyad as-Salihin 1607', 'ریاض الصالحین 1607', null, 'معنى الحديث: رأى -عليه الصلاة والسلام- حمارًا قد كُوي في وجهه، فأنكر ذلك، والوسم هو عبارة عن كي يكوي الحيوان ليكون علامة، يتخذ أهل المواشي علامة لهم، كل قبيلة لها وسم معين إما شرطتان أو شرطة مربعة أو دائرة أو هلال، المهم أن كل قبيلة لها وسم معين، والوسم هذا يحفظ الماشية إذا وجدت ضالة يعني ضائعة عرف الناس أنها لهؤلاء القبيلة فذكروها لهم.
"فقال" أي العباس بن عبد المطلب رضي الله عنه كما هو مُصَرَّح به في رواية ابن حبان في صحيحه عن ابن عباس رضي الله عنهما "أن العباس، وسَم بعيرًا أو دابة في وجهه، فرآه النبي صلى الله عليه وسلم فغضب، فقال عباس: لا أسِمْه إلا في آخره، فوسَمَه في جَاعِرَتَيْه".
و بعد أن عَلِم بالنهي، حلف أن لا يَسِم حمارًا إلا في أقْصَى شيء من وجهه، وفي رواية ابن حبان السابقة: "لا أسمه إلا في آخِره فوسَمَه في جَاعِرَتَيْه" 
ثم أمر بحماره فوُسِم في جَاعِرَتَيْهِ، وهي مؤخرته، حيث مَضْرَب الحيوان بِذَنَبِه على فَخِذه. 
قال النووي رحمه الله : "وإذا وُسِمَ فيستحب أن يَسِمَ الغنم في آذانها والإبل والبقر في أصول أفخاذِها؛ لأنه موضع صَلْبٌ فيقل الألم فيه ويَخِفُ شعره ويظهر الوَسْم وفائدة الوَسْم تمييز الحيوان بعضه من بعض" فالعباس رضي الله عنه أول من وسَمَ حماره في مؤخرته.', 'النهي عن وسْمِ الحيوان في وجهه.
فضل العباس -رضي الله عنه- وطاعته لنهي رسول الله -صلى الله عليه وسلم- عن وسم الحيوان في الوجه.
فيه جواز وسْم الحيوان في غير الوجه، وإن كان فيه شيء من التعذيب.
وجوب إنكار المنكر.', 'مَوْسُومَ الْوَجْه : مُعَلَّم على وجهه بالكيِّ.
الجَاعِرَتانِ : ناحية الوركين حول الدبر.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8891', false),
(21608, 2, 218, 1608, 'hadith', 'وعنه أن النبي صلى الله عليه وسلم : مر عليه حمار قد وُسم في وجهه، فقال: «لعن الله الذي وسمه».', 'An ass with a brand on the face happened to pass before the Prophet (ﷺ). Thereupon he said, "May Allah curse the one who has branded it (on the face).".Another narration in Muslim is: "The Messenger of Allah (ﷺ) prohibited us from hitting across the face and branding on the face (of an animal)."', null, 'Ibn ''Abbas (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1608', 'Riyad as-Salihin 1608', 'ریاض الصالحین 1608', 'رواه مسلم. وفي رواية لمسلم أيضًا: نهى رسول الله صلى الله عليه وسلم عن الضرب في الوجه، وعن الوسم في الوجه', 'في هذا الحديث النهي الأكيد والوعيد الشديد فيمن وسَم حيوانًا في وجهه وكذا الضرب في الوجه. قد عَدَّه العلماء -رحمهم الله- من كبائر الذنوب
وعلل العلماء للنهي؛ بأن الوجه لطيف يجمع المحاسن، وأعضاؤه نفيسة لطيفة وأكثر الإدراك بها فقد يبطلها ضرب الوجه وقد ينقصها وقد يشوه الوجه والشين فيه فاحش لأنه بارز ظاهر لا يمكن ستره ومتى ضربه لا يسلم من شين غالبا.', 'النهي عن الوَسْم في الوجه.
فيه النهي عن ضرب الوجه، ولو للتأديب.
جواز لعن من وسَم في الوجه.
الوسم في الوجه من كبائر الذنوب؛ لأن فاعله استحق اللعن.
الأمر بالرفق بالحيوان.
فيه جواز وسْم الحيوان في غير الوجه.', 'وسم : الوسم العلامة، وتكون بالكي غالبًا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8893', false),
(21609, 2, 218, 1609, 'hadith', 'عن أبي هريرة رضي الله عنه قال: بعثنا رسول الله صلى الله عليه وسلم في بعث فقال: "إن وجدتم فلانًا وفلانًا" لرجلين من قريش سماهما "فأحرقوهما بالنار" ثم قال رسول الله صلى الله عليه وسلم حين أردنا الخروج: "إني كنت أمرتكم أن تحرقوا فلانًا وفلانًا، وإن النار لا يعذب بها إلا الله، فإن وجدتموهما فاقتلوهما".', 'The Messenger of Allah (ﷺ) sent us on an expedition and said to us, "If you find so- and-so (he named two persons belonging to the Quraish) commit them to the fire." When we were on the verge of departure, he said to us, "I ordered you to burn so-and-so, but it is Allah Alone Who punishes with the fire. So if you find them put them to death.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1609', 'Riyad as-Salihin 1609', 'ریاض الصالحین 1609', 'رواه البخاري', 'يخبر أبو هريرة رضي الله عنه في هذا الحديث أن النبي صلى الله عليه وسلم بعثهم في جيش لقتال العدو، وأمرهم إذا رأوا رجلين من قريش عينهما لهم أن يحرقوهما بالنار، ثم قال صلى الله عليه وسلم لهم عندما جاءوا ليودعونه قبل سفرهم: إني كنت أمرتكم أن تحرقوا فلانا وفلانا، وإن النار لا يعذب بها إلا الله، فإن أخذتموهما فاقتلوهما.', 'النهي عن الإحراق بالنار، والاكتفاء بالقتل كأقصى درجات التأديب والعقوبة حتى للأعداء.
جواز الحكم بالشيء اجتهادا ثم الرجوع عنه.
استحباب ذِكر الدليل عند تقرير الحكم لرفع الالتباس.
فيه دليل على نسخ السنة بالسنة.
جواز نسخ الحكم قبل العمل به، أو قبل التمكن من العمل به.
طول الزمان لا يرفع العقوبة عمن يستحقها.
أن التعذيب بالنار من خصوصيات الله -تعالى-.', 'في بَعْثٍ : أي في جيش مَبْعُوث به.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8889', false),
(21610, 2, 218, 1610, 'hadith', 'عن ابن مسعود رضي الله عنه قال: كنا مع رسول الله صلى الله عليه وسلم في سفر، فانطلق لحاجته، فرأينا حمرة معها فرخان، فأخذنا فرخيها، فجاءت الحمرة فجعلت تعرش فجاء النبي صلى الله عليه وسلم فقال: "من فجع هذه بولدها؟ ردوا ولدها إليها" ورأى قرية نمل قد حرقناها، فقال: "من حرق هذه؟" قلنا: نحن. قال: "إنه لا ينبغي أن يعذِّب بالنار إلا رب النار". قوله: قرية نمل معناه: موضع النمل مع النمل.', 'We were with the Messenger of Allah (ﷺ) in a journey when he drew apart (to relieve nature). In his absence, we saw a red bird which had two young ones with it. We caught them and the red mother bird came, beating the earth with its wings. In the meantime the Prophet (ﷺ) returned and said, "Who has put this bird to distress on account of its young? Return them to her." He (ﷺ) also noticed a mound of ants which we had burnt up. He asked, "Who has set fire to this?" We replied: "We have done so." He (ﷺ) said, "None can chastise with fire except the Rubb of the fire.".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1610', 'Riyad as-Salihin 1610', 'ریاض الصالحین 1610', null, 'ذَكر عبدالله بن مسعود رضي الله عنه أنهم كانوا مع النبي صلى الله عليه وسلم في سفر، فانطلق صلى الله عليه وسلم لقضاء حاجته، فوجد أصحابه طائر الحُمّرة ومعها فرخان، فأخذوهما، فجعلت الحمرة تفرش جناحيها وتفتحهما فزعًا لفَقْد فرخيها، فجاء صلى الله عليه وسلم وقال: 

من أحزنها وخوّفها بأخذ صغارها؟! 

ثم أمر بردِّها إليها. 

ثم رأى قرية نمل قد حُرِّقت بالنار، فقال صلى الله عليه وسلم: من حرق هذه؟ 

قال بعض أصحابه: نحن. 

فقال لهم: إنه لا يجوز لأحد أن يُعذب حيًّا بالنار؛ إلا الله خالقها.', 'مشروعية الاستتار لقضاء الحاجة.
النهي عن تَعْذِيب الحيوانات بأخذ أولادها.
النهي عن إحراق النَّمل والحَشَرات بالنَّار.
الحثُّ على الرَّأفة والرحمة بالحيوان، وسبق الإسلام في ذلك.
رحمته صلى الله عليه وسلم بالحيوان.
التعذيب بالنار مما اختص به المولى عز وجل.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8892', false),
(21611, 2, 218, 1611, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «مطل الغني ظلم وإذا أُتبع أحدكم على مليء فليتبع».', 'The Messenger of Allah (ﷺ) said, "It is an act of oppression on the part of a person to procrastinate in fulfilling his obligation; if the repayment of a debt due to any of you is undertaken by a rich person, you should agree to the substitution.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1611', 'Riyad as-Salihin 1611', 'ریاض الصالحین 1611', 'متفق عليه. معنى "أتبع": أحيل', 'في هذا الحديث الشريف أدب من آداب المعاملة الحسنة.
فهو صلى الله عليه وسلم يأمر المدين بحسن القضاء، كما يرشد الغريم إلى حسن المطالبة.
فبين صلى الله عليه وسلم أن الغريم إذا طلب حقه، أو فهم منه الطلب بإشارة أو قرينة، فإن تأخير حقه عند الغني القادر على الوفاء، ظلم له، أنه دون حقه بلا عذر.
وهذا الظلم يزول إذا أحال المدين الغريم على مليء يسهل عليه أخذ حقه منه، فَلْيَقْبَل الغريم الحوالة حينئذ.
ففي هذا حسن الاقتضاء منه، وتسهيل الوفاء، كما أن فيه إزالة الظلم بما لو بقي الدين بذمة المدين المماطل.', 'تحريم مطل الغنىّ، ووجوب وفاء الدين الذي عليه لغريمه.
التحريم خاص بالغني المتمكن من الأداء، أما الفقير، أو العاجز لشيء من الموانع، فهو معذور.
تحريم مطالبة المعسر، ووجوب إنظاره إلى الميسرة؛ لأن تحريم المطل ووجوب الوفاء متعلقان بالغنى القادر، أما المعسر فيحرم التضييق عليه؛ لأنه معذور، و ملاحقته بالدين حرام.
في الحديث حسن القضاء من المدين، بأن لا يماطل الغريم، وفيه حسن الاقتضاء من الغريم بأن يقبل الحوالة إذا أحاله المدين على مليء.
ظاهر الحديث أنه إذا أحال المدين الغريم على مليء، وجب عليه قبول الحوالة.
مفهومه أنه لا يجب على المحال قبول الحوالة إذا أحاله على غير مليء.
فسر العلماء "المليء" بأنه ما اجتمع فيه ثلاث صفات:(1) أن يكون قادراً على الوفاء، فليس بفقير. (2) صادقا بوعده، فليس بمماطل. (3) يمكن جلبه إلى مجلس الحكم، فلا يكون صاحب جاه، أو يكون أباً للمحال، فلا يسمح القاضي له بمرافعته.
قال العلماء: إن مناسبة الجمع بين هاتين الجملتين أنه لما كان المطل ظلماً من المدين، طلب من الغريم إزالة هذا الظلم بقبول الحوالة على من لا يلحقه منه ضرر وهو المليء.
ظاهر الحديث، انتقال الديْن من ذمة المحيل إلى ذمة المحال عليه.
الإرشاد إلى ترك الأسباب القاطعة لاجتماع القلوب، لأن ذلك هو الحكمة في الزجر عن المماطلة.', 'مطل الغني : تأخير القادر على الأداء ما استحق أداؤه بغير عذر.
ظلم : يحرم عليه، والظلم: وضع الشيء في غير محله، والمطل ظلم لأنه وضع المنع موقع القضاء.
مليء : هو المليء بماله، وبدنه، وقوله: بماله: القدرة على الوفاء، وبدنه: إمكان إحضاره بمجلس الحكم، وقوله: أن لا يكون مماطلا.
فليتبع : فليقبل الإحالة؛ لأنه لا يتعذر استيفاء الحق منه عند الامتناع بل يأخذه الحاكم قهرا ويوفيه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6141', false),
(21612, 2, 218, 1612, 'hadith', 'عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «الذي يعود في هبته كالكلب يرجع في قيئه».', 'The Messenger of Allah (ﷺ) said, "He who gives something (to someone) as a gift and then gets it back (from him or her) is like a dog which eats its own vomit."Another narration is: "He who gets back his charity is like a dog which vomits and then returns to that and eats it.".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1612', 'Riyad as-Salihin 1612', 'ریاض الصالحین 1612', 'متفق عليه)). ((وفي رواية: "مثل الذي يرجع في صدقته، كمثل الكلب يقيء، ثم يعود في قيئه فيأكله". وفي رواية: "العائد في هبته كالعائد في قيئه', null, null, null, 'sunnah.com', null, false, null, false),
(21613, 2, 218, 1613, 'hadith', 'عن عمر بن الخطاب رضي الله عنه قال: حملت على فرس في سبيل الله فأضاعه الذي كان عنده، فأردت أن أشتريه، وظننت أنه يبيعه برخص، فسألت النبي صلى الله عليه وسلم فقال: "لا تشتره ولا تعد في صدقتك وإن أعطاكه بدرهم، فإن العائد في صدقته كالعائد في قيئه" ((متفق عليه)). قوله: "حملت على فرس في سبيل الله" معناه: تصدقت به على بعض المجاهدين.', 'I donated a horse in the way of Allah. Its new possessor did not treat it properly. I made my mind to buy it because I thought that he would sell it at a cheap price (now that it became weak and emaciated). I asked the Prophet (ﷺ) about it, whereupon he said, "Do not buy it and do not get back your charity, for one who gets back the charity is like a dog that eats its own vomit."', 'عمر بن الخطاب رضي الله عنه', '''Umar bin Al-Khattab (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1613', 'Riyad as-Salihin 1613', 'ریاض الصالحین 1613', null, 'أعان عمر بن الخطاب رضي الله عنه رجلا على الجهاد في سبيل الله، فأعطاه فرسا يغزو عليه، فقصر الرجل في نفقة ذلك الفرس، ولم يحسن القيام عليه، وأتعبه حتى هزل وضعف، فأراد عمر أن يشتريه منه وعلم أنه سيكون رخيصًا لهزاله وضعفه، فلم يقدم على شرائه حتى استشار النبي صلى الله عليه وسلم عن ذلك، ففي نفسه من ذلك شيء، فنهاه النبي صلى الله عليه وسلم عن شرائه ولو بأقل ثمن، لأن هذا شيء خرج لله تعالى فلا تتبعه نفسك ولا تعلق به، ولئلا يحابيك الموهوب له في ثمنه، فتكون راجعاً ببعض صدقتك، ولأن هذا خرج منك، وكفر ذنوبك، وأخرج منك الخبائث والفضلات، فلا ينبغي أن يعود إليك، ولهذا سمى شراءه عوداً في الصدقة مع أنه يشتريه بالثمن، وشبهه بالعود في القيء، وهو ما يخرج من البطن عن طريق الفم، والعود فيه أن يأكله بعد خروجه، وهذا للتقبيح والتنفير عن هذا الفعل.', 'استحباب الإعانة على الجهاد في سبيل اللّه، وأن ذلك من أجل الصدقات، فقد سماه النبي -صلى الله عليه وسلم- صدقة.
أن عمر تصدق على ذلك المجاهد بالفرس ولم يجعلها وقفا عليه، أو وقفا في سبيل الله على الجهاد، وإلا لما جاز للرجل بيعه.
نهي الإنسان عن شراء صدقته، لأنها خرجت لله، فلا ينبغي أن تتعلق بها النفس، وشراؤها دليل على تعلقه بها، ولئلا يحابيه البائع فيعود عليه شيء من صدقته.
يحرم الرجوع في الصدقة.', 'حملت على فرس : تبرعت بفرس يحمل من يركب عليه، وذلك على سبيل الصدقة.
في سبيل الله : في الجهاد.
فأضاعه الذي كان عنده : لم يحسن القيام به وقصر في مؤونته وخدمته.
قيئه : ما يخرج من بطنه عن طريق فمه.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6073', false),
(21614, 2, 218, 1614, 'hadith', 'عن أبي هريرة رضي الله عنه عن النبي صلى الله عليه وسلم قال: "اجتنبوا السبع الموبقات" قالوا: يا رسول الله وما هن؟ قال: "الشرك بالله، والسحر وقتل النفس التي حرم الله إلا بالحق، وأكل الربا، وأكل مال اليتيم، والتولي يوم الزحف، وقذف المحصنات المؤمنات الغافلات".', 'The Prophet (ﷺ) said, "Keep away from the seven fatalities." It was asked: "What are they, O Messenger of Allah?" He (ﷺ) replied, "Associating anything with Allah in worship (i.e., committing an act of Shirk), sorcery, killing of one whom Allah has declared inviolable without a just cause, devouring the property of an orphan, the eating of usury (Riba), fleeing from the battlefield and accusing chaste believing women, who never even think of anything touching their chastity.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1614', 'Riyad as-Salihin 1614', 'ریاض الصالحین 1614', 'متفق عليه. "الموبقات" المهلكات', 'يأمرُ رسولُ الله صلى الله عليه وسلم أمَّتَه بالابتعاد عن سبع جرائم ومَعاصٍ مهلكاتٍ، ولما سُئل عنها: ما هي؟ بيّنها بأنها:

 أولًا: الشرك بالله، باتخاذ النظير والمثيل له سبحانه من أي شكل كان، وصَرْف أي عبادة من العبادات لغير الله تعالى، وبدأ بالشرك؛ لأنه أعظم الذنوب.

ثانيًا: السحر -وهو عبارة عن عُقََد ورُقَى وأدوية وتدخينات-، يؤثِّر في بَدَن المسحور بالقتل أو بالمرض، أو يفرِّق بين الزوجين، وهو عمل شيطاني، وكثير منه لا يُتَوَصَّل إليه إلا بالشرك والتقرّب إلى الأرواح الخبيثة بشيء مما تحب.

ثالثًا: قتل النفس التي منع الله من قتلها إلا بمسوِّغٍ شرعي يُنفِّذُه الحاكم.

رابعًا: تناول الربا بأكلٍ أو بغيره من وجوه الانتفاع.

خامسًا: التعدِّي على مال الصغير الذي مات أبوه وهو دون البلوغ.

سادسًا: الفرار من المعركة مع الكفار.

سابعًا: اتهام الحرائر العفيفات بالزنا، وكذلك اتهام الرجال.', 'الكبائر ليست محصورة في سبع، وتخصيص هذه السبع لِعِظَمِها وخطرِها.
جواز قتل النفس إذا كان بحقٍّ، كالقصاص والردة والزنا بعد إحصان، وينفِّذه الحاكم الشرعي.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3331', false),
(21615, 2, 218, 1615, 'hadith', 'عن ابن مسعود رضي الله عنه قال: « لعن رسول الله صلى الله عليه وسلم آكل الربا وموكله» ((رواه مسلم)). زاد الترمذي وغيره: وشاهديه، وكاتبه', 'The Messenger of Allah (ﷺ) cursed the one who accepts Ar-Riba (the usury) and the one who pays it.

.

The narration in At-Tirmidhi adds: And the one who records it, and the two persons who stand witness to it.', 'ابن مسعود رضي الله عنه', '`Abdullah bin Mas`ud (May Allah be pleased with him)', null, 'رياض الصالحين 1615', 'Riyad as-Salihin 1615', 'ریاض الصالحین 1615', null, null, null, null, 'sunnah.com', null, false, null, false),
(21616, 2, 218, 1616, 'hadith', 'عن أبي هريرة رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: « قال الله تعالى: أنا أغنى الشركاء عن الشرك، من عمل عملا أشرك فيه معي غيري، تركته وشركه».', 'The Messenger of Allah (ﷺ) said, "Almighty Allah says, ''I am the One Who is most free from want of partners. He who does a thing for the sake of someone else beside Me, I discard him and his polytheism..".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1616', 'Riyad as-Salihin 1616', 'ریاض الصالحین 1616', 'رواه مسلم', 'يُخبِرُ النبيُّ صلى الله عليه وسلم أنَّ الله تبارك وتعالى قال بأنه أغنى الشركاء عن الشرك، فهو الغني عن كل شيء، وأنَّ الإنسانَ إذا عَمِل عملًا من الطاعات وجَعَلَه لله ولغير الله؛ تَركَه اللهُ ولم يقبلْه منه، وردَّه على صاحبِه؛ 
فيجبُ إخلاصُ العمل لله تعالى؛ لأنه سبحانه لا يَقبل إلا ما كان خالصًا لوجهِه الكريم.', 'التحذير من الشرك بجميع أشكاله، وأنه مانعٌ من قبول العمل.
استشعار غنى الله وعظمته مما يعين على الإخلاص في العمل.', '.....', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/3342', false),
(21617, 2, 218, 1617, 'hadith', 'وعنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: « إن أول الناس يقضى يوم القيامة عليه رجل اسُتشهد، فأتي به، فعرفه نعمته، فعرفها، قال: فما عملت فيها؟ قال: قاتلت فيك حتى اسُتشهدت، قال: كذبت، ولكنك قاتلت لأن يقال: جريء، فقد قيل، ثم أمر به، فسحب على وجهه حتى ألقي في النار. ورجل تعلم العلم وعلمه، وقرأ القرآن، فأتي به، فعرفه نعمه فعرفها. قال فما عملت فيها؟ قال تعلمت العلم وعلمته وقرأت فيك القرآن. قال كذبت، ولكنك تعلمت ليقال: عالم. وقرأت القرآن ليقال: هو قارئ، فقد قيل: ثم أُمر به، فسُحب على وجهه حتى ألقي في النار، ورجل وسع الله عليه، وأعطاه من أصناف المال، فأتي به فعرفه نعمه، فعرفها. قال: فما عملت فيها ؟ قال: ما تركت من سبيل تحب أن ينفق فيها إلا أنفقت فيها لك، قال: كذبت، ولكنك فعلت ليقال: جواد، فقد قيل، ثم أُمر به فسُحب على وجهه ثم ألقي في النار» ((رواه مسلم)). جَريء بفتح الجيم وكسر الراء وبالمد، أي: شجاع حاذق', 'I heard the Messenger of Allah (ﷺ) saying, "The first to be judged on the Day of Resurrection will be a man who had died as a martyr. He will be brought forward. Allah will remind him of the favours He had bestowed upon him and the man will acknowledge them. Then He will ask him: ''What did you do to express gratitude for it?'' The man will reply: ''I fought for Your Cause till I was martyred.'' Allah will say: ''You have lied. You fought so that people might call you courageous; and they have done so.'' Command will then be issued about him and he will be dragged on his face and thrown into Hell. Next a man who had acquired and imparted knowledge and read the Qur''an will be brought forward, Allah will remind him of the favours He had bestowed upon him and the man will acknowledge them. Then He will ask him: ''What did you do to express gratitude for it?'' The man will reply: ''I acquired knowledge and taught it, and read the Qur''an for Your sake.'' Allah will say to him: ''You have lied. You acquired knowledge so that people might call you a learned (man), and you read the Qur''an so that they might call you a reciter, and they have done so.'' Command will then be issued about him, and he will be dragged on his face and thrown into Hell. Next a man whom Allah had made affluent and to whom Allah had given plenty of wealth, will be brought forward, Allah will remind him of the favours He had bestowed upon him and the man will acknowledge them. He will ask him: ''What did you do to express gratitude for it?'' The man will reply: ''I did not neglect any of the ways You liked wealth to be spent liberally for Your sake''. Allah will say to him: ''You have lied. You did it so that people might call you generous, and they have done so.'' Command will then be issued about him and he will be dragged on his face and thrown into Hell.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1617', 'Riyad as-Salihin 1617', 'ریاض الصالحین 1617', null, 'أن أول من يُقضي فيهم يوم القيامة هم ثلاثة أصناف: مُتَعلِّم مرائي ومقاتل مرائي ومتصدِّق مرائي، ثم إن الله سبحانه وتعالى يأتى بهم إليه يوم القيامة فيعرفهم الله نعمته فيعرفونها ويعترفون بها فيسأل كل منهم: ماذا صنعت؟ يعني في شكر هذه النعمة، فيقول الأول: تعلمت العلم وقرأت القرآن فيك. فقال الله له: كذبت، ولكن تعلمت ليقال: عالم، وقرأت القرآن ليقال: قارئ ليس لله، بل لأجل الرياء، ثم أُمر به فسُحب على وجهه في النار، وكذا من بعده.', 'التحذير من الرياء، وأن أول ما يقضى فيه يوم القيامة أعمال الرياء بإظهارها وتأنيب أصحابها وفضحهم.
تغليظ تحريم الرِّياء وشدِّة العقوبة عليه.
لا يكفي العمل الظاهر للنجاة في الآخرة، بل لا بد من الإخلاص وابتغاء وجه الله -تعالى-.
المراؤون يأخذون ثوابهم في الدنيا فقط وهو مدح الناس لهم.
المراؤون يوم القيامة لا يجدون إلا العذاب جزاء وفاقًا لهم.
امتهان وإذلال للمرائين؛ لأنهم يسحبون على وجوههم موضع كرامتهم إلى النار.
وجوب إخلاص العمل لله -تعالى-.', 'يُقضى يوم القيامة عليه : يحكم عليه ويفصل في أمره.
عرَّفه نِعمته : عرَّف الله العبد نِعمته التي كانت عليه في الدنيا.
قَاتَلْت فيك : أي لأجلك ولنَصر دِينك.
فقد قِيل : أي حصل لك في الدنيا ما أردت.
فَسُحِب : جُرَّ.
جَواد : كثير الجُود والعطاء.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8899', false),
(21618, 2, 218, 1618, 'hadith', 'عن ابن عمر رضي الله عنهما أن ناسًا قالوا له: إنا ندخل على سلاطيننا فنقول لهم بخلاف ما نتكلم إذا خرجنا من عندهم؟ قال ابن عمر رضي الله عنهما: كنا نعد هذا نفاقًا على عهد رسول الله صلى الله عليه وسلم.', 'Some people told me, "We visit our rulers and we tell them things contrary to those which we say when we depart from them."
`Abdullah bin `Umar (May Allah be pleased with them) replied: "In the era of the Messenger of Allah (ﷺ) we considered this to be an act of hypocrisy."', 'ابن عمر رضي الله عنهما', '`Abdullah bin `Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1618', 'Riyad as-Salihin 1618', 'ریاض الصالحین 1618', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21619, 2, 218, 1619, 'hadith', 'عن جُندب بن عبد الله بن سفيان رضي الله عنه قال: قال النبي صلى الله عليه وسلم : "من سمَّع سمَّع الله به، ومن يرائي الله يرائي به" ((متفق عليه)). ((رواه مسلم أيضًا من رواية ابن عباس رضي الله عنه)). "سمَّع" بتشديد الميم، ومعناه: أظهر عمله للناس رياء " سمَّع الله به" أي فضحه يوم القيامة، ومعنى: " من راءى" أي: من أظهر للناس العمل الصالح ليعظم عندهم "راءى الله به" أي: أظهر سريرته على رءوس الخلائق.', 'The Prophet (ﷺ) said, "He who so acts to show off, Allah will disgrace him on the Day of Resurrection, and he who does good deeds so that people (may hold him in high esteem), Allah will expose his hidden evil intentions before the people on the Day of Resurrection.".', 'جُندب بن عبد الله بن سفيان رضي الله عنه', 'Jundub (May Allah be pleased with him) said:', null, 'رياض الصالحين 1619', 'Riyad as-Salihin 1619', 'ریاض الصالحین 1619', null, null, null, null, 'sunnah.com', null, false, null, false),
(21620, 2, 218, 1620, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم « من تعلم علمًا مما يبتغى به وجه الله عز وجل لا يتعلمه إلا ليصيب به عرضًا من الدنيا، لم يجد عَرف الجنة يوم القيامة» يعني ريحها. رواه أبو داود بإسناد صحيح والأحاديث في الباب كثير مشهورة.', 'The Messenger of Allah (ﷺ) said, "A person who acquires (religious) knowledge, which is (normally) acquired to gain the Pleasure of Allah, (for the sole reason) to secure worldly comforts will not even smell the fragrance of Jannah on the Day of Resurrection (i.e., will not enter Jannah).".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1620', 'Riyad as-Salihin 1620', 'ریاض الصالحین 1620', null, 'بيَّن النبي صلى الله عليه وسلم أنَ من تعلم العلم الشرعي الذي الأصل فيه أن يراد به رضى الله تعالى لا يتعلمه إلا ليصيب وينال به حظًا ومتاعًا من الدنيا من مالٍ أو جاهٍ لم يجد ريح الجنة يوم القيامة.', 'وجوب الإخلاص في طلب العلم، والحث على ذلك.
التحذير الشديد من اتخاذ العلم الشرعي رياءً أو مطية للدنيا، وأن ذلك من كبائر الذنوب.
أن من طلب العلم لله تعالى وجاءته الدنيا تبعا جاز له أخذها، ولم يضره ذلك.
قال السندي: قوله (عرف الجنة): الرائحة، مبالغة في تحريم الجنة؛ لأن من لا يجد ريح الشيء لا يتناوله.
من تعلم علمًا مما يبتغى به وجه الله من أجل الوظيفة، أو من أجل أغراض أخرى؛ فإن عليه التوبة إلى الله من ذلك، والله يمحو عنه ما حصل من النية الفاسدة وهو ذو الفضل العظيم سبحانه وتعالى.
هذا التحذير لطالب العلم الشرعي، أما من طلب علمًا من علوم الدنيا لأجل متاع الدنيا كالهندسة والكيمياء وغيرهما لأجل الدنيا فله نيته.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6262', false),
(21621, 2, 218, 1621, 'hadith', 'عن أبي ذر رضي الله عنه قال: قيل لرسول الله صلى الله عليه وسلم : أرأيت الرجل يعمل العمل من الخير، ويحمده الناس عليه؟ قال: « تلك عاجل بشرى المؤمن».', 'The Messenger of Allah (ﷺ) was asked: "Tell us about a person who does some good deed and people praise him, will this be considered as showing off?" He replied, "This is the glad tidings which a believer receives (in this life).".', 'أبي ذر رضي الله عنه', 'Abu Dharr (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1621', 'Riyad as-Salihin 1621', 'ریاض الصالحین 1621', 'رواه مسلم', 'معنى الحديث: أن الرَّجُل يعمل عملا صالحا لله لا يقصد به الناس، ثم إن الناس يمدحونه على ذلك. يقولون فلان كثير الخير فلان كثير الطاعة فلان كثير الإحسان إلى الخلق وما أشبه ذلك فقال صلى الله عليه وسلم : "تلك عاجل بشرى المؤمن" وهو الثناء عليه؛ لأن الناس إذا أثنوا على الإنسان خيرًا فهم شهداء الله في أرضه ولهذا لما مَرَّت جَنازة من عند النبي صلى الله عليه وسلم وأصحابه أثنوا عليها خيرا قال وجبت، ثم مرَّت أخرى فأثنوا عليها شرًا قال وجبت فقالوا يا رسول الله ما وجبت قال: "أما الأول فوجبت له الجنة وأما الثاني فوجبت له النار أنتم شهداء الله في الأرض".
فهذا معنى قوله: "تلك عاجل بشرى المؤمن".
والفرق بين هذه وبين الرياء أن المرائي لا يعمل العمل إلا لأجل أن يراه الناس ويثنون عليه فيكون في هذه الحال قد أشرك مع الله غيره، وأما هذا فنيته خالصة لله عز وجل ولم يطرأ على باله أن يمدحه الناس أو يذموه فإذا علموا بطاعته ومدحوه وأثنوا عليه فهذا ليس برياء هذا عاجل بشرى، والفرق بين هذا وبين ما ذُكر في الحديث فرق عظيم.', 'أن الإخلاص لله -تعالى- وقصد التَّقرب إليه لا يُعَكِّره ثناء الناس عليه، بل إن إطلاق الله -تعالى- لألسنة الناس بالثناء عليه، دليل على القبول، وشهادة صادقة وبشرى عاجلة بالفوز والفلاح.
لا يدخل في الرياء عمل العبد إذا أخلص عمله لله تعالى وحمده الناس عليه.
دليل على رضا الله ومحبته لهذا العبد، و أنه يحبب فيه الخلق لإخلاصه ولذلك يكتب له القبول في الأرض.
التَّعرض لمدح الناس مذْمُوم.', 'أرأيت : أخبرني.
عاجِل بُشْرَى المؤمن : الخبر السار الذي يكون في الدنيا قبل الآخرة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8900', false),
(21622, 2, 218, 1622, 'hadith', 'عن أبي هريرة رضي الله عنه أن النبي صلى الله عليه وسلم قال: «كُتب على ابن آدم نصيبه من الزنا مدرك ذلك لا محالة: العينان زناهما النظر، والأذنان زناهما الاستماع، واللسان زناه الكلام، واليد زناها البطش، والرجل زناها الخطا، والقلب يهوى ويتمنى، ويصدق ذلك الفرج أو يكذبه».', 'The Prophet (ﷺ) said, "Allah has written the very portion of Zina which a man will indulge in. There will be no escape from it. The Zina of the eye is the (lustful) look, the Zina of the ears is the listening (to voluptuous songs or talk), the Zina of the tongue is (the licentious) speech, the Zina of the hand is the (lustful) grip, the Zina of the feet is the walking (to the place where he intends to commit Zina), the heart yearns and desires and the private parts approve all that or disapprove it.".This is the wording in Muslim; Al-Bukhari wording is a bit short.', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1622', 'Riyad as-Salihin 1622', 'ریاض الصالحین 1622', 'متفق عليه. وهذا لفظ مسلم، ورواية البخاري مختصرة', 'معنى الحديث أن الإنسان مُدرك للزنا لا محالة إلا من عصمه الله، ثم ذكر النبي صلى الله عليه وسلم أمثلة لذلك:
"فالعين زناها النظر" يعني: أن الرَّجُل إذا نظر إلى امرأة ولو لغير شهوة وهي ليست من محارمه فهذا نوع من الزنا وهو زنا العين.
"والأُذنان زِناهما الاستماع" أي يستمع الإنسان إلى كلام المرأة ويتلذذ بصوتها، هذا زنا الأذن.
"واليد زناها البَطْش" يعني العمل باليد من اللمس وما أشبه ذلك. 
"والرِجل زناها الخُطا" يعني أن الإنسان يمشي إلى محل الفواحش مثلا أو يسمع إلى صوت امرأة فيمشي إليها أو يرى امرأة، فيتبعها هذا نوع من الزنا.
"والقلب يَهْوَى ويتمنى" أي يميل إلى هذا الأمر وهو التعلق بالنساء هذا زنا القلب.
"والفرج يصدِّق ذلك أو يُكذِّبه" يعني أنه إذا زنى بالفرج والعياذ بالله، فقد صدق زنا هذه الأعضاء وإن لم يزن بفرجه، بل سَلِم وحفظ نفسه فإن هذا يكون تكذيبا لزنا هذه الأعضاء.
فدل ذلك على الحذر من التعلق بالنساء لا بأصواتهن ولا بالرؤية إليهن ولا بمسهن ولا بالسعي إليهن ولا بغواية القلب لهن، كل ذلك من أنواع الزنا -والعياذ بالله-، فليحذر الإنسان العاقل العفيف من أن يكون في هذه الأعضاء شيء يتعلق بالنساء.', 'التوجيه إلى ترك الزنا ودواعيه.
حرمة النظر إلى ما في البيت بغير استئذان.
الزنا الذي يوجب الحدَّ لا يتحقق إلا بالإيلاج.
سماع ما حرَّم الله نوع من أنواع الزنا.
النظر إلى ما حرَّم الله نوع من أنواع الزنا.
الكلام فيما حرَّم الله نوع من أنواع الزنا.
الله يعلم من الأزَل مقادير الناس، ولا يقع شيء مخالفا لعلمه، ولا يتخلف علمه عن معرفة كل شيء.
الله أعطى العبد المقْدِرة على رَدْع نفسه عما حرَّمه الله عليه.
الزنا لا يختص إطلاقه بالفرج، بل هو شامل لدواعيه من النظر واللمس.
الحديث دليل لمعتقد أهل الحق في باب القدر أن العبد لا يخلق فعل نفسه؛ بدليل قوله عليه الصلاة والسلام: "والقلب يهوى ويتمنى ويصدق ذلك الفرج أو يكذبه"؛ فدل هذا أن العبد لو كان خالقا لفعل نفسه لما عجز عن فعل ما يريد مع وجود الطواعية واستحكام الشهوة.', 'كُتِبَ : قُدِّرَ.
مُدْرِكُ : محصِّل.
البَطْش : الأخذ القوي الشَّديد.
الخُطا : المشي والمراد المشي إلى فعل الحرام.
القلب يَهوى : أي يريد وقوع ما تحبه النفس من الشهوة.
يُصَدِّق : يحقق.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8898', false),
(21623, 2, 218, 1623, 'hadith', 'عن أبي سعيد الخُدري رضي الله عنه عن النبي صلى الله عليه وسلم قال: "إياكم والجلوس في الطرقات". قالوا: يا رسول الله ما لنا من مجالسنا بُد نتحدث فيها. فقال رسول الله صلى الله عليه وسلم : "فإذا أبيتم إلا المجلس، فأعطوا الطريق حقه" قالوا: وما حق الطريق يا رسول الله؟ قال: "غض البصر، وكف الأذى، ورد السلام، والأمر المعروف والنهي عن المنكر".', 'The Prophet (ﷺ) said, "Avoid sitting on roadsides." His Companions said: "O Messenger of Allah (ﷺ), there is no other alternative but to sit there to talk." Thereupon the Messenger of Allah (ﷺ) said, "If you have to sit at all, then fulfill the rights of the road." They asked: "What are their rights?" Thereupon he said, "Lowering the gaze (so that you may not stare at unlawful things); refraining from doing some harm to others, responding to greeting (i.e., saying ''Wa''alaikumus- salam'' to one another) and commanding the good and forbidding the evil.".', 'أبي سعيد الخُدري رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1623', 'Riyad as-Salihin 1623', 'ریاض الصالحین 1623', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21624, 2, 218, 1624, 'hadith', 'عن أبي طلحة زيد بن سهل رضي الله عنه قال: كنا قعودًا بالأفنية نتحدث فيها فجاء رسول الله صلى الله عليه وسلم فقالم علينا فقال: "ما لكم ولمجالس الصعدات؟ فقلنا: إنما قعدنا لغير ما بأس، قعدنا نتذاكر، ونتحدث. قال: "إما لا فأدوا حقها: غض البصر، ورد السلام، وحسن الكلام" ((رواه مسلم)). "الصُّعُدات" بضم الصاد والعين، أي: الطرقات.', 'We were sitting and talking on a platform in front of our house when the Messenger of Allah (ﷺ) stopped by us and said, "Why do you sit on roads? Avoid sitting in them." We replied: "We sit there intending no harm. We only sit and discuss (religious) knowledge and talk." He said, "If you have to sit, you should fulfill the rights of the road: Lower your gaze, respond to greetings and talk in a good manner.".', 'أبي طلحة زيد بن سهل رضي الله عنه', 'Abu Talhah Zaid bin Sahl (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1624', 'Riyad as-Salihin 1624', 'ریاض الصالحین 1624', null, 'يخبر أبو طلحة رضي الله عنه أنهم كانوا قعودًا عند فِنَاءِ دار، وهي الأماكن المتسعة عند البيوت ويتحدثون في أمورهم، "فجاء رسول الله صلى الله عليه وسلم فقام علينا" أي أن النبي صلى الله عليه وسلم أقبل عليهم ووقف عندهم ونهاهم صلى الله عليه وسلم عن الجلوس في الطرقات.
قالوا: "إنما قَعَدْنَا لغير ما بأس، قَعَدْنَا نتذَاكَر، ونتحدث" أي أن جلوسنا هنا يا رسول الله لا لأمر فيه بأس شرعًا، بل جلوسنا هنا لأمر مباح وهو أننا نتذاكر ونتحدث فيما بيننا.
قال: "إما لا فأدُّوا حقَها" أي فإن أبيتم ترك هذه المجالس، فأدوا حقها وفي الرواية الأخرى: "إن أبيتم إلا المجلس فأعطوا الطريق حقه"، وفي الرواية الأخرى: "سألوه وما حقُّ الطريق" فقال لهم: "غَضُّ البَصَر، وردُّ السلام، وحُسْن الكلام"، وفي الرواية الأخرى: "غضُّ البصر وكفُّ الأذى وردُّ السلام والأمر بالمعروف والنهي عن المنكر" والمعنى إن أبيتم إلا الجلوس في الطرقات، فإن الواجب عليكم أن تُؤَدُّوا ما هو واجب عليكم، فبين لهم صلى الله عليه وسلم سبب النهي عن الجلوس في الطرقات وذلك أن الإنسان قد يتعرض للفتن بحضور النساء الشواب، وخوف ما يلحق من ذلك من النظر إليهن والفتنة بسببهن، ومن التعرض لحقوق الله وللمسلمين بما لا يلزم الإنسان إذا كان في بيته وحيث ينفرد أو يشتغل بما يلزمه، ومن رؤية المنكر، فيجب عليه في هذه الحال أن يأمر بالمعروف وينهى عن المنكر، فإن ترك ذلك فقد تعرض لمعصية الله.
وكذلك هو يتعرض لمن يَمُر عليه ويسلِّم، وربما كثر ذلك عليه فيعجز عن ردِّ السلام على كل مَار، ورَدُّه فرض، فيأثم والمرء مأمور ألا يتعرض للفتن، ولا يلزم نفسه ما لعله لا يقوم بحقه فيه.', 'إباحة الجلوس في حافات الطرق، بشرط أداء حق الطريق والتأدب بالآداب الإسلامية، وهي: غضُّ البصر، ردُّ السلام، كفُّ الأذى، والأمر بالمعروف والنهي عن المنكر.
النهي عن إتيان الأماكن التي يتعرض فيها للفتن.
النهي عن تضييق الطريق على المسلمين.', 'الأفْنِيَة : جمع فناء وهو المكان المُتَّسع أمام البيت.
فقام علينا : وقف علينا.
الصُّعُدَات : الطُرقات.
لغير ما بأس : البَأس: المانع والحرج، والمعنى: أن قعودنا هنا لمباح لا لأمر فيه بأس شرعًا.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8896', false),
(21625, 2, 218, 1625, 'hadith', 'عن جرير رضي الله عنه قال: سألت رسول الله صلى الله عليه وسلم عن نظر الفجأة فقال: «اصرف بصرك».', 'I asked the Messenger of Allah (ﷺ) about (the Islamic ruling on) accidental glance (i.e., at a woman one is not Islamically allowed to look at) and he ordered me to turn my eyes away..', 'جرير رضي الله عنه', 'Jarir bin ''Abdullah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1625', 'Riyad as-Salihin 1625', 'ریاض الصالحین 1625', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21626, 2, 218, 1626, 'hadith', 'عن أم سلمة رضي الله عنها قالت: كنت عند رسول الله صلى الله عليه وسلم وعنده ميمونة، فأقبل ابن أم مكتوم، وذلك بعد أن أُمرنا بالحجاب فقال النبي صلى الله عليه وسلم : "احتجبا منه" فقلنا: يا رسول الله إلىس هو أعمى لا يبصرنا، ولا يعرفنا؟ فقال النبي صلى الله عليه وسلم : "أفعمياوان أنتما ألستما تبصرانه؟!".', 'I was with the Messenger of Allah (ﷺ) along with Maimunah (May Allah be pleased with her) when Ibn Umm Maktum (May Allah be pleased with him) (who was blind) came to visit him. (This incident took place after the order of Hijab). The Prophet (ﷺ) told us to hide ourselves from him (i.e., observe Hijab). We said: "O Messenger of Allah (ﷺ), he is blind and is unable to see us, nor does he know us." He replied; "Are you also blind and unable to see him?".', 'أم سلمة رضي الله عنها', 'Umm Salamah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1626', 'Riyad as-Salihin 1626', 'ریاض الصالحین 1626', 'رواه أبو داود والترمذي: وقال حديث حسن صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21627, 2, 218, 1627, 'hadith', 'عن أبي سعيد رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «لا ينظر الرجل إلى عورة الرجل، ولا المرأة إلى عورة المرأة، ولا يفضي الرجل إلى الرجل في ثوب واحد، ولا تفضي المرأة إلى المرأة في ثوب واحد».', 'The Messenger of Allah (ﷺ) said, "A man must not look at a man''s private parts nor must a woman look at a woman''s private parts; neither should two men lie naked under one cover, nor should two women lie naked under the same cover.".', 'أبي سعيد رضي الله عنه', 'Abu Sa''id Al-Khudri (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1627', 'Riyad as-Salihin 1627', 'ریاض الصالحین 1627', 'رواه مسلم', 'نَهَى النبيُّ صلى الله عليه وسلم أن يَنظُرَ الرجلُ إلى عورة الرجل، أو تنظرَ المرأةُ إلى عورة المرأة. 

والعورة: هي كل ما يُسْتَحْيَا منه إذا ظَهَر، وعورة الرجل هي ما بين سُرَّتِه ورُكبتِه، 
والمرأةُ كلُّها عورةٌ بالنسبة للرجال الأجانب، وبالنسبة للنساء ولمحارمِها فإنها تُظْهِرُ ما يَظْهَر عادةً عند عملِها في البيت. 

ونَهى النبيُّ صلى الله عليه وسلم عن أنْ يَخْلُوَ الرجلُ إلى الرجل في ثوبٍ واحدٍ أو تحت غطاء واحدٍ مُتَجَرِّدَيْن، وعن أنْ تَخْلُوَ المرأةُ إلى المرأة في ثوب واحد أو تحت غطاء واحد مُتَجَرِّدَتين؛ لأن ذلك قد يُؤدِّي إلى لَمْسِ كلٍّ منهما عورةَ صاحبه، ولمسُها مَنهيٌّ عنه كالنظر إليها، بل هو أشد في النهي؛ لما يؤدي ذلك إلى مفاسد أكبر.', 'النهي عن النظر إلى العورات ماعدا الزوج وزوجته.
حرص الإسلام على طهارة المجتمع وإغلاق الطرق المؤدِّية للفواحش.
جواز النظر إلى العورة إذا دعت الحاجة إلى ذلك كالتَّطَبُّب ونحوه، على أن يكون بغير شهوة.
المسلم مأمور بستر عورته وغضِّ بصره عن عورة غيره.
خُصَّ النهي بالرجال مع الرجال والنساء مع النساء؛ لأنه أدعى للنظر وكشف العورات.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8904', false),
(21628, 2, 218, 1628, 'hadith', 'عن عقبة بن عامر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "إياكم والدخول على النساء"، فقال رجل من الأنصار: أفرأيت الحمو؟ قال: "الحمو الموت" ((متفق عليه)). الحمو قريب الزوج كأخيه، وابن أخيه، وابن عمه.', 'The Messenger of Allah (ﷺ) said, "Avoid (entering a place) in which are women (uncovered or simply to mix with them in seclusion)." A man from the Ansar said, "Tell me about the brother of a woman''s husband." He replied, "The brother of a woman''s husband is death.".', 'عقبة بن عامر رضي الله عنه', '''Uqbah bin ''Amir (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1628', 'Riyad as-Salihin 1628', 'ریاض الصالحین 1628', null, 'حَذَّرَ النبيُّ صلى الله عليه وسلم مِن الاختلاط بالنساء الأجنبيات، وقال: اتقوا أنفسَكم أنْ تدخلوا على النساء، والنساء أنْ يَدخلْنَ عليكم.

فقال رجل من الأنصار: أفرأيتَ أقارب الزوج؛ كأخِ الزوج وابن أخيه، وعمه وابن عمه، وابن أخته، ونحوهم ممن يَحِلُّ لها تزويجُه لو لم تكن مُتزوجة؟ 

فقال صلى الله عليه وسلم: احذروه كما تَحذَروا الموت! لأنَّ الخَلْوَة بالأَحْمَاء مُؤدِّيَة إلى الفتنة والهلاك في الدِّين، فأقارب الزَّوج غير آبائه وأبنائه أولى بالمنع من الأجنبي؛ لأن الخَلْوَة بقريب الزوج أكثر من الخلوة بغيره، والشر يُتَوَقّع منه أكثر من غيره، والفتنة به أَمْكَنُ؛ لِتَمَكُّنه من الوصول إلى المرأة والخلوة بها من غير نكير عليه، ولأنه لا بُدّ منه، ولا يمكن حَجْبُه عنها، حيث جرت العادة بالتساهل فيه فيخلو الرجل بامرأة أخيه؛ فهو يُشْبِه الموتَ في الاستقباح والمفسدة، بخلاف الرجل الأجنبي فإنه يُحْذَرُ منه.', 'النهيُ عن الدخول على الأجنبيات والخلوة بهن، سَدًّا لذريعة وقوع الفاحشة.
هذا عامٌّ في الأجانب من أخي الزوج وأقاربه، الذين ليسوا محارم للمرأة، ولا بد من اعتبار أن يكون الدخول مقتضيًا للخلوة.
الابتعاد عن مواطن الزَّلَل عامة، خشية الوقوع في الشر.
قال النووي: اتفق أهل العلم باللغة على أنَّ الأحْمَاءَ أقاربُ زوج المرأة كأبيه وعمه، وأخيه وابن أخيه، وابن عمه ونحوهم، وأن الأَخْتَانَ أقاربُ زوجة الرجل، وأنَّ الأصْهارَ تقعُ على النوعين.
شَبَّهَ (الحَمْوَ) بالموت، قال ابن حجر: والعرب تَصف الشيء المكروه بالموت، وجْهُ الشَّبَهِ أنه موتُ الدِّين إنْ وقعت المعصية، وموتُ المُختلي إن وقعت المعصية ووجب الرَّجْم، وهلاك المرأة بفراق زوجها إذا حَمَلَتْه الغَيْرَة على تَطلِيقِها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5888', false),
(21629, 2, 218, 1629, 'hadith', 'عن ابن عباس رضي الله عنهما أن رسول الله صلى الله عليه وسلم قال: «لا يخلون أحدكم بامرأة إلا مع ذي محرم».', 'The Messenger of Allah (ﷺ) said, "No one of you should meet a woman in privacy unless she is accompanied by a Mahram (i.e., a relative within the prohibited degrees).".', 'ابن عباس رضي الله عنهما', 'Ibn Abbas (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1629', 'Riyad as-Salihin 1629', 'ریاض الصالحین 1629', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21630, 2, 218, 1630, 'hadith', 'عن بريدة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "حرمة نساء المجاهدين على القاعدين كحرمة أمهاتهم، ما من رجل من القاعدين يخلف رجلا من المجاهدين في أهله، فيخونه فيهم إلا وقف له يوم القيامة، فيأخذ من حسناته ما شاء حتى يرضى" ثم التفت إلينا رسول الله صلى الله عليه وسلم وقال: "ما ظنكم؟".', 'The Messenger of Allah (ﷺ) said, "The sanctity of the wives of Mujahidun (i.e., those who strive hard and fight in the way of Allah) for those who remain at home (i.e., those who do not go to the battlefield to fight Jihad) is like the sanctity of their own mothers. Anyone who remains behind to look after the family of a Mujahid and betrays his trust, will be made to stand on the Day of Resurrection before the Mujahid who will take away from his meritorious deeds whatever he likes till he is satisfied." The Messenger of Allah (ﷺ) turned toward us and said, "Now, what do you think (i.e., will he leave anything with him)?".', 'بريدة رضي الله عنه', 'Buraidah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1630', 'Riyad as-Salihin 1630', 'ریاض الصالحین 1630', 'رواه مسلم', 'الأصل أن المرأة الأجنبية تحرم على غيرها من الرجال الأجانب ويزداد الأمر حُرْمَة في نساء المجاهدين الذين خرجوا للجهاد في سبيل الله تعالى وتركوا نساءهم خلفهم، وائتمنوا المقيمين عليهن.
فالواجب عليهم الحذر من أن يقعوا في أعراضهم، لا بخلوة ولا نظر ولا كلام فاحش؛ لأنهن في التحريم كَحُرمة أمهاتهم عليهم، فبين النبي صلى الله عليه وسلم أن على الإنسان أن يقوم بما يجب لهم ولا يخونه فيهم لا بأن ينظر أو يحاول أن يقع في أمر محرم، ولا في أن يُقَصِّر فيما هو مطلوب منه من الرعاية والعناية وإيصال الخير إليهم ودفع الأذى عنهم.
"ما من رَجُلٍ من القَاعِدِين يَخْلِف رجُلا من المجاهدين في أهله، فَيَخُونُهُ فيهم إلا وقَف له يوم القيامة، فيأخذ من حسناته ما شاء حتى يَرْضى" والمعنى : أن من تجرأ على نساء المجاهدين حال غيبتهم وخانهم في نسائهم، فإن الله تعالى يمكن المجاهد منه يوم القيامة؛ فيأخذ المجاهد من حسنات الخائن ما شاء حتى يرضى وتقرَّ عينه.
ثم قال صلى الله عليه وسلم : "فما ظنكم؟" أي: فما تظنون في رغبة المجاهد في أخذ حسناته والاستكثار منها في ذلك المقام؟ أي لا يبقى منها شيء إلا أخذه.', 'الحضُّ على التكافل بين المسلمين وحرص كل منهم على سلامة الآخرين.
التحذير من الخيانة ويشتد ذلك في حقِّ المجاهدين في سبيل الله؛ لأن المجاهدين يقومون بنصرة الدين ويدافعون عن القاعدين، فلا يجوز لقاعد أن يتعرض لنسائهم بوجه من الوجوه مستغلًا غياب الزوج.
يعاقب المعتدي على نساء المجاهدين بعرض حسناته يوم القيامة على ذلك المجاهد ليأخذ منه ما شاء.
حِيطة الإسلام على سلامة أمن المجاهدين والغائبين عن أهليهم.
فيه عِظم فضل المجاهدين وأن الشرع قد حَمى أعراضهم حال غيبتهم وتوعَّد من ينتهكها بأشد العقوبات.
ثبوت القصاص بين الخلائق يوم القيامة.', 'يَخْلِفُ رجُلاً : يكون خليفة عنه وقت غيابه ويقوم عنه بحوائجهم.
فيخونهم : بدلًا من القيام بحوائجهم يتعرض بهم بالسوء من النظر أو الكلام أو محاولة الفاحشة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8901', false),
(21631, 2, 218, 1631, 'hadith', 'عن ابن عباس رضي الله عنهما قال: لعن رسول الله صلى الله عليه وسلم المخنثين من الرجال، والمترجلات من النساء. وفي رواية: لعن رسول الله صلى الله عليه وسلم المتشبهين من الرجال بالنساء، والمتشبهات من النساء بالرجال.', 'The Messenger of Allah (ﷺ) cursed those men who are effeminate, and women who imitate men.Another narration is: The Messenger of Allah (ﷺ) cursed men who copy women and cursed women who copy men..', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1631', 'Riyad as-Salihin 1631', 'ریاض الصالحین 1631', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21632, 2, 218, 1632, 'hadith', 'عن أبي هريرة رضي الله عنه قال: لعن رسول الله صلى الله عليه وسلم الرجل يلبس لبسة المرأة، والمرأة تلبس لبسة الرجل.', 'The Messenger of Allah (ﷺ) cursed a man who puts on the dress of women, and a woman who puts on the dress of men..', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1632', 'Riyad as-Salihin 1632', 'ریاض الصالحین 1632', 'رواه أبو داود بإسناد صحيح', 'دَعَا النبيُّ صلى الله عليه وسلم بالطَّرْدِ والإبعاد من رحمة الله لكلِّ رجلٍ يتشبَّه بالمرأة في الملابس الخاصة بالنساء؛ سواء في الهيئة أو اللون أو الكيفية أو طريقة اللبس والزينة أو غير ذلك، 
أو أن تتشبَّهَ المرأةُ باللبس الخاص بالرجال كذلك، وهو كبيرة من كبائر الذنوب.', 'قال الشوكاني: تحريم تشبه النساء بالرجال والرجال بالنساء؛ لأن اللعن لا يكون إلا على فعل محرم.
قال ابن عثيمين: ما كان مشتركًا بينهما مثل بعض الفنائل التي يلبسها الرجل والنساء فإنه لا بأس به، أي لا بأس أن يلبسَه الرجال والنساء؛ لأنه مشترك.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8905', false),
(21633, 2, 218, 1633, 'hadith', 'وعنه قال: قال رسول الله صلى الله عليه وسلم : «صِنفان من أهل النار لم أرهما: قوم معهم سياط كأذناب البقر يضربون بها الناس، ونساء كاسيات عاريات مميلات مائلات، رءوسهن كأسنمة البخت المائلة لا يدخلن الجنة، ولا يجدن ريحها، وإن ريحها ليوجد من مسيرة كذا وكذا» ((رواه مسلم)). معنى ((كاسيات)) اي من نعمة الله ((عاريات)) من شكرها ، وقيل معناه: تستر بعض بدنها ، وتكشف بعضه إظهارا بحالها ونحوه ، وقيل : معناه تلبس ثوبا رقيقا يصف لون بدنها . وأما ( مائلات ) فقيل : معناه عن طاعة الله ، وما يلزمهن حفظه . ( مميلات ) أي يعلمن غيرهن فعلهن المذموم ، وقيل : مائلات يمشين متبخترات ، مميلات لأكتافهن . وقيل : مائلات يمشطن المشطة المائلة ، وهي مشطة البغايا . مميلات يمشطن غيرهن تلك المشطة . ومعنى ( رءوسهن كأسنمة البخت ) أن يكبرنها ويعظمنها بلف عمامة أو عصابة أو نحوهما .', 'The Messenger of Allah (ﷺ) said, "There are two types of people who will be punished in Hell and whom I have not seen: men having whips like the tails of cows and they will be beating people with them, and, women who will be dressed but appear to be naked, inviting to evil; and they themselves will be inclined to it. Their heads will appear like the humps of the Bactrian camel inclined to one side. They will not enter Jannah and they will not smell its fragrance which is perceptible from such and such a distance.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1633', 'Riyad as-Salihin 1633', 'ریاض الصالحین 1633', null, 'يُحَذِّرُ النبيُّ صلى الله عليه وسلم مِن صِنفين مِن الناس مِن أهل النار لم يَرَهما ولم يُوجدا في عَصرِه، بل سيكونان بعده:

الصنف الأول: قومٌ معهم سِيَاطٌ كذُيول البقر طويلة، يضربون بها الناس، وهم الشُّرَطُ وأعوانُ الظلمة الذين يضربون الناس بغير حق. 

والصنف الثاني: نساءٌ خَلَعْنَ ثوبَ العِفَّة والحياء الذي فُطِرَتْ عليه الأنثى عادةً.

ووصفهن: كاسيات في الحقيقة، عاريات في المعنى؛ لأنهن يَلبَسنَ ثيابًا رقاقًا تَصِفُ البَشَرَة، ويَستُرْنَ بعضَ بَدنِهِن ويَكشفنَ بعضَه؛ إظهارًا للجمال، 
مُمِيْلات قلوب الرجال إليهنَّ بِلبسِهنّ وتَبَخْتُرِهُنّ بالمشي، مميلات لأكتافِهن، ويُمِلْنَ غيرَهنَّ إلى الانحراف والزيغ الواقعات فيه، 
ومن صفاتهن: رؤوسُهنَّ مِثلُ سنام الجمل المائل، فهنّ يُعَظِّمْنَ حَجْمَ رؤوسِهِنَّ ويُكبرنها بلف عصابة ونحوها، 
والتشبيه بأسنمة البُخت إنما هو لارتفاع شعرِهنّ وظفائرِهنّ فوقَ رؤوسهن، وتَكَسُّرها بما يضفرنه حتى تميلَ إلى ناحية من نواحي الرأس كما يميل سنام البعير. 
فمَنْ كُنّ بهذه الصفات ففيهن هذا الوعيد الشديد بأنْ لا يَدخُلْنَ الجنة ولا يَجِدْنَ ريحَها ولا يَقْرَبْنَ منها، وريح الجنة يوجد ويُشَمُّ من مسافة بعيدة.', 'تحريم ضربِ الناس وإيذائهم دون إثم فعلوه أو ذنب اقترفوه.
تحريم إعانة الظلمة على ظلمهم.
تحذير النساء من التبرُّج والسفور ولبس الضيق والشَّفاف الذي يَصف العورة أو يُجَسِّمها.
حث المرأة المسلمة على الالتزام بأوامر الله، والبُعد عمّا يُسخِطه ويجعلها تستحق العذاب الأليم المقيم في الآخرة.
الحديث من دلائل نبوَّته عليه الصلاة والسلام، حيث أخبر عليه الصلاة والسلام عن الأمور الغيبية التي لم تقع، ووقعت كما أخبر.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8903', false),
(21634, 2, 218, 1634, 'hadith', 'عن جابر رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «لا تأكلوا بالشمال، فإن الشيطان يأكل ويشرب بشماله».', 'I heard the Messenger of Allah (ﷺ) as saying: "Do not eat with your left hand, because Satan eats and drinks with his left hand.".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1634', 'Riyad as-Salihin 1634', 'ریاض الصالحین 1634', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21635, 2, 218, 1635, 'hadith', 'عن ابن عمر رضي الله عنهما أن رسول الله قال: «لا يأكلن أحدكم بشماله، ولا يشربن بها. فإن الشيطان يأكل بشماله ويشرب بها».', 'The Messenger of Allah (ﷺ) said, "No person should eat and drink with his left hand for Satan eats with his left hand and drinks with his left hand.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1635', 'Riyad as-Salihin 1635', 'ریاض الصالحین 1635', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21636, 2, 218, 1636, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إن اليهود والنصارى لا يصبغون، فخالفوهم» ((متفق عليه)) . المُرَادُ: خِضَابُ شَعْرِ اللِّحْيةِ والرَّأسِ الأبْيضِ بِصُفْرةٍ أوْ حُمْرةٍ، وأمَّا السَّوادُ، فَمنْهيُّ عَنْهُ كَما سَنَذْكُرُ في الْباب بعْدَهُ، إنْ شَاءَ اللَّه تَعَالَى.', 'I heard the Messenger of Allah (ﷺ) as saying: "Jews and Christians do not dye their hair, so act differently from them.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', null, 'رياض الصالحين 1636', 'Riyad as-Salihin 1636', 'ریاض الصالحین 1636', null, null, null, null, 'sunnah.com', null, false, null, false),
(21637, 2, 218, 1637, 'hadith', 'عن جابر رضي الله عنه قال: أتي بأبي قحافة والد أبي بكر الصديق رضي الله عنهما يوم فتح مكة ورأسه ولحيته كالثغامة بياضًا، فقال رسول الله صلى الله عليه وسلم : «غيروا هذا واجتنبوا السواد».', 'Abu Quhafah, father of Abu Bakr (May Allah be pleased with them) was presented to the Messenger of Allah (ﷺ) on the day of the conquest of Makkah and his head and beard were snow white. The Messenger of Allah (ﷺ) said, "Change it (i.e., dye it and avoid black colour).".', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1637', 'Riyad as-Salihin 1637', 'ریاض الصالحین 1637', 'رواه مسلم', 'معنى الحديث: أنه أتي بأبي قحافة -والد أبي بكر الصديق- إلى النبي صلى الله عليه وسلم يوم فتح مكة ورأسه ولحيته كَالثَّغَامَةِ ، وهو نوع من النبات أبيض، فلما رآه صلى الله عليه وسلم على تلك الحال، قال: "غَيِّرُوا هذا واجْتَنِبوا السَّوَاد" فأمر بتغيير الشَّيب وأن يُجَنَّب السَّواد؛ لأن السَّواد يعني أنه يُعيد الإنسان شابًّا، فكان ذلك مضادة لفطرة الله عز وجل وسنته في خلقه، وأما بقية الأصباغ كالحُمرة والصُفرة أو بالحناء والكَتَم مخلوطين فلا بأس، إذا خرج اللون عن السَّواد، بل بين السَّواد والحُمرة، فهذا لا بأس به، والمنهي عن صبغه به هو السَّواد الخالص، وفي مسلم من حديث أنس رضي الله عنه خضب أبو بكر وعمر رضي الله عنهما بالحناء والكَتَم.', 'كراهة ترك الشَّيب على حاله، واستحباب تغيير لونه.
يحرم تغيير الشَّيب بالسَّواد الخالص؛ لما في ذلك من الخِداع.', 'الثَّغَامَة : نَبْت أبيض يُشبه الشَّيب يُسمى العَوسَج.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8909', false),
(21638, 2, 218, 1638, 'hadith', 'عن ابن عمر رضي الله عنهما قال: نهى رسول الله صلى الله عليه وسلم عن القزع.', 'The Messenger of Allah (ﷺ) forbade shaving a part of the head..', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1638', 'Riyad as-Salihin 1638', 'ریاض الصالحین 1638', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21639, 2, 218, 1639, 'hadith', 'وعنه قال: رأى رسول الله صلى الله عليه وسلم صبيًا قد حلق بعض شعر رأسه وترك بعضه فنهاهم عن ذلك وقال: «احلقوه كله، أو اتركوه كله». رواه أبو داود بإسناد صحيح على شرط البخاري ومسلم.', 'The Messenger of Allah (ﷺ) saw a boy, some portion of whose head was shaved and some of it was left out. He prohibited them from that and said, "Shave the whole of it or leave the whole of it.".', null, 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1639', 'Riyad as-Salihin 1639', 'ریاض الصالحین 1639', null, 'رأى رسول الله صلى الله عليه وسلم صَبِيًّا قد حُلق بعض شعر رأسه وتُرك بَعضه، وهذا الفعل يُسمى القزع، فَنَهَاهُم عن أن يفعلوا ذلك بالصبي مرة ثانية، وقال لهم: لا يُحلق جزء منه ويترك البقية، وهذا النهي إما على الكراهة وإما على التحريم، فينبغي اجتنابه مطلقًا.', 'النهي عن حَلْق بعض شعر الرأس دون بعض لغير حاجة؛ لما فيه من التشبه بأهل الكتاب.
جواز حلق شعر الرأس كله، وجواز تركه بشرط عدم التشبه بالنساء.
فيه نهي أولياء الأمور عن حلق بعض شعر الصبية وترك بعضه وإن كان القلم مرفوعا عنهم.
عدم جواز تمكين الصبي من فعل المحرمات وعلى أولياء أمورهم نهيهم.
بيان اهتمام الإسلام بالمظهر الخارجي وتحسينه مما يؤدي إلى تميز المسلم.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8906', false),
(21640, 2, 218, 1640, 'hadith', 'عن عبد الله بن جعفر رضي الله عنهما أن النبي صلى الله عليه وسلم أمهل آل جعفر رضي الله عنه ثلاثًا، ثم أتاهم فقال: "لا تبكوا على أخي بعد اليوم". ثم قال: "ادعوا لي بني أخي" فجيء بنا كأننا أفرخ فقال: "ادعوا لي الحلاق" فأمره، فحلق رءوسنا". رواه أبو داود بإسناد صحيح على شرط البخاري ومسلم.', 'The Prophet (ﷺ) gave respite for three days to the family of Ja''far (after his martydom). Then he came and said, "Don''t weep for my brother after this day." He said, "Bring all of my nephews to me." We were accordingly brought as if we were chickens. Then he said, "Call for me a barber." He directed him to shave our heads which he did..', 'عبد الله بن جعفر رضي الله عنهما', '''Abdullah bin Ja''far (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1640', 'Riyad as-Salihin 1640', 'ریاض الصالحین 1640', null, 'معنى الحديث: أنه عندما استشهد جعفر بن أبي طالب في غزوة مؤتة، أمهل النبي صلى الله عليه وسلم أهله ثلاثا من أجل أن تَطيب نَفوسهم ويذهب ما في نفوسهم من الحزن والأسى، ثم قال لهم: "لا تَبْكُوا على أَخِي بعد اليوم" أي نهاهم عن البكاء بعد ثلاثة أيام؛ لأن الصدمة الأولى وزمن الحزن لا يطول ولا يستمر. 
والنهي هنا: للتنزيه لإباحة البكاء بعد ثلاثة أيام ما لم يقترن به محرم. 
ثم قال: «ادعوا لي بَنِي أخِي» وهم محمد وعبد الله وعوف أولاد جعفر، قال عبد الله: "فجيء بِنَا كأننا أفْرُخٌ" الفَرَخ ولد الطائر، وذلك لما أصابهم من الحزن على فقد والدهم.
قال: "ادعوا لي الحلَّاق. فأمره، فَحَلَق رؤوسنا" أي أن النبي صلى الله عليه وسلم أمر بحلق رؤوسهم فحُلقت، لما رأى من اشتغال أمهم أسماء بنت عميس رضي الله عنها عن ترجيل شعورهم بما أصابها من قتل زوجها في سبيل الله فأشفق عليهم من الوَسَخ والقمل، فإذا أزيل صار في ذلك فائدة ومصلحة وراحة لأمهم التي جاءها ما يشغلها عن العناية بشعر أولادها. 
تنبيه: معلوم أن الحلق عند المصيبة لا يجوز، وقد جاء في الحديث: (لعن الرسول صلى الله عليه وسلم الصَّالقة والحَالقة والشَّاقة).
والحالقة: التي تحلق شعرها عند المصيبة، والشاقة: التي تشق ثوبها عند المصيبة، والصالقة: التي ترفع صوتها عند المصيبة، والحلق لأولاد جعفر ليس اعتراضا على موته، ولكن المقصود من هذا الحَلق لأولاد جعفر بعد موته -رضي الله تعالى عنه وأرضاه- هو كون أمهم كانت منشغلة عن العناية برؤوسهم، فخشي أن يُصيبهم شيء من القَمْل فأمر بحلق رءوسهم -صلوات الله وسلامه وبركاته عليه-، ولم يكن الحلق تأثرًا بالمصيبة.', 'جواز حلق جميع شعر الرأس، خاصة للصبيان.
جواز حلق شعر الرأس في غير حج وعمرة.
استحباب مواساة أهل الميت، خاصة من استشهد في سبيل الله، وأن يدعوهم إلى فعل ما يتفاءل به لإزالة الحُزن وتَفْرِيج الكَرْب.
جواز البكاء على الميت من غير فعل محرم، كشَقِّ الجِيُوب ولَطْمِ الخُدود، وجواز الحداد عليه لمدة ثلاثة أيام، ولا يجوز أكثر من ذلك لغير الزوجة.
النهي عن البكاء على الميت بعد ثلاثة أيام، إلا أن النهي للتنزيه.
الحث على كفالة اليتيم والرفق به.
المؤمنون إخوة في الله.
منزلة عبد الله بن جعفر عند رسول الله -صلى الله عليه وسلم-.
تحمل الحديث حال الصِّغر والتحديث به في الكِبَر.
جواز تأخير التعزية إلى اليوم الثالث.', 'أفْرُخٌ : أولاد الطائر، وشُبِّهوا بذلك لما أصابهم من الحُزن على فقدان والدهم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8910', false)
