insert into hadith (id, collection_id, chapter_id, number_in_book, kind, arabic, translation_en, narrator_ar, narrator_en, grade_ar, reference_ar, reference_en, reference_ur, full_ref_ar, explanation_ar, benefits_ar, word_meanings_ar, source, source_ref, daily_ok, review_note, deleted) values
(21641, 2, 218, 1641, 'hadith', 'عن علي قال: نهى رسول الله صلى الله عليه وسلم أن تحلق المرأة رأسها.', 'The Messenger of Allah (ﷺ) prohibited a woman from shaving her head..', null, '''Ali (May Allah be pleased with him) said:', null, 'رياض الصالحين 1641', 'Riyad as-Salihin 1641', 'ریاض الصالحین 1641', 'رواه النسائي', null, null, null, 'sunnah.com', null, false, null, false),
(21642, 2, 218, 1642, 'hadith', 'وعَنْ أسْمَاءَ رَضِيَ اللَّه عنْهَا: أنَّ امْرأَةً سألتِ النبيَّ ﷺ فَقَالتْ: يا رَسُولَ اللَّه، إنَّ ابْنَتِي أصَابَتْهَا الْحَصْبةُ، فتَمَرَّقَ شَعْرُهَا، وإنِّي زَوَّجْتُها، أفَأَصِلُ فِيهِ؟ فقالَ: لَعَنَ اللَّه الْواصِلةَ والْمَوصولة متفقٌ عليه. وفي روايةٍ: الواصِلَةَ والمُسْتوصِلَةَ. قَوْلَهَا:"فَتَمرَّقَ"هو بالرَّاءِ، ومعناهُ: انْتثر وَسَقَطَ،"والْوَاصِلة": التي تَصِلُ شَعْرهَا، أو شَعْر غَيْرِهَا بشَعْرٍ آخَرَ."والمَوْصُولة": التي يُوصَلُ شَعْرُهَا. "والمُستَوصِلَةُ": التي تَسْأَلُ منْ يَفْعَلُ ذلكَ لَهَا.', 'A woman came to the Prophet (ﷺ) and said: "O Messenger of Allah! I have a daughter who had an attack of small pox and her hair fell off. Now I want to celebrate her marriage. Can I get her a wig?" Thereupon the Prophet (ﷺ) said, "Allah has cursed the maker and wearer of a wig.".', null, 'Asma'' (May Allah be pleased with her) said:', null, 'رياض الصالحين 1642', 'Riyad as-Salihin 1642', 'ریاض الصالحین 1642', null, null, null, null, 'sunnah.com', null, false, null, false),
(21643, 2, 218, 1643, 'hadith', 'وعَنْ عائشة رضي اللَّه عنْهَا نَحْوُهُ، متفقٌ عليه.', 'A similar narration was narrated on the authority of ''Aishah.', null, null, null, 'رياض الصالحين 1643', 'Riyad as-Salihin 1643', 'ریاض الصالحین 1643', null, null, null, null, 'sunnah.com', null, false, null, false),
(21644, 2, 218, 1644, 'hadith', 'وَعَنْ حميْدِ بن عبْدِ الرَّحْمن أنَّهُ سَمِعَ مُعاويَةَ رضي اللَّه عنْهُ عامَ حجَّ علَى المِنْبَر وَتَنَاول قُصَّةً مِنْ شَعْرٍ كَانَتْ في يَدِ حَرِسيٍّ فَقَالَ: يَا أهْل المَدِينَةِ أيْنَ عُلَمَاؤكُمْ؟، سمِعْتُ النبيَّ صَلّى اللهُ عَلَيْهِ وسَلَّم يَنْهَى عنْ مِثْلِ هَذِهِ ويقُولُ: «إنًَّمَا هَلَكَتْ بنُو إسْرَائِيل حِينَ اتخذ هذه نِسَاؤُهُمْ» متفقٌ عليه.', 'I saw Mu''awiyah (May Allah be pleased with him) during the Hajj (pilgrimage) standing on the pulpit. He took from the guard a bunch of hair, and said: "O people of Al-Madinah! Where are your scholars? (Why do they do not prohibit you) I heard the Prophet (ﷺ) prohibiting from using this (false hair) and saying, ''The people of Bani Israel were ruined when their women wore such hair."''', null, 'Humaid bin ''Abdur-Rahman (May Allah be pleased wth him) said:', 'صحيح', 'رياض الصالحين 1644', 'Riyad as-Salihin 1644', 'ریاض الصالحین 1644', null, 'يخبر حُميد بن عبد الرحمن بن عوف رحمه الله أنه سمع معاوية رضي الله عنه عام حَجَّ وهو على المِنْبَر، وبيده قُصَّة من شَعْرٍ، وهي شَعْر مكْفُوف بعضه على بعض، كانت بيد أَحَد خدمه الذين يحرسونه فتناولها منه، فقال: يا أهل المدينة أين عُلَمَاؤُكُمْ؟! من باب الإنكار عليهم بإهمالهم إنكار هذا المنكر وغفلتهم عن تغييره، ثم أخبرهم رضي الله عنه أن النبي صلى الله عليه وسلم أخبره أن الله تعالى أهلك بني إسرائيل عندما اتخذ نساؤها هذه القصة، ووصلها بالشعر، وإنما أهلكوا جميعا؛ لإقرارهم المنكر مع ما انضم إلى ذلك من ارتكابهم ما ارتكبوه من المناهي.', 'جواز تناول الشيء في الخطبة؛ ليراه من لم يكن رآه عند الحاجة.
جواز اتخاذ الأمراء للحراس.
وجوب اهتمام ولاة الأمور بإنكار المنكرات، والحث على إزالتها والتَّأنيب على من قَصَّر في إنكارها ممن هو أهل لذلك.
الإنكار علنًا لا سيما إذا كان المنكر فاشيًا، فيفشي إنكاره تأكيدا؛ ليحذر منه.
النهي عن وصْلِ الشَّعْر بغيره، أو وضع شعر كامل على الرأس ولو للأصلع، وهو: ما يسمى بالباروكة.
ظهور المُنْكرات في عامة الناس وعدم إنكارها من الخاصة؛ سبب لاستحقاق الهلاك، وعموم العقاب من الله -تعالى-.
وجود المنكرات في خير القرون.
إباحة الحديث عن بني إسرائيل، وكذا غيرهم من الأمم؛ للتحذير مما وقعوا فيه.', 'قُصَّة : خَصْلَة من الشَّعر.
حَرَسِيٍّ : شُرطي، وهو: غُلام الأمير.
هلكت : أي: كان هذا سبب هلاكهم.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8915', false),
(21645, 2, 218, 1645, 'hadith', 'عن ابن عمر رضي الله عنه أن رسول الله صلى الله عليه وسلم لعن الواصلة والمستوصلة والواشمة والمستوشمة.', 'The Messenger of Allah (ﷺ) cursed the maker and wearer of a wig and the tattooer and the one who is tattooed..', 'ابن عمر رضي الله عنه', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1645', 'Riyad as-Salihin 1645', 'ریاض الصالحین 1645', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21646, 2, 218, 1646, 'hadith', 'عن ابن مسعود رضي الله عنه قال: لعن الله الواشمات والمستوشمات والمتنمصات والمتفلجات بالحسن، المغيرات خلق الله! فقالت له امرأة في ذلك فقال: وما لي لا ألعن من لعنه رسول الله صلى الله عليه وسلم وهو في كتاب الله؟! قال الله تعالى: {وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا} ((الحشر:7)).((متفق عليه)). المتفلجة هي: التي تبرد من أسنانها ليتباعد بعضها من بعض قليلا، وتحسنها وهو الوشر. والنامصة: التي تأخذ من شعر حاجب غيرها، وترققه ليصير حسنا. والمتنمصة: التي تأمر من يفعل بها ذلك.', 'Allah has cursed those women who practise tattooing and those women who have themselves tattooed, and those women who get their hair removed from their eyebrows and faces (except the beard and the mustache), and those who make artificial spaces between their teeth for beauty, whereby they change Allah''s creation. A woman started to argue with him, saying: "What is all this?" He replied: "Why should I not curse those whom the Messenger of Allah (ﷺ) cursed and who are cursed in Allah''s Book? Allah, the Exalted, has said in His Book:"And whatsoever the Messenger (Muhammad (ﷺ)) gives you, take it; and whatsoever he forbids you, abstain (from it)." (59:7).', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him) said:', null, 'رياض الصالحين 1646', 'Riyad as-Salihin 1646', 'ریاض الصالحین 1646', null, null, null, null, 'sunnah.com', null, false, null, false),
(21647, 2, 218, 1647, 'hadith', 'عن عائشة رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم : «من عمل عملا ليس عليه أمرنا فهو رد».', 'The Messenger of Allah (ﷺ) said, "He who does something contrary to our way (i.e., Islam) will have it rejected.".', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1647', 'Riyad as-Salihin 1647', 'ریاض الصالحین 1647', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21648, 2, 218, 1648, 'hadith', 'عن أبي قتادة رضي الله عنه عن النبي صلى الله عليه وسلم قال: «إذا بال أحدكم، فلا يؤخذن ذكره بيمينه، ولا يستنجي بيمينه، ولا يتنفس في الإناء» ((متفق عليه)) وفي الباب أحاديث كثيرة صحيحة.', 'The Prophet (ﷺ) said, "Do not touch your private parts with your right hand while urinating, nor for washing or cleaning (your private parts); and do not breathe into the drinking vessel from which you drink.".', 'أبي قتادة رضي الله عنه', 'Abu Qatadah (May Allah be pleased with him) said:', null, 'رياض الصالحين 1648', 'Riyad as-Salihin 1648', 'ریاض الصالحین 1648', null, null, null, null, 'sunnah.com', null, false, null, false),
(21649, 2, 218, 1649, 'hadith', 'عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: "لا يمشي أحدكم في نعل واحدة لينعلهما جميعًا او ليخلعهما جميعًا". وفي رواية " أو ليحفهما جميعًا.', 'The Messenger of Allah (ﷺ) said, "None of you should walk wearing one shoe; you should either wear them both or take them off both.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1649', 'Riyad as-Salihin 1649', 'ریاض الصالحین 1649', 'متفق عليه', 'نهى النبي صلى الله عليه وسلم عن المشي في نعل واحدة، فإما أن يلبس النعلين جميعا، أو يخلعهما جميعا ويكون حافيا، وهذا الأدب دليل من الأدلة على دقة الشريعة الإسلامية وشمولها لجميع مناحي الحياة.', 'الإسلام كامل، ويدعو إلى الكمال، وجميل يحب الجمال؛ فإن مشي الإنسان في نعل واحدة، أو خفٍّ واحدة، ففيه مُثْلَةٌ وتشهير، ومخالفة للمعتاد؛ لذا نهى عن المشي في نعل واحدة، فإما أن ينعل الرجلين جميعًا، وإما أن يتركهما، ويكون حافيًا، وكان صلى الله عليه وسلم تارة ينتعل، وتارة يمشي حافيًا.
النهي عن المشي في نعل واحدة، وهذا النهي عند جمهور العلماء للكراهة لا للتحريم.
جواز لبس النعلين وعدمه.
اهتمام الإسلام بالمظهر الطيب الموافق لجميل المروءة؛ لأن المشي بنعل واحدة يخالف سجية المشي، ولا يأمن من العثار.', 'لينعلهما جميعا : يلبس النعلين في كلتا رجليه.
ليخلعهما : أي ينزع رجليه من النعلين.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5369', false),
(21650, 2, 218, 1650, 'hadith', 'وعنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «إذا انقطع شسع نعل أحدكم، فلا يمشِ في الأخرى حتى يصلحها».', 'I heard the Messenger of Allah (ﷺ) saying, "When the lace of one of the shoes of any one of you is cut off, he should not walk with the other until he has got the lace repaired.".', null, 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1650', 'Riyad as-Salihin 1650', 'ریاض الصالحین 1650', 'رواه مسلم', 'نهى النبي صلى الله عليه وسلم المسلم إذا انقطع نعله ولم يمكنه المشي فيه، فلا يمشي في نعل واحدة، بل عليه أن يصلح ما فسد أو يخلع الأخرى ويمشي حافيًا، وسبب ذلك ما فيه من التشبه بالشيطان، كما في أحاديث أخرى.', 'كراهة المشي بنعل واحدة، فإما أن ينتعلهما جميعا أو يخلعهما جميعا.
قد يدخل في هذا كل لباس شفع كالخفين وإخراج اليد الواحدة من الكُم دون الأخرى؛ إذ الأصل العدل بين الجوارح فأعطِ كل ذي حقٍّ حقه.', 'الشَّسْعُ : السَّير الذي يُمسك النَّعل بالقَدَم، ويكون على ظهرها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8907', false),
(21651, 2, 218, 1651, 'hadith', 'عن جابر رضي الله عنه أن رسول الله صلى الله عليه وسلم نهى أن ينتعل الرجل قائمًا".', 'The Messenger of Allah (ﷺ) forbade a person wearing (tying up) his shoe while standing..', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him) said:', 'حسن', 'رياض الصالحين 1651', 'Riyad as-Salihin 1651', 'ریاض الصالحین 1651', 'رواه أبو داود بإسناد حسن', null, null, null, 'sunnah.com', null, false, null, false),
(21652, 2, 218, 1652, 'hadith', 'عن ابن عمر رضي الله عنهما عن النبي صلى الله عليه وسلم قال: «لا تتركوا النار في بيوتكم حين تنامون».', 'The Prophet (ﷺ) said, "Do not keep the fire burning in your homes when you go to bed.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1652', 'Riyad as-Salihin 1652', 'ریاض الصالحین 1652', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21653, 2, 218, 1653, 'hadith', 'عن أبي موسى الأشعري رضي الله عنه قال: احترق بيت بالمدينة على أهله من الليل، فلما حدث رسول الله صلى الله عليه وسلم بشأنهم قال: «إن هذه النار عدو لكم، فإذا نمتم فأطفئوها».', 'A house in Al-Madinah was burnt with its occupants inside it one night. When this was reported to the Messenger of Allah (ﷺ) he said, "Fire is your enemy. So, put it out before going to bed.".', 'أبي موسى الأشعري رضي الله عنه', 'Abu Musa Al-Ash''ari (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1653', 'Riyad as-Salihin 1653', 'ریاض الصالحین 1653', 'متفق عليه', 'احترق بيت بالمدينة في الليل، فبلغ ذلك النبيَّ صلى الله عليه وسلم فأخبرهم بأن هذه النار عدو لأهلها إذا لم يتحرزوا من شر لهيبها وإحراقها، ثم أمرهم -عليه الصلاة والسلام- بإطفائها قبل النوم دفعاً لشرها من الاشتعال والحريق ونحو ذلك.', 'لزوم إطفاء النار قبل النوم.
حرص رسول الله -صلى الله عليه وسلم- على أمته في أمور الدنيا والآخرة.
يدخل في معنى النار إطفاء قارورات الغاز وقواطع الكهرباء ونحوها، حتى يؤمن شرها من الحريق والاختناق.', 'من الليل : أي: في الليل.
حُدِّث : أي: أُخبر.
أطفئوها : أخمدوها.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4235', false),
(21654, 2, 218, 1654, 'hadith', 'عن جابر رضي الله عنه عن النبي صلى الله عليه وسلم قال: "غطوا الإناء، وأوكئوا السقاء، وأغلقوا الأبواب، وأطفئوا السراج، فإن الشيطان لا يحل سقاء، ولايفتح بابًا ولايكشف إناءً، إن لم يجد أحدكم إلا أن يعرض على إنائه عودا، ويذكر اسم الله، فليفعل، فإن الفويسقة تضرم على أهل البيت بيتهم" ((رواه مسلم)) "الفويسقة: الفأرة، و"تضرم": تحرق.', 'The Messenger of Allah (ﷺ) said, "Cover up the (kitchen) containers (i.e., pots, pans, etc.), tie up the mouth of the water-skin, lock up the doors and extinguish the lamps, because Satan can neither untie the water-skin nor open the door nor uncover the containers. If one can cover the cooking pot even by placing a piece of wood across it, and pronounce the Name of Allah on it, let him do it. A mouse can sometimes cause a house to burn along its dwellers."', 'جابر رضي الله عنه', 'Jabir (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1654', 'Riyad as-Salihin 1654', 'ریاض الصالحین 1654', null, 'أمر النبي صلى الله عليه وسلم بتغطية الإناء؛ صونًا له من الحشرات، وسائر المؤذيات ولما قد ينزل فيه من الوباء، وأن تغلق الأسقية، وأن تغلق الأبواب لما في ذلك من المصالح الدينية والدنيوية، وحراسة الأنفس والأموال، من أهل العبث والفساد.
وأرشد إلى أن تطفأ السرج لما في ذلك من حفظ البيت وأهله لما قد يخشى عليهم من ضرر الاحتراق. 
والحديث محمول على وقت النوم ليلا، وأخبر أن الشيطان لا يفتح سِقاء مغلقا، ولا بابا ولا يَكشف عن الأواني المغلقة. 
فإذا لم يمكن تغطية الإناء بما يستوعبه بحيث لا يظهر ما بداخله أو بعضه فلا يدعه مشكوفا، بل يجعل عليه عودا عرضًا، ويسمي الله تعالى عند تغطية الإناء، وإيكاء الأسقية، وإغلاق الأبواب، وذكر أن السِّراج وغيره من المواد المشتعلة إذا تركت على حالها ولم تطفأ قبل النوم؛ فإن الغالب على الفويسقة العَبَث به؛ وقد يكون ذلك سببا لإحراق أهل البيت وقت نومهم.', 'تغطية أوعية الطعام، وسد أفواه أوعية الماء، وتغطيتها أيضاً؛ وذلك صونًا لها من الحشرات والأوساخ، وكل ما يؤذي ويستقذر.
يجزئ تغطية بعض الإناء، إذا لم يمكن تغطيته كله.
إغلاق أبواب البيوت والغرف؛ احتياطا من الفُسَّاق واللصوص والشياطين، وكل خطر يتوقع.
الشيطان يعبث بشؤون الناس حين غفلتهم، ويغري هوام الأرض بالإيذاء؛ لذا يجب الأخذ بالحيطة والحذر من كل شرٍّ متوقع.
أن ذكر الله -تعالى- يمنع الشيطان من العَبَث.
استحباب التسمية عند وضع الأشياء واستعمالها.
نُصح النبي -صلى الله عليه وسلم- لأمته.', 'أَوْكِئُوا السِّقَاء : اربِطوا السِّقَاء؛ لئلا يدخلها شيء.والسقاء: ظَرف من الجِلد يُوضع فيه الماء.
السِّراج : المِصباح.
يَعْرِض على إنَائِه عُوْدَا : أي: يَمُدُّ عليه خَشَبَة عرضًا.
الفُوَيْسِقَة : الفأرة.
تُضْرِمُ : تُحْرِق.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8925', false),
(21655, 2, 218, 1655, 'hadith', 'عن ابن عمر رضي الله عنهما قال : «نهينا عن التكلف».', 'We have been forbidden to go into excess..', 'ابن عمر رضي الله عنهما', '''Umar (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1655', 'Riyad as-Salihin 1655', 'ریاض الصالحین 1655', 'رواه البخاري', null, null, null, 'sunnah.com', null, false, null, false),
(21656, 2, 218, 1656, 'hadith', 'عن مسروق قال : دخلنا على عبدالله بن مسعود رضي الله عنه فقال : يا أيها الناس من علم شيئا فليقل به، ومن لم يعلم، فليقل :الله أعلم، فإن من العلم أن يقول الرجل لما لا يعلم: الله أعلم . قال الله تعالى لنبيه صلى الله عليه وسلم :{قل ما أسألكم عليه من أجر وما أنا من المتكلفين}.', 'We visited ''Abdullah bin Mas''ud (May Allah be pleased with him) and he said to us: O people! He who has the knowledge of any matter may convey it to the others. And he who has no knowledge, thereof, should say: "Allahu a''lam (Allah knows better)." It is a part and parcel of knowledge that a man who has no knowledge of a matter should say: "Allah knows better." Allah said to His Prophet (ﷺ):"Say (O Muhammad (ﷺ)): ''No wage do I ask of you for this (the Qur''an), nor am I one of the Mutakallifun (those who pretend and fabricate things which do not exist)."'' (38:86).', 'مسروق قال : دخلنا على عبدالله بن مسعود رضي الله عنه', 'Masruq (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1656', 'Riyad as-Salihin 1656', 'ریاض الصالحین 1656', 'رواه البخاري', 'معنى الحديث: أن الإنسان إذا سُئل عن شيء يعلمه، فليبينه للناس ولا يكتمه، وأما إذا سئل عن شيء لا يعلمه، فليقل: الله أعلم ولا يتكلف الجواب.
"فإن من العلم أن يقول لِمَا لا يَعْلَم: الله أعلم" أي أن من العلم أن يقول الإنسان لما لا يعلم : "الله أعلم"؛ لأن الذي يقول لا أعلم وهو لا يعلم هو العالم حقيقة هو الذي علم قَدْر نفسه وعلم منزلته وأنه جاهل فيقول لما لا يعرف الله أعلم.
وعند مسلم بلفظ: "فإنه أعلم لأحدكم أن يقول لما لا يعلم: الله أعلم". 
والمعنى: أنه أحسن لعلمه وأتم وأنفع له أن يقول لما لا يعلمه: "الله أعلم".
ثم استدل ابن مسعود رضي الله عنه بقوله تعالى : (قل ما أسألكم عليه من أجر وما أنا من المتكلفين) أي لا أسألكم على ما جئت به من الوحي أجرا تعطونني إياه وإنما أدلكم على الخير وأدعوكم إلى الله عز وجل .
(وما أنا من المتكلفين) أي من الشاقين عليكم أو القائلين بلا علم.
فالحاصل: أنه لا يجوز للإنسان أن يفتي إلا حيث جازت له الفتوى، وإن كان الله تعالى قد أراد أن يكون إمامًا للناس يفتيهم ويهديهم إلى صراط مستقيم فإنه سيكون وإن كان الله لم يرد ذلك فلن يفيده تجرأه في الفتوى ويكون ذلك وبالًا عليه في الدنيا والآخرة.', 'عدم التكلف في المسائل العلمية، كأن يسأل عن شيء غير واضح له فيتحمل جوابا له، وربما أبعد عن الحقيقة في بيانه.
لا ينقص من قَدْرِ العالم أن يجهل بعض مسائل العلم، ويعلن عدم معرفته بها.
الاقتداء برسول الله -صلى الله عليه وسلم- في عدم التَّكَلف مطلقًا.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8934', false),
(21657, 2, 218, 1657, 'hadith', 'عن عمر بن الخطاب رضي الله عنه قال: قال النبي صلى الله عليه وسلم :"الميت يُعذب في قبره بما نِيح عليه ". وَفِي روايةٍ:"مَا نِيحَ علَيْهِ".', 'The Prophet (ﷺ) said, "The deceased is tortured in his grave for bewailing over him.".', 'عمر بن الخطاب رضي الله عنه', '''Umar bin Al-Khattab (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1657', 'Riyad as-Salihin 1657', 'ریاض الصالحین 1657', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21658, 2, 218, 1658, 'hadith', 'عن ابن مسعود رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «ليس منا من ضرب الخدود، وشق الجيوب، ودعا بدعوى الجاهليه».', 'The Messenger of Allah (ﷺ) said, "He who (on befalling a calamity) slaps his cheeks, tears his clothes and follows the ways and traditions of the Days of Ignorance is none of us.".', 'ابن مسعود رضي الله عنه', 'Ibn Mas''ud (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1658', 'Riyad as-Salihin 1658', 'ریاض الصالحین 1658', 'متفق عليه', 'نَهَى النبيُّ صلى الله عليه وسلم وحَذَّرَ عن بعض أفعال أهل الجاهلية فقال: ليس منا: 

الأول: مَن لَطَمَ الخُدُود، وخَصَّ الخَدّ لكونه الغالب في ذلك، وإلا فَضَرْبُ بقية الوجه داخل في النهي. 

والثاني: شَقَّ ما يُفْتَح من الثوب ليدخل فيه الرأس من شدّة الجزع. 

والثالث: دَعى بدعوى أهل الجاهلية كالدعاء بالويل والثُّبُور والنياحة والنُّدْبَة وغيرها.', 'هذا الوعيد في الحديث يدل على أنَّ هذه الأعمال من كبائر الذنوب.
وجوب الصبر على المصيبة، وتحريم التَّسَخُّط مِن أقدار الله المؤلمة، وإظهار ذلك: بالنياحة أو النَّدْب أو الحَلْق أو الشَّقّ أو غير ذلك.
تحريم تَقلِيْد الجاهلية بأمورهم التي لم يُقِرّهم الشارع عليها.
لا بأس من الحُزْن والبكاء، فهو لا ينافي الصبر على قضاء الله تعالى، وإنما هو رحمة جعلها الله في قلوب الأقارب والأحباب.
على المسلم الرضا بقضاء الله، فإنْ لم يَرْضَ فالصبر واجب عليه.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5380', false),
(21659, 2, 218, 1659, 'hadith', 'عن أبي بردة قال: وجع أبو موسى، فغشي عليه، ورأسه في حجر امرأة من أهله، فأقبلت تصيح برنة فلم يستطع أن يرد عليها شيئًا، فلما أفاق ،قال : أنا بريء ممن برئ منه رسول الله صلى الله عليه وسلم ، إن رسول الله صلى الله عليه وسلم برئ من الصالقة، والحالقة، والشاقة.((متفق عليه)) «الصالقة»: التي ترفع صوتها بالنياحة والندب. والحالقة : التي تحلق رأسها عند المصيبة الشاقة :التي تشق ثوبها.', '(My father) Abu Musa got seriously ill and lost his consciousness. His head was in the lap of a woman of the family and she began to wail. When Abu Musa recovered his consciousness, he said: "I am innocent of those from whom Messenger of Allah (ﷺ) is innocent. Verily, the Messenger of Allah (ﷺ) declared himself free of (the responsibility) for a woman who wails, shaves her head and tears up her clothes.".', null, 'Abu Burdah (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1659', 'Riyad as-Salihin 1659', 'ریاض الصالحین 1659', null, 'حَكَى أبو بردة رضي الله عنه أنّ أباه أبا موسى الأشعري رضي الله عنه مَرض مرضًا شديدًا فأغمي عليه، وكانت رأسه في حِجْر امرأةٍ من أهله، فصاحت ونَدَبَتْه، فلم يستطع أن يَرُدَّ عليها شيئًا بسبب إغمائه.

فلما أفاق قال: إنه بريءٌ ممن بَرِئَ منه رسول الله صلى الله عليه وسلم، وإنه صلى الله عليه وسلم قد بَرِئَ من:

الصالقة: وهي الرافعة صوتها عند المصيبة. 

والحالقة: وهي التي تَحلق شعرها عند المصيبة.

والشاقة: وهي التي تَشقُّ ثوبها عند المصيبة. 

لأنها من أمور الجاهلية، بل أمر بالصبر عند المصائب، واحتساب أجرها على الله.', 'النهي عن شَقِّ الثوب، وحَلْق الشعر، ورفع الصوت عند وقوع المصائب، وأن ذلك من كبائر الذنوب.
الحزن والبكاء دون نياحةٍ ورَفْعِ صوتٍ ليس محرّمًا، فهو لا ينافي الصبر على قضاء الله، وإنما هو رحمة.
تحريم التسخُّط من أقدار الله المؤلمة بالقول أو الفعل.
وجوب الصبر عند وقوع المصائب.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/4849', false),
(21660, 2, 218, 1660, 'hadith', 'عن المغيرة بن شعبة رضي الله عنه قال :سمعت رسول الله صلى الله عليه وسلم يقول «من نِيح عليه، فإنه يُعذب بما نِيح عليه يوم القيامة».', 'I heard the Messenger of Allah (ﷺ) saying, "He who allows (others) to wail over his death, will be punished for it on the Day of Resurrection.".', 'المغيرة بن شعبة رضي الله عنه', 'Al-Mughirah bin Shu''bah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1660', 'Riyad as-Salihin 1660', 'ریاض الصالحین 1660', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21661, 2, 218, 1661, 'hadith', 'عن أم عطية نَُسيبة -بضم النون وفتحها- رضي الله عنها قالت : أخذ علينا رسول الله صلى الله عليه وسلم عند البيعة أن لا ننوح.', 'At the time of giving the pledge of allegiance, the Messenger of Allah (ﷺ) took from us an oath that we would not wail..', 'أم عطية نَُسيبة -بضم النون وفتحها- رضي الله عنها', 'Umm ''Atiyyah (May Allah be pleased with her) said:', 'صحيح', 'رياض الصالحين 1661', 'Riyad as-Salihin 1661', 'ریاض الصالحین 1661', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21662, 2, 218, 1662, 'hadith', 'عن النعمان بن بشير رضي الله عنه قال: أغمي على عبد الله بن رواحة رضي الله عنه فجعلت أخته تبكي، وتقول: واجبلاه، وا كذا وا كذا: تعدد عليه فقال حين أفاق: ما قلت شيئًا ألا قيل لي :أنت كذلك؟!.', 'When ''Abdullah bin Rawahah (May Allah be pleased with him) became unconscious, his sister began to weep and shout: "Alas! For the mountain among men. Alas! for such and such (mentioning his virtuous qualities)." When he recovered his consciousness, he said: "I was asked (disapprovingly, by the angels) about everything you said concerning me whether I am as you said.".', 'النعمان بن بشير رضي الله عنه', 'An-Nu''man bin Bashir (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1662', 'Riyad as-Salihin 1662', 'ریاض الصالحین 1662', 'رواه البخاري', 'أخبر النعمان بن بشير رضي الله عنهما أن عبد الله بن رواحة رضي الله عنه أصيب بمرض وأغمي عليه بسبب شِدَّة المرض، فلما رأته أخته رضي الله عنها على تلك الحال ظنت أنه قد مات، فجعلت تبكي وتندب وتقول واجَبَلاهُ" أي أنه- رضي الله عنه- كان لها كالجبل تأوي إليه عند طروق الحوادث فتعتصم به، ومستندًا تستند إليه في أمورها و تذكره بمحاسنه وشمائله على طريقة أهل الجاهلية، فلما أفاق من غيبوبته أخبرها عما حصل له، وأنه قيل له: أأنت جبل يلجؤون إليك، أأنت كذا وكذا كما يصفونك، فكل ما عددته من صفات أُخبر بها رضي الله عنه في غيبوبته، وذلك على سبيل التَّهكم، والوعيد الشديد، وجاء في رواية أنه لما مات لم تندبه واتعظت بذلك.', 'النهي عن الندب للميت وغيره، وخاصة إذا كان بصفات ليست في المندوب، وهو إساءة له؛ لأنه يُقرَّع على ذلك ويُلام عليه.
الميت يعذب بنوح أهله عليه، أي يتألم ويتضايق بعد حال موته.
تحريم ادعاء صفات ليست في المَرء، سواء من قبل نفسه أو من قبل غيره.', 'واجَبَلاهُ : أي أن الميت لها كالجبل.
تُعَدِّدُ عليه : تذكر صفاته الحميدة على طريقة أهل الجاهلية.
شيئًا : من الصِفات التي ذكرتيها.
قِيل لي : الظاهر أن القائل هم الملائكة.
أنت كذلك : أي : أنت كذلك كما يَصِفُون؟', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8927', false),
(21663, 2, 218, 1663, 'hadith', 'عن ابن عمر رضي الله عنهما قال: اشتكى سعد بن عبادة رضي الله عنه شكوى فأتاه رسول الله صلى الله عليه وسلم يعوده مع عبد الرحمن بن عوف، وسعد بن أبي وقاص، وعبد الله بن مسعود رضي الله عنهم، فلما دخل عليه، وجده في غشية فقال: "أقضي؟" قالوا: لا يا رسول الله فبكى رسول الله صلى الله عليه وسلم فلما رأى القوم بكاء النبي صلى الله عليه وسلم بكوا، قال: "ألا تسمعون؟ إن الله لا يُعذب بدمع العين، ولا بحزن القلب، ولكن يعذب بهذا" وأشار إلى لسانه "أو يرحم".', 'The Messenger of Allah (ﷺ) visited Sa''d bin ''Ubadah during his illness. He was accompanied by ''Abdur-Rahman bin ''Auf, Sa''d bin Abu Waqqas and ''Abdullah bin Mas''ud (May Allah be pleased with them). When they entered his house, they found him unconscious. The Messenger of Allah asked, "Has he died?" They replied: "No, O Messenger of Allah." Hearing this the Messenger of Allah (ﷺ) began to weep. When his Companions saw this, they also began to weep too. He said, "Listen attentively: Allah does not punish for the shedding of tears or the grief of the heart, but takes to task or show mercy because of the utterances of this (and he pointed to his tongue).".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1663', 'Riyad as-Salihin 1663', 'ریاض الصالحین 1663', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21664, 2, 218, 1664, 'hadith', 'عن أبي مالك الأشعري رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «النائحة إذا لم تتب قبل موتها تقام يوم القيامة وعليها سربال من قطران، ودرع من جرب».', 'The Messenger of Allah (ﷺ) said, "If the wailing woman does not repent before she dies, she will be made to stand on the Day of Resurrection wearing a garment of pitch and a garment of scabies (Allah knows the nature thereof).".', 'أبي مالك الأشعري رضي الله عنه', 'Abu Malik Al-Ash''ari (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1664', 'Riyad as-Salihin 1664', 'ریاض الصالحین 1664', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21665, 2, 218, 1665, 'hadith', 'عن أسيد بن أبي أسيد التابعي عن امرأة من المبايعات قالت: كان فيما أخذ علينا رسول الله صلى الله عليه وسلم، في المعروف الذي أخذ علينا أن لا نعصيه فيه: أن لا نخمش وجهًا، ولا ندعو ويلا، ولا نشق جيبًا، وأن لا ننشر شعرًا".', 'A woman who had taken a pledge of allegiance at the hand of the Messenger of Allah (ﷺ) said: "Among the matters in respect of which we gave the Messenger of Allah (ﷺ) the pledge not to disobey him in any Ma''ruf .', null, 'Asid bin Abu Usaid', 'صحيح', 'رياض الصالحين 1665', 'Riyad as-Salihin 1665', 'ریاض الصالحین 1665', 'رواه أبو داود بإسناد حسن', 'كان النبي -عليه الصلاة والسلام- يأخذ العهد من الصحابيات عند المبايعة بأن لا يعصينه، ومن ذلك: ألا تخدش المرأة وجهها، أو تضرب وجهها، أو تضرب خدها، ولا ترفع صوتها بالنياحة المنهي عنها، ولا تمزق ثيابها، وألا تنفش شعرها وتمزقه عند نزول المصائب.', 'أن هذه الأفعال من خصال الجاهلية، وأنها من النياحة المنهي عنها.
صوت المرأة ليس بعورة، إذا لم يكن فيه خضوع بالقول كما نهى الله سبحانه النساء عن ذلك.
جهالة الصحابي لا تَقدح في صحة الحديث.', 'المُبَايِعَات : أي اللواتي بايعن النبي -صلى الله عليه وسلم- على السَّمع والطاعة.
لا نَخْمِشَ : لا نَخْدِش.
ولا نَدْعُوَ وَيْلًا : أي: لا نقول عند المصيبة ويلاه، ونحو ذلك من ألفاظ النياحة، والوَيل: الحزن، والعذاب، والهلاك.
جَيْبَا : من القميص ونحوه: ما يدخل منه الرأس عند لُبْسِه.
نَنْشُرَ شَعْرًا : ننفُش ونُمَزق، وهو من فعل النساء غالبا عند المصائب.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8929', false),
(21666, 2, 218, 1666, 'hadith', 'عن أبي موسى رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «ما من ميت يموت، فيقوم باكيهم، فيقول: واجبلاه، وأسيداه، أو نحو ذلك إلا وكل به ملكان يلهزانه: أهكذا كنت؟!". رواه الترمذي وقال حديث حسن. «اللَّهْزُ»: الدَّفْعُ بِجُمْعِ اليَدِ فِي الصَّدْرِ.', 'The Messenger of Allah (ﷺ) said, "If anyone dies and the mourner gets up and says: ''Alas! For the mountain among men. Alas! For the chief ...'' and such like, Allah will put two angels in charge of him who will beat on the breast and ask him (disapproving): ''Were you like that?'' ".', 'أبي موسى رضي الله عنه', 'Abu Musa (May Allah be pleased with him) said:', 'حسن', 'رياض الصالحين 1666', 'Riyad as-Salihin 1666', 'ریاض الصالحین 1666', null, 'أن المسلم إذا مات، وقام أحد يبكي عليه وينوح ويخبر بأن هذا الميت بالنسبة له أو لها كالجبل تأوي إليه عند الشدائد، وأنه كان له سنداً وملجأ، أو نحو ذلك؛ إلا جاء ملكان للميت يدفعانه في صدره ويسألانه سؤال المتهكم: هل أنت كما قيل؟', 'النهي عن النَّدب والنياحة على الميت، وأن ذلك مما يسبب له الأذى.', 'واجَبَلاهُ : أي أن النائحة تشبه الميت بالجبل بالنسبة لها.
واسَيِّدَاه : المراد بالسِّيد هنا: السَّند والملجَأ.
يَلْهَزَانِه : الدفع بِجَمْع اليَد في الصدر، أي ويده مجموعة مضمومة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8917', false),
(21667, 2, 218, 1667, 'hadith', 'عن أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : «اثنان في الناس هما بهم كفر: الطعن في النسب، والنياحة على الميت».', 'The Messenger of Allah (ﷺ) said, "Two things are signs of disbelief on the part of those who indulge in them: Slandering one''s lineage and wailing over the dead.".', 'أبي هريرة رضي الله عنه', 'Abu Hurairah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1667', 'Riyad as-Salihin 1667', 'ریاض الصالحین 1667', 'رواه مسلم', 'يُخْبِرُ النبيُّ صلى الله عليه وسلم عن خصلَتَين في الناس من أعمال الكفار، وأخلاق الجاهلية، وهما: 

الأولى: الطَّعْن بأنساب الناس وتَنَقُّصُهم والتكبُّر عليهم. 

الثانية: رفع الصوت عند المصيبة تَسَخُّطًا على القَدَر، أو قطع الثياب من شِدّة الجَزَع.', 'الحثُّ على التواضع وعدَم التكبُّر على الناس.
وجوب الصبر على المصيبة وعدم التسخُّط.
هذه الأعمال من الكُفْر الأصغر، وليس مَن قام به شُعْبةٌ من شُعَب الكُفْر يكون كافرًا الكفر المُخْرِج من المِلّة حتى يقومَ به الكفرُ الأكبر.
نهي الإسلام عن كلِّ ما يؤدِّي إلى الفُرْقَة بين المسلمين من الطعن في الأنساب وغيرها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6361', false),
(21668, 2, 218, 1668, 'hadith', 'عن عائشة رضي الله عنها قالت: سأل رسول الله صلى الله عليه وسلم أناس عن الكهان، فقال: "ليسوا بشيء" فقالوا: يا رسول الله إنهم يحدثونا أحيانًا بشيء، فيكون حقًا؟ فقال رسول الله صلى الله عليه وسلم : "تلك الكلمة من الحق يخطفها الجني. فيقرها في أذن وليه، فيخلطون معها مائة كذبة" ((متفق عليه)). وفي رواية للبخاري عن عائشة رضي الله عنها أنها سمعت رسول الله صلى الله عليه وسلم يقول: "إن الملائكة تنزل في العَنان -وهو السحاب-. فتذكر الأمر قضي في السماء، فيسترق الشيطان السمع، فيسمعه، فيوحيه إلى الكهان، فيكذبون معها مائة كذبة من عند أنفسهم" قَولُهُ: «فَيَقُرُّهَا» هو بفتح الياء وضم القاف والراء، أي: يُلْقِيها، «والعَنانِ» بفتح العين.', 'Some people asked the Messenger of Allah (ﷺ) about soothsayers. He (ﷺ) said, "They are of no account." Upon this they said to him, "O Messenger of Allah! But they sometimes make true predictions." Thereupon the Messenger of Allah (ﷺ) said, "That is a word pertaining to truth which a jinn snatches (from the angels) and whispers into the ears of his friend (the soothsayers) who will then mix more than a hundred lies with it.".The narration in Al-Bukhari is: "The angels descend in the clouds and mention matters which has been decreed in heaven; Satan steals a hearing (listens to it stealthily) and communicates it to the soothsayers who tell along with it a hundred lies."', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her) said:', null, 'رياض الصالحين 1668', 'Riyad as-Salihin 1668', 'ریاض الصالحین 1668', null, null, null, null, 'sunnah.com', null, false, null, false),
(21669, 2, 218, 1669, 'hadith', 'عن قبيصة بنت أبي عبيد، عن بعض أزواج النبي صلى الله عليه وسلم، ورضي الله عنها، عن النبي صلى الله عليه وسلم قال: «من أتي عرافًا فسأله عن شيء، فصدقه، لم تقبل له صلاة أربعين يومًا».', 'Narrated Safiyyah, daughter of Abu ''Ubaid, on the authority of some of the wives of the Prophet (ﷺ) who said, "He who goes to one who claims to tell about matters of the Unseen and believes in him, his Salat (prayers) will not be accepted for forty days.".', null, null, 'صحيح', 'رياض الصالحين 1669', 'Riyad as-Salihin 1669', 'ریاض الصالحین 1669', 'رواه مسلم', 'يُحَذِّرُ النبيُّ صلى الله عليه وسلم من إتيان العرّاف -هو اسم عام للكاهن والمُنِّجم والرَّمَّال ونحوهم، ممن يَسْتَدِلُّ على معرفة الغيب بمقدمات يستعملها -، وأنَّ مُجَرَّدَ سؤالِهِ عن شيء من أمور الغيب سيَحْرِمُه الله به ثوابَ صلاته أربعين يومًا؛ وذلك عقوبة له على هذا الإثم والذنب الكبير.', 'تحريم الكَهَانة، والذهاب إلى الكُهان وسؤالهم عن المغيبات.
قد يُحْرَمُ الإنسانُ مِن ثواب الطاعة عقوبة له على فعل المعصية.
يَدْخُلُ في الحديث ما يُسمّى بالأبراج والنظر فيها، وقراءة الكَفِّ والفنجان -ولو على سبيل الاطلاع فقط-؛ لأن ذلك كلَّه من الكهانة ومن دعوى علم الغيب.
إذا كان هذا جزاءَ مَن أتى العَرّاف، فكيف بجزاء العراف نفسه؟
صلاة أربعين يومًا تَقَعُ مُجزئة لا يَجِبُ قضاؤها، ولكن لا ثواب فيها.', null, 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5986', false),
(21670, 2, 218, 1670, 'hadith', 'عن قبيصة بن المخارق رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: «العِيافة، والطِّيَرة، والطرق، من الجبت". ((رواه أبو داود بإسناد حسن)). وقال: «الطَّرْقُ» هُوَ الزَّجْرُ: أيْ زَجْرُ الطَّيْرِ وَهُوَ أنْ يَتَيَمَّنَ أو يَتَشَاءمَ بِطَيَرَانِهِ، فإنْ طَارَ إلَى جِهَةِ اليَمِين، تَيَمَّنَ، وإنْ طَارَ إلَى جِهَةِ اليَسَارِ، تَشَاءمَ. قال أبو داود: «والعِيَافَةُ»: الخَطُّ. قالَ الجَوْهَريُّ في الصِّحَاحِ: الجِبْتُ كَلِمَةٌ تَقَعُ عَلَى الصَّنَمِ وَالكاهِنِ والسَّاحِرِ وَنَحْوِ ذلِكَ.', 'I heard the Messenger of Allah (ﷺ) saying, "The practice of ''Iyafah, the interpretation of omens from the flight of birds, the practice of divination by drawing lines on the ground and taking evil omens are all practices of Al-Jibt (the idol, the diviner, or sorcerer).".', 'قبيصة بن المخارق رضي الله عنه', 'Qabisah bin Al-Mukhariq (May Allah be pleased with him) said:', null, 'رياض الصالحين 1670', 'Riyad as-Salihin 1670', 'ریاض الصالحین 1670', null, null, null, null, 'sunnah.com', null, false, null, false),
(21671, 2, 218, 1671, 'hadith', 'عن ابن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : «من اقتبس علمًا من النجوم، اقتبس شعبة من السحر زاد ما زاد».', 'The Messenger of Allah (ﷺ) said, "He who acquires a branch of the knowledge of astrology, learns a branch of magic (of which he acquires more as long as) he continues to do so.".', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1671', 'Riyad as-Salihin 1671', 'ریاض الصالحین 1671', 'رواه أبو داود بإسناد صحيح', 'يُبَيِّنُ النبيُّ صلى الله عليه وسلم أنَّ مَن تَعَلَّم وأَخَذَ من علم النجوم والأبراج والاستدلال بحركاتها ودخولها وخروجها على الحوادث الأرضية من موت فلان أو حياته أو مرضه، ونحو ذلك مما سيقع في المستقبل، فقد تَعَلَّمَ جزءًا من السحر، وأنه كلَّما أكثر الإنسان هذا العلم فقد أكثر من السحر.', 'تحريم التنجيم الذي هو الإخبار عن المستقبل اعتمادًا على أحوال النجوم؛ لأنه من ادعاء علم الغيب.
أن التنجيم المُحَرَّم من أنواع السحر المنافي للتوحيد، بخلاف النظر في النجوم لمعرفة الاتجاهات أو القِبْلة أو دخول المواسم والشهور فهو مباح.
كلما زاد في تَعَلُّمِه للتنجيم فهو يزيد من تَعَلُّمِ شُعَبِ السحر.
للنجوم ثلاث فوائد ذكرها الله في كتابه: زينة للسماء، وعلامات يهتدى بها، ورجوم للشياطين.', 'من اقتبسَ: من تعلّم.
شعبة: طائفة وقطعة.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/5989', false),
(21672, 2, 218, 1672, 'hadith', 'عن معاوية بن الحكم رضي الله عنه قال: قلت يا رسول الله إني حديث عهد بجاهلية، وقد جاء الله تعالى بالإسلام، وإن منا رجالا يأتون الكهان؟ قال: "فلا تأتهم" قلت: ومنا رجال يتطيرون؟ قال: "ذلك شيء يجدونه في صدورهم، فلا يصدهم" قلت: ومنا رجال يخطون؟ قال: "كان نبي من الأنبياء يخط، فمن وافق خطه، فذاك".', 'I said: "O Messenger of Allah, I have recently emerged from ignorance and Allah has favoured me with Islam. There are still some men among us who visit the soothsayers to consult them (on matters relating to the future)." He (ﷺ) replied, "Do not visit them." I said: "There are some men who are guided by omens." He replied, "These are the ideas which come up in their minds but you should not be influenced by them (i.e., these things) should not prevent them from pursuing their works." I said: "There are some men who practise divination by drawing lines on the ground." The Messenger of Allah (ﷺ) replied, "There was a Prophet who drew lines, the line which agrees with the line drawn by that Prophet would be correct.".', 'معاوية بن الحكم رضي الله عنه', 'Mu''awiyah bin Al-Hakam (May Allah be pleased with him)', 'صحيح', 'رياض الصالحين 1672', 'Riyad as-Salihin 1672', 'ریاض الصالحین 1672', 'رواه مسلم', null, null, null, 'sunnah.com', null, false, null, false),
(21673, 2, 218, 1673, 'hadith', 'عن أبي مسعود البدري رضي الله عنه قال: إن رسول الله صلى الله عليه وسلم «نهى عن ثمن الكلب، ومهر البغي وحُلوان الكاهن».', 'The Messenger of Allah (ﷺ) prohibited the price of a dog, the earning of an prostitute, and the money given to a soothsayer..', 'أبي مسعود البدري رضي الله عنه', 'Abu Mas''ud Al-Badri (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1673', 'Riyad as-Salihin 1673', 'ریاض الصالحین 1673', 'متفق عليه', 'لطلب الرزق طرق كريمة شريفة طيبة، جعلها الله عوضا عن الطرق الخبيثة الدنيئة.
فلما كان في الطرق الأولى كفاية عن الثانية، ولما كانت مفاسد الثانية عظيمة لا يقابلها ما فيها من منفعة، حَرَّم الشرع الطرق الخبيثة التي من جملتها، هذه المعاملات الثلاث.
1- بيع الكلب: فإنه خبيث رجس.
2- وكذلك ما تأخذه الزانية مقابل فجورها، الذي به فساد الدين والدنيا.
3- ومثله ما يأخذه أهل الدجل والتضليل، ممن يدعون معرفة الغيب والتصرف في الكائنات، ويخيلون على الناس-بباطلهم- ليسلبوا أموالهم، فيأكلوها بالباطل.
كل هذه طرق خبيثة محرمة، لا يجوز فعلها، ولا تسليم العوض فيها، وقد أبدلها اللَه بطرق مباحة شريفة.', 'النهي عن بيع الكلب، وتحريم ثمنه، ولا فرق بين المُعلَّم وغيره، وكلب الزرع والماشية وغيره، وإنما يجوز اقتناؤه فقط بهذه الأشياء الثلاثة.
تحريم البغاء وتحريم ما يؤخذ عليه، سواء كان من حُرَةٍ أو أمة، فهو خبيث من عمل خبيث في جميع طرقه.
تحريم الكهانة ونحوها من العرافة، والتنجيم، وضرب الحصى، وتحضير الجن، وتحريم أخذ شيء على هذه الأعمال الشيطانية.
من هذه المنهيات وغيرها، يُعلم أنَّ الشريعة تنهى عن كل ما فيه مضرة وما يترتب عليه من مكاسب.
الكلب غير متقوم، يعني: لو أتلف شخصٌ كلب الصيد أو الحرث أو الماشية فلا قيمة له شرعا؛ أنه لو كان له قيمة لجاز له الثمن، إذ أن القيمة عوض عن العين المتلفة، والثمن عوض عن العين الفائتة عن صاحبها، وهذا هو القول الراجح، ولكن من أتلف كلب غيره لغير عذر فيستحق التعزير.
حفظ العرض أولى من حفظ المال، فلا يجوز اتخاذ الزنا والبغاء مهنة للتكسب وأخذ المال.', 'ثمن : ما يبذل في مقابل الحصول على الشيء.
مهر البغي : الزانية، والبغاء: الطلب، وكثرة استعماله في الفساد، ومهرها، ما تعطاه على الزنا، سمى مهرا، من باب التوسع.
حلوان الكاهن : الحُلوان بضم الحاء، مصدر "حلوته" إذا أعطيته، قال في فتح الباري: وأصله من الحلاوة، شبه بالشيء الحلو، من حيث إنه يؤخذ سهلا بلا مشقة، وأما الكاهن: فهو الذي يدعي علم الأشياء المغيبة المستقبلة، وفي معناه "العراف" و "المنجم" ونحوهما من المشعوذين والدجالين.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/6036', false),
(21674, 2, 218, 1674, 'hadith', 'عن أنس رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم : "لا عدوى ولا طِيَرة ويعجبني الفأل" قالوا: وما الفأل؟ قال: "كلمة طيبة".', 'The Messenger of Allah (ﷺ) said, "Not the transmission of disease of one person to another and no evil omen, but I am pleased with good omens." He was asked: "What is good omen?" He replied, "A good word.".', 'أنس رضي الله عنه', 'Anas (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1674', 'Riyad as-Salihin 1674', 'ریاض الصالحین 1674', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21675, 2, 218, 1675, 'hadith', 'عن ابن عمر رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم : «لا عدوى ولا طِيَرة، وإن كان الشؤم في شيء ففي الدار والمرأة، والفرس».', 'The Messenger of Allah (ﷺ) said, "There is no infection and no evil omen; but if there is anything (that may be a source of trouble) then it could be a house, a horse, and a woman.".', 'ابن عمر رضي الله عنهما', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1675', 'Riyad as-Salihin 1675', 'ریاض الصالحین 1675', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false),
(21676, 2, 218, 1676, 'hadith', 'عن بريدة رضي الله عنه أن النبي صلى الله عليه وسلم كان لا يتطير.', 'The Prophet never took ill omens..', 'بريدة رضي الله عنه', 'Buraidah (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1676', 'Riyad as-Salihin 1676', 'ریاض الصالحین 1676', 'رواه أبو داود بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21677, 2, 218, 1677, 'hadith', 'عن عروة بن عامر رضي الله عنه قال: ذكرت الطِيَرة عند رسول الله صلى الله عليه وسلم فقال: «أحسنها الفأل، ولا ترد مسلمًا فإذا رأى أحدكم ما يكره، فليقل: اللهم لا يأتي بالحسنات إلا أنت، ولا يدفع السيئات إلا أنت، ولا حول ولا قوة إلا بك».', 'When talking of omens was mentioned in the presence of the Messenger of Allah (ﷺ) he said, "The best type of omen is the good omen." He added, "A Muslim should not refrain from anything because of an omen." He (ﷺ) told them, "When any of you sees anything which he dislikes, he should say: ''Allahuma la ya''ti bil-hasanati illa Anta, wa la yadfa''us- sayyi''ati illa Anta, wa la hawla wa la quwwata illa Bika (O Allah ! You Alone bring good things; You Alone avert evil things, and there is no might or power but in You)."''.', 'عروة بن عامر رضي الله عنه', '''Urwah bin ''Amir (May Allah be pleased with him) said:', 'صحيح', 'رياض الصالحين 1677', 'Riyad as-Salihin 1677', 'ریاض الصالحین 1677', 'حديث صحيح رواه أبو داود بإسناد صحيح', null, null, null, 'sunnah.com', null, false, null, false),
(21678, 2, 218, 1678, 'hadith', 'عن ابن عمر رضي الله عنه أن رسول الله صلى الله عليه وسلم قال: «إن الذين يصنعون هذه الصور يعذبون يوم القيامة، يقال لهم: أحيوا ما خلقتم».', 'The Messenger of Allah (ﷺ) said, "Those who draw pictures will be punished on the Day of Resurrection; and it will be said to them: ''Breathe soul into what you have created."''.', 'ابن عمر رضي الله عنه', 'Ibn ''Umar (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1678', 'Riyad as-Salihin 1678', 'ریاض الصالحین 1678', 'متفق عليه', 'أن الذين يصنعون الصُّور -سواء كانت الصورة نحْتًا أو رسْمًا أو تصويرًا فوتوغرافيًّا- مما له روح، كتصوير آدمي أو حيوان، وسواء كانت الصورة ممتهنة أو غير ممتهنة، فإنهم يُعذبون بفعلهم ذلك يوم القيامة؛ لمضاهاتهم خلق الله تعالى ، ويقال لهم: "أَحْيُوا" أوجدوا فيها الروح كما أوجدتم الجَسد "ما خَلَقْتُم" ما صورتم من الصُّور المشابهة لخلق الله تعالى ، فإذا كنتم قد شابهتهم خلق الله تعالى في الصورة، فابعثوا فيها الروح، وهذا من باب التهكم والتقريع والتوبيخ.
وفي الصحيحين من حديث ابن عباس رضي الله عنهما عن النبي صلى الله عليه وسلم : (من صوَّر صورة في الدنيا كُلِّف أن ينفخ فيها الروح يوم القيامة، وليس بنافخ)، وفي رواية البخاري: (من صور صورة فإن الله مُعَذِّبه حتى ينفخ فيها الروح).
قال النووي رحمه الله : "قال العلماء: تصوير صورة الحيوان حرام شديد التحريم، وهو من الكبائر؛ لأنه متوعد عليه بهذا الوعيد الشديد المذكور في الأحاديث، وسواء صنعه بما يمتهن أو بغيره، فصنعته حرام بكل حال؛ لأن فيه مضاهاة لخلق الله تعالى ".', 'النهي الشديد والتحريم الأكيد لصنع الصُّور، وهو مقصور على ذوات الأرواح.
تحريم التصوير بكافة أشكاله، سواء كان يدوياً أو فوتوغرافياً؛ لأن النَّص مطلق، فلا يخصص إلا بدليل، فالتصوير الفوتوغرافي الشمسي من أنواع التصوير المحرم، فهو والتصوير عن طريق النسيج والصبغ بالألوان والصور المجسمة سواء في الحكم، والاختلاف في وسيلة التصوير وآلته لا يقتضي اختلافاً في الحكم، وكذا لا أثر للاختلاف فيما يبذل من جهد في التصوير صعوبة وسهولة في الحكم أيضًا، وإنما المعتبر الصورة فهي محرمة وإن اختلفت وسيلتها وما بذل فيها من جهد.
أن من يصنع الصُّور يُعَذَّب بها يوم القيامة، ويأمرهم أمر تعجيز بنفخ الروح فيما صوَّروا، وأنى لهم ذلك.
إذا اقتضت الحاجة إلى التصوير في التعليم أو تشخيص المرض ونحو ذلك، فإن في الأمر سعة، لكن بشرط ألا تتخذ هدفاً، وغايةً في ذاتها، فإن الضرورات تبيح المحظورات، والضرورة تقدر بقدرها، فما جاوزها إلى حَدِّ المُبَاهَاة والمتعة بالتصوير فذلك حرام.
علة تحريم الصور هي مضاهاة خلق الله -تعالى-.', 'الصُّور : صور ذات الرُّوح.
أَحْيُوا ما خَلَقْتُم : اجعلوا روحًا لما صَنَعْتُم مُشَابِها لخلق الله -تعالى-.', 'sunnah.com', null, true, 'الشرح والفوائد: https://hadeethenc.com/ar/browse/hadith/8947', false),
(21679, 2, 218, 1679, 'hadith', 'عن عائشة رضي الله عنها قالت: قدم رسول الله صلى الله عليه وسلم من سفر وقد سترت سهوة لي بقرام فيه تماثيل فلما رآه رسول الله صلى الله عليه وسلم، تلون وجهه، وقال: «يا عائشة، أشد الناس عذابًا عن الله يوم القيامة الذين يضاهون بخلق الله" قالت: فقطعناه، فجعلنا منه وسادة أو وسادتين. ((متفق عليه)). «القِرامُ» بكسرِ القاف هو: السِّتْرُ. «وَالسَّهْوَةُ» بفتح السينِ المهملة وهي: الصُّفَّةُ تَكُونُ بَيْنَ يَدَيِ البَيْتِ، وقيلَ: هِيَ الطَّاقُ النَّافِذُ في الحائِطِ.', 'The Messenger of Allah (ﷺ) visited me after returning from a journey, and I had a shelf with a thin cloth curtain hanging over it and on which there were portraits. When he saw it, the colour of his face changed (because of anger) and he said, "O ''Aishah! the most grievous torment from Allah on the Day of Resurrection will be for those who imitate (Allah) in the act of His creation." ''Aishah said: We tore it into pieces and made a cushion or two cushions out of that..', 'عائشة رضي الله عنها', '''Aishah (May Allah be pleased with her) said:', null, 'رياض الصالحين 1679', 'Riyad as-Salihin 1679', 'ریاض الصالحین 1679', null, null, null, null, 'sunnah.com', null, false, null, false),
(21680, 2, 218, 1680, 'hadith', 'عن ابن عباس رضي الله عنهما قال: سمعت رسول الله صلى الله عليه وسلم يقول: "كل مصور في النار يجعل له بكل صورة صورها نفس فيعذبه في جهنم" قال ابن عباس: فإن كنت لابد فاعلا، فاصنع الشجر وما لا ورح فيه".', 'I heard the Messenger of Allah (ﷺ) saying, "Every painter will go to Hell, and for every portrait he has made, there will be appointed one who will chastise him in the Hell." Ibn ''Abbas said: If you have to do it, draw pictures of trees and other inanimate things..', 'ابن عباس رضي الله عنهما', 'Ibn ''Abbas (May Allah be pleased with them) said:', 'صحيح', 'رياض الصالحين 1680', 'Riyad as-Salihin 1680', 'ریاض الصالحین 1680', 'متفق عليه', null, null, null, 'sunnah.com', null, false, null, false)
